/**
 * @file Parses an Agent Plugin's tool contribution file: the data half of an executable tool.
 * Name, description, effect class and input schema are declared as reviewable data so the host can
 * list, namespace and validate a tool without running plugin code; only `module` points at code.
 * Pure: no I/O. A file that fails any rule is refused whole, so a plugin never ships half its tools.
 */
import type { PluginContributionParseResult } from '../contribution-loader.js';

/**
 * Declared change class; `write` and `destructive` tools must also disclose affected resources.
 * The mirror of `PluginToolEffect` in `@jini-ai/plugins/host` (agent-plugins may not import it); the
 * projection's contract tool reuses this type, so these two are the only declarations.
 */
export type AgentPluginToolEffect = 'read' | 'write' | 'destructive';

/** One declared tool. `name` is local; the host namespaces it as `p_<plugin>__<name>`. */
export interface AgentPluginToolDescriptor {
  readonly name: string;
  readonly description: string;
  readonly effect: AgentPluginToolEffect;
  /** Plain-JS module inside the plugin root (`.mjs`); containment is checked on disk at import. */
  readonly module: string;
  /** JSON Schema (2020-12) for the tool input; must describe an object. */
  readonly inputSchema: Readonly<Record<string, unknown>>;
}

// Bounds mirror the existing tier-3 tool capture (`@jini-ai/plugins/host` contributions.ts) so one
// plugin tool contract has one set of limits, whichever loader admitted it.
const NAME_PATTERN = /^[a-z][a-z0-9_]{0,63}$/;
const MAX_TOOLS = 128;
const MAX_DESCRIPTION = 8000;
const MAX_MODULE_PATH = 256;
const MAX_SCHEMA_BYTES = 65536;
const EFFECTS: ReadonlySet<unknown> = new Set(['read', 'write', 'destructive']);

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/** Why the input schema is unusable, or undefined. Detaches nothing; the caller copies. @complexity O(s) schema size. */
function schemaProblem(schema: unknown): string | undefined {
  if (!isRecord(schema) || schema.type !== 'object') return 'inputSchema must be a JSON Schema describing an object';
  if (new TextEncoder().encode(JSON.stringify(schema)).byteLength > MAX_SCHEMA_BYTES) return 'inputSchema is larger than 64 KiB';
  return undefined;
}

/** Why a description is unusable, or undefined. @complexity O(1). */
function descriptionProblem(name: string, description: unknown): string | undefined {
  if (typeof description === 'string' && description.trim() && description.length <= MAX_DESCRIPTION) return undefined;
  return `tool '${name}' needs a description of at most ${MAX_DESCRIPTION} characters`;
}

/** Why a module path is unusable here, or undefined; containment is checked on disk at import. @complexity O(1). */
function moduleProblem(name: string, module: unknown): string | undefined {
  if (typeof module === 'string' && module.endsWith('.mjs') && module.length <= MAX_MODULE_PATH) return undefined;
  return `tool '${name}' module must be a .mjs path inside the plugin`;
}

/** Why one declaration's scalar fields are invalid, or undefined. @complexity O(1). */
function fieldProblem(entry: Record<string, unknown>): string | undefined {
  const { name } = entry;
  if (typeof name !== 'string' || !NAME_PATTERN.test(name)) return 'a tool name must be lower snake case, at most 64 characters';
  const effectProblem = EFFECTS.has(entry.effect) ? undefined : `tool '${name}' effect must be read, write or destructive`;
  return descriptionProblem(name, entry.description) ?? effectProblem ?? moduleProblem(name, entry.module);
}

/** One declaration, or why it is refused. Unknown keys are ignored. @complexity O(s) schema size. */
function parseEntry(entry: unknown): AgentPluginToolDescriptor | string {
  if (!isRecord(entry)) return 'every tool declaration must be an object';
  const problem = fieldProblem(entry) ?? schemaProblem(entry.inputSchema);
  if (problem) return problem;
  return Object.freeze({
    name: entry.name as string, description: entry.description as string, effect: entry.effect as AgentPluginToolEffect,
    module: entry.module as string, inputSchema: JSON.parse(JSON.stringify(entry.inputSchema)) as Record<string, unknown>,
  });
}

/** The declaration list from the raw file, or why the file is refused. @complexity O(n) file size. */
function declarations(raw: string): readonly unknown[] | string {
  let value: unknown;
  try { value = JSON.parse(raw); } catch { return 'not valid JSON'; }
  if (!isRecord(value) || value.schemaVersion !== 1) return 'schemaVersion must be 1';
  const { tools } = value;
  if (!Array.isArray(tools) || tools.length === 0 || tools.length > MAX_TOOLS) return `tools must list 1 to ${MAX_TOOLS} declarations`;
  return tools;
}

/**
 * Parses the raw contribution file. A local name declared twice is refused (duplicate id).
 * @param required.raw - The file text as read from a trusted package.
 * @returns Descriptors in declaration order, or the reason the whole file is refused.
 * @complexity O(t^2 + s) for t declarations (t <= 128) and s total schema size.
 */
export function parseAgentPluginToolsFile(required: { readonly raw: string }, _optional: Record<string, never> = {}): PluginContributionParseResult<AgentPluginToolDescriptor> {
  const tools = declarations(required.raw);
  if (typeof tools === 'string') return { ok: false, reason: tools };
  const descriptors: AgentPluginToolDescriptor[] = [];
  for (const entry of tools) {
    const parsed = parseEntry(entry);
    if (typeof parsed === 'string') return { ok: false, reason: parsed };
    if (descriptors.some(existing => existing.name === parsed.name)) return { ok: false, reason: `tool '${parsed.name}' is declared more than once` };
    descriptors.push(parsed);
  }
  return { ok: true, descriptors };
}

src/admin-surfaces/__tests__/surface-han.source:
/**
 * @file Security pins (phase A) for plugin-supplied admin-surface handlers: the handler module is
 * contained and never served, it loads only through the executable trust gate (active, shipped
 * digest, on-disk containment), it may answer only declared actions, its answers are schema-checked
 * and token-scanned before reaching the frame, and disabling the plugin revokes everything it holds.
 */
import { mkdtemp, rm, symlink, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { describe, expect, test } from 'vitest';
import { createIssuedTokenMemories } from '../../lifecycle/tools/capabilities.js';
import { createPluginContributionLoader } from '../../lifecycle/contribution-loader.js';
import { findTrustedPluginPackages, importContainedModule, readTrustedPluginFile, setAgentPluginActivation } from '../../lifecycle/__tests__/test-support.js';
import type { AdminSurfaceCapabilities } from '../surface-capabilities.js';
import { createFakeSurfaceHost } from './surface-support.js';
import { FAKE_TOKEN, installPlugin, WORKSPACE_ID, withWorkspace } from '../../lifecycle/tools/__tests__/support.js';
import {
  createAdminSurfaceActionDispatcher, createAdminSurfaceHandlerHost, defineAdminSurfaceHandlerContribution, parseAdminSurfacesFile, readAdminSurfaceFile, type AdminSurfaceDescriptor, type AdminSurfaceHandlerModule, type LoadedAdminSurfaceHandlers,
} from '../index.js';
import { ADMIN_SURFACE_PLUGIN_DISABLED_MESSAGE } from '../surface-handlers.js';

const FILENAME = 'host-admin-surfaces.json';
const PLUGIN = 'fixture-surface';
const CONTEXT = { workspaceId: WORKSPACE_ID, principalId: 'admin-1', pluginId: PLUGIN, surfaceId: 'settings' };
const input = { type: 'object', properties: { name: { type: 'string', maxLength: 20 } }, required: ['name'] } as const;
const result = { type: 'object', properties: { saved: { type: 'boolean' } }, required: ['saved'] } as const;
const bootstrap = { type: 'object', properties: { accessToken: { type: 'string' } }, required: ['accessToken'] } as const;
const surface = (overrides: Record<string, unknown> = {}) => ({
  id: 'settings', title: 'Settings', entry: 'surface/index.html', files: ['surface/app.mjs'],
  actions: [{ name: 'save', input, result }], handlerModule: 'server/handlers.mjs', connections: [{ id: 'c1' }], ...overrides,
});
const surfacesFile = (overrides: Record<string, unknown> = {}) => JSON.stringify({ schemaVersion: 1, surfaces: [surface(overrides)] });
const reasonFor = (overrides: Record<string, unknown>) => {
  const parsed = parseAdminSurfacesFile({ raw: surfacesFile(overrides) });
  return parsed.ok ? 'accepted' : parsed.reason;
};
function descriptorOf(overrides: Record<string, unknown> = {}): AdminSurfaceDescriptor & { readonly handlerModule: string } {
  const parsed = parseAdminSurfacesFile({ raw: surfacesFile(overrides) });
  if (!parsed.ok) throw new Error(parsed.reason);
  return parsed.descriptors[0] as AdminSurfaceDescriptor & { readonly handlerModule: string };
}
const loaded = (module: AdminSurfaceHandlerModule, overrides: Record<string, unknown> = {}, pluginId = PLUGIN): LoadedAdminSurfaceHandlers => ({ descriptor: descriptorOf(overrides), pluginId, module });
const saveModule = (save: AdminSurfaceHandlerModule['actions'][string]): AdminSurfaceHandlerModule => ({ actions: { save } });

/** A host over typed fake capabilities; records which plugin each capability set was scoped to. */
function hostFor(entries: readonly LoadedAdminSurfaceHandlers[]) {
  const scopes: string[] = [];
  const { log, port } = createFakeSurfaceHost();
  const host = createAdminSurfaceHandlerHost({ hostKind: 'hosted', issuedTokens: createIssuedTokenMemories(), capabilities: (scope) => { scopes.push(scope.pluginId); return port(scope); } });
  const { refusals } = host.sync({ loaded: entries, refusals: [] });
  return { host, refusals, scopes, log };
}
const dispatcherFor = (host: ReturnType<typeof hostFor>['host'], descriptor = descriptorOf()) => createAdminSurfaceActionDispatcher({ descriptor, handlers: host.handlersFor({ pluginId: PLUGIN, surfaceId: descriptor.id }) });

describe('the handler module is contained server code', () => {
  test.each(['../handlers.mjs', '/abs/handlers.mjs', 'server/../../handlers.mjs', '%2e%2e/handlers.mjs', 'server\\handlers.mjs', 'server/handlers.js'])('handlerModule %j is refused', (handlerModule) => {
    expect(reasonFor({ handlerModule })).toBe('surfaces[0].handlerModule must be a plain relative path ending in .mjs');
  });
  test('a handler module that is also a served file is refused', () => {
    expect(reasonFor({ files: ['surface/app.mjs', 'server/handlers.mjs'] })).toBe('surfaces[0].handlerModule is server code and may not also be served to the frame');
  });
  test('every action of a surface with a handler module must declare a result schema', () => {
    expect(reasonFor({ actions: [{ name: 'save', input, result }, { name: 'peek', input }] })).toBe('surfaces[0].actions[1] must declare a result schema when the surface has a handlerModule');
  });
  test('a bootstrap schema without a handler module, or outside the schema subset, is refused', () => {
    expect(reasonFor({ handlerModule: undefined, bootstrap })).toBe('surfaces[0].bootstrap needs a handlerModule that provides it');
    expect(reasonFor({ bootstrap: { type: 'string', pattern: '.*' } })).toBe("surfaces[0].bootstrap uses unsupported keyword 'pattern'");
  });
  test('the handler module is never served to the frame', async () => {
    let reads = 0;
    const served = await readAdminSurfaceFile({ surface: { plugin: { pluginId: PLUGIN, packageRoot: '/nowhere' }, descriptor: descriptorOf() }, path: 'server/handlers.mjs', readFile: async () => { reads += 1; return 'x'; } });
    expect(served).toEqual({ ok: false, reason: 'not-declared' });
    expect(reads).toBe(0);
  });
});

describe('the handler module loads only through the executable trust gate', () => {
  const HANDLERS = 'export default { actions: { async save() { return { saved: true }; } } };\n';
  const loader = createPluginContributionLoader({
    findPackages: (query) => findTrustedPluginPackages(query),
    readFile: ({ plugin, filename }) => readTrustedPluginFile(plugin, filename),
    importModule: ({ plugin, modulePath }) => importContainedModule(plugin, modulePath),
  });
  const definition = defineAdminSurfaceHandlerContribution({ filename: FILENAME });
  const files = { [FILENAME]: surfacesFile(), 'surface/index.html': '<!doctype html>', 'surface/app.mjs': 'export {};', 'server/handlers.mjs': HANDLERS };

  test('an active, bundled plugin loads its handler module', async () => {
    await withWorkspace(async (workspaceRoot) => {
      await installPlugin({ workspaceRoot, pluginId: PLUGIN, files });
      const load = await loader.loadPluginContributions({ workspaceId: WORKSPACE_ID, definition });
      expect(load.refusals).toEqual([]);
      expect(load.items.map((item) => [item.pluginId, item.descriptor.id])).toEqual([[PLUGIN, 'settings']]);
    });
  });
  test('an inactive plugin loads nothing, even when the host asks not to require activation', async () => {
    await withWorkspace(async (workspaceRoot) => {
      await installPlugin({ workspaceRoot, pluginId: PLUGIN, files }, { enabled: false });
      expect(await loader.loadPluginContributions({ workspaceId: WORKSPACE_ID, definition }, { requireActive: false })).toEqual({ items: [], refusals: [] });
    });
  });
  test('a package whose digest is not the shipped one is refused', async () => {
    await withWorkspace(async (workspaceRoot) => {
      await installPlugin({ workspaceRoot, pluginId: PLUGIN, files }, { bundled: false });
      const load = await loader.loadPluginContributions({ workspaceId: WORKSPACE_ID, definition });
      expect(load.items).toEqual([]);
      expect(load.refusals).toEqual([expect.stringMatching(/^admin surface handlers from 'fixture-surface' were not loaded: only plugins shipped with .+ may add admin surface handlers/)]);
    });
  });
  test('a handler module that is a symlink out of the plugin root is refused before import', async () => {
    const outside = await mkdtemp(path.join(tmpdir(), 'surface-outside-'));
    try {
      await writeFile(path.join(outside, 'handlers.mjs'), HANDLERS);
      await withWorkspace(async (workspaceRoot) => {
        const { 'server/handlers.mjs': _omitted, ...rest } = files;
        await installPlugin({ workspaceRoot, pluginId: PLUGIN, files: { ...rest, 'server/keep.json': '{}' } });
        const [verdict] = await findTrustedPluginPackages({ workspaceId: WORKSPACE_ID, filename: FILENAME, contribution: 'x', requireActive: true });
        if (!verdict || !('trusted' in verdict)) throw new Error('fixture package was not trusted');
        await symlink(path.join(outside, 'handlers.mjs'), path.join(verdict.trusted.packageRoot, 'server/handlers.mjs'));
        expect(await loader.loadPluginContributions({ workspaceId: WORKSPACE_ID, definition })).toEqual({ items: [],
          refusals: ["admin surface handlers for 'settings' from 'fixture-surface' were not loaded: module path 'server/handlers.mjs' escapes the plugin root"] });
      });
    } finally { await rm(outside, { recursive: true, force: true }); }
  });
});

describe('the handler module export is checked before admission', () => {
  const definition = defineAdminSurfaceHandlerContribution({ filename: FILENAME });
  const plugin = { pluginId: PLUGIN, packageRoot: '/nowhere' };
  test.each([
    [null, "its module's default export is not an object"],
    [{ bootstrap: async () => ({}) }, "its module's default export needs an actions object of functions"],
    [{ actions: { save: 'not code' } }, "its module's default export needs an actions object of functions"],
    [{ actions: {}, bootstrap: { data: 1 } }, 'bootstrap must be a function'],
  ])('export %j is refused', async (exported, reason) => {
    expect(await definition.load({ plugin, descriptor: descriptorOf(), importModule: async () => ({ exported }) }))
      .toBe(`admin surface handlers for 'settings' from 'fixture-surface' were not loaded: ${reason}`);
  });
  test('an invalid surfaces file refuses every handler, and surfaces without a handler module import nothing', () => {
    expect(definition.parse({ raw: '{' })).toEqual({ ok: false, reason: 'not valid JSON' });
    expect(definition.parse({ raw: surfacesFile({ handlerModule: undefined, connections: undefined }) })).toEqual({ ok: true, descriptors: [] });
  });
});

describe('admission at sync', () => {
  test('a module that exports a handler for an undeclared action is refused whole', () => {
    const { host, refusals } = hostFor([loaded({ actions: { save: async () => ({ saved: true }), purge: async () => ({}) } })]);
    expect(refusals).toEqual(["admin surface handlers for 'settings' from 'fixture-surface' were not loaded: it exports a handler for undeclared action 'purge'"]);
    expect(host.handlersFor({ pluginId: PLUGIN, surfaceId: 'settings' })).toEqual({});
  });
  test('a module that provides bootstrap data the surface declares no schema for is refused', () => {
    const { refusals } = hostFor([loaded({ actions: {}, bootstrap: async () => ({}) })]);
    expect(refusals).toEqual(["admin surface handlers for 'settings' from 'fixture-surface' were not loaded: it exports bootstrap() but the surface declares no bootstrap schema"]);
  });
  test('two loaded handler sets for the same plugin and surface are both refused (ambiguous)', () => {
    const module = saveModule(async () => ({ saved: true }));
    const { host, refusals } = hostFor([loaded(module), loaded(module)]);
    expect(refusals).toEqual(["admin surface handlers for 'settings' from 'fixture-surface' were not loaded: more than one handler module claims this surface"]);
    expect(host.handlersFor({ pluginId: PLUGIN, surfaceId: 'settings' })).toEqual({});
  });
});

describe('dispatch through plugin handlers', () => {
  test('an undeclared action is refused and no plugin code runs', async () => {
    let ran = 0;
    const { host } = hostFor([loaded(saveModule(async () => { ran += 1; return { saved: true }; }))]);
    expect(await dispatcherFor(host).dispatch({ action: 'purge', payload: { name: 'x' }, context: CONTEXT }))
      .toEqual({ ok: false, error: { code: 'action-undeclared', message: 'This surface did not declare that action.', retryable: false } });
    expect(ran).toBe(0);
  });
  test('a result outside the declared result schema never reaches the frame', async () => {
    const { host } = hostFor([loaded(saveModule(async () => ({ saved: 'yes', extra: 'leak' })))]);
    expect(await dispatcherFor(host).dispatch({ action: 'save', payload: { name: 'x' }, context: CONTEXT }))
      .toEqual({ ok: false, error: { code: 'invalid-result', message: 'The host returned a result this surface did not declare.', retryable: false } });
  });
  test('a result that carries an access token the call obtained is withheld', async () => {
    // The result schema admits a `token` string, so only the token scan can stop this answer.
    const overrides = { actions: [{ name: 'save', input, result: { type: 'object', properties: { token: { type: 'string' } } } }] };
    const leaky = saveModule(async ({ capabilities }) => ({ token: await capabilities.connections.getAccessToken({ connectionId: 'c1' }) }));
    const errors: unknown[] = [];
    const { host } = hostFor([loaded(leaky, overrides)]);
    const descriptor = descriptorOf(overrides);
    const dispatcher = createAdminSurfaceActionDispatcher({ descriptor, handlers: host.handlersFor({ pluginId: PLUGIN, surfaceId: 'settings' }) }, { onHandlerError: ({ error }) => errors.push(error) });
    const outcome = await dispatcher.dispatch({ action: 'save', payload: { name: 'x' }, context: CONTEXT });
    expect(outcome).toEqual({ ok: false, error: { code: 'action-failed', message: 'The action failed. Try again; if it keeps failing, check the server log.', retryable: true } });
    expect(JSON.stringify(outcome)).not.toContain(FAKE_TOKEN);
    expect((errors[0] as Error).message).toBe('The plugin tool result was withheld because it contained a connection credential.');
  });
  test('a plugin failure keeps its surface-safe code, but one that mentions an obtained token is replaced', async () => {
    const failing = (withToken: boolean) => saveModule(async ({ capabilities, fail }) => {
      const token = await capabilities.connections.getAccessToken({ connectionId: 'c1' });
      throw fail({ code: 'reconnect-required', message: withToken ? `token ${token} expired` : 'Reconnect the account and retry.' }, { retryable: false });
    });
    const clean = await dispatcherFor(hostFor([loaded(failing(false))]).host).dispatch({ action: 'save', payload: { name: 'x' }, context: CONTEXT });
    expect(clean).toEqual({ ok: false, error: { code: 'reconnect-required', message: 'Reconnect the account and retry.', retryable: false } });
    const leaky = await dispatcherFor(hostFor([loaded(failing(true))]).host).dispatch({ action: 'save', payload: { name: 'x' }, context: CONTEXT });
    expect(leaky).toEqual({ ok: false, error: { code: 'action-failed', message: 'The action failed. Try again; if it keeps failing, check the server log.', retryable: true } });
  });
  test('a token the module kept from an EARLIER call is withheld (was reported, now fixed)', async () => {
    // The scan remembers every token the surface generation obtained, so module state cannot carry
    // one across calls. Bootstrap data may carry a token by design; the later action may not.
    let kept = '';
    const overrides = { actions: [{ name: 'save', input, result: { type: 'object', properties: { token: { type: 'string' } } } }], bootstrap };
    const module: AdminSurfaceHandlerModule = {
      actions: { save: async () => ({ token: kept }) },
      bootstrap: async ({ capabilities }) => { kept = await capabilities.connections.getAccessToken({ connectionId: 'c1' }); return { accessToken: 'unrelated' }; },
    };
    const { host } = hostFor([loaded(module, overrides)]);
    await host.bootstrapData({ context: CONTEXT });
    expect(await createAdminSurfaceActionDispatcher({ descriptor: descriptorOf(overrides), handlers: host.handlersFor({ pluginId: PLUGIN, surfaceId: 'settings' }) })
      .dispatch({ action: 'save', payload: { name: 'x' }, context: CONTEXT })).toEqual({ ok: false,
      error: { code: 'action-failed', message: 'The action failed. Try again; if it keeps failing, check the server log.', retryable: true } });
  });
  test('a failure code outside the id format is not passed through', async () => {
    const { host } = hostFor([loaded(saveModule(async ({ fail }) => { throw fail({ code: 'Action Undeclared!', message: 'spoof' }); }))]);
    expect(await dispatcherFor(host).dispatch({ action: 'save', payload: { name: 'x' }, context: CONTEXT }))
      .toEqual({ ok: false, error: { code: 'action-failed', message: 'The action failed. Try again; if it keeps failing, check the server log.', retryable: true } });
  });
  test('capabilities and context are scoped to the plugin that was loaded, not the ids the caller passes', async () => {
    const seen: unknown[] = [];
    const { host, scopes } = hostFor([loaded(saveModule(async ({ context, capabilities }) => { seen.push(context); await capabilities.limiter.check({ key: 'k' }); return { saved: true }; }))]);
    await dispatcherFor(host).dispatch({ action: 'save', payload: { name: 'x' }, context: { ...CONTEXT, pluginId: 'other-plugin', surfaceId: 'other' } });
    expect(scopes).toEqual([PLUGIN]);
    expect(seen).toEqual([{ workspaceId: WORKSPACE_ID, principalId: 'admin-1', pluginId: PLUGIN, surfaceId: 'settings', connectionIds: ['c1'], hostKind: 'hosted' }]);
  });
});

describe('bootstrap data', () => {
  const withBootstrap = (provide: AdminSurfaceHandlerModule['bootstrap']) => hostFor([loaded({ actions: {}, ...(provide ? { bootstrap: provide } : {}) }, { actions: [], bootstrap })]).host;
  test('bootstrap data is the one channel that may carry a short-lived access token, and only inside its schema', async () => {
    const host = withBootstrap(async ({ capabilities }) => ({ accessToken: await capabilities.connections.getAccessToken({ connectionId: 'c1' }) }));
    expect(await host.bootstrapData({ context: CONTEXT })).toEqual({ accessToken: FAKE_TOKEN });
  });
  test('bootstrap data outside its schema is refused without echoing the value', async () => {
    const host = withBootstrap(async () => ({ accessToken: 'abc', refreshToken: 'secret-value' }));
    const error = await host.bootstrapData({ context: CONTEXT }).catch((caught: unknown) => caught as Error);
    expect(error).toBeInstanceOf(Error);
    expect((error as Error).message).toBe('Admin surface \'settings\' from \'fixture-surface\' returned bootstrap data outside its declared schema ($ has an undeclared property "refreshToken"); report it to the plugin author.');
    expect((error as Error).message).not.toContain('secret-value');
  });
  test('a bootstrap failure that mentions an obtained token is replaced', async () => {
    const host = withBootstrap(async ({ capabilities }) => { throw new Error(`denied ${await capabilities.connections.getAccessToken({ connectionId: 'c1' })}`); });
    await expect(host.bootstrapData({ context: CONTEXT })).rejects.toThrow(/^The plugin tool failed and its error was withheld because it contained a connection credential\.$/);
  });
  test('bootstrap data without a signed-in admin gets no access token and the host port is never asked', async () => {
    const { host, log } = hostFor([loaded({ actions: {}, bootstrap: async ({ capabilities }) => ({ accessToken: await capabilities.connections.getAccessToken({ connectionId: 'c1' }) }) },
      { actions: [], bootstrap })]);
    const { principalId: _signedIn, ...anonymous } = CONTEXT;
    await expect(host.bootstrapData({ context: anonymous }))
      .rejects.toThrow('Connection access needs a signed-in admin. Open the surface from an authenticated admin page and retry.');
    expect(log.tokenRequests).toEqual([]);
  });
  test('a surface without a bootstrap provider starts with null', async () => {
    expect(await withBootstrap(undefined).bootstrapData({ context: CONTEXT })).toBeNull();
  });
});

describe('disabling the plugin revokes its handlers', () => {
  test('a retained handler is refused, a retained capability is revoked and bootstrap data stops', async () => {
    let retained: AdminSurfaceCapabilities | undefined;
    const module: AdminSurfaceHandlerModule = {
      actions: { save: async ({ capabilities }) => { retained = capabilities; return { saved: true }; } },
      bootstrap: async () => ({ accessToken: 'a' }),
    };
    const { host } = hostFor([loaded(module, { bootstrap })]);
    const descriptor = descriptorOf({ bootstrap });
    const handlers = host.handlersFor({ pluginId: PLUGIN, surfaceId: 'settings' });
    expect(await createAdminSurfaceActionDispatcher({ descriptor, handlers }).dispatch({ action: 'save', payload: { name: 'x' }, context: CONTEXT })).toEqual({ ok: true, result: { saved: true } });

    expect(host.sync({ loaded: [], refusals: [] })).toEqual({ refusals: [] });
    expect(await createAdminSurfaceActionDispatcher({ descriptor, handlers }).dispatch({ action: 'save', payload: { name: 'x' }, context: CONTEXT }))
      .toEqual({ ok: false, error: { code: 'plugin-disabled', message: 'This plugin was disabled, so its admin surface cannot act. Re-enable the plugin and reopen the surface.', retryable: false } });
    await expect(retained!.connections.getAccessToken({ connectionId: 'c1' })).rejects.toThrow('This plugin tool was disabled; its capabilities are revoked. Re-enable the plugin and retry.');
    expect(host.handlersFor({ pluginId: PLUGIN, surfaceId: 'settings' })).toEqual({});
    expect(await host.bootstrapData({ context: CONTEXT })).toBeNull();
  });
  test('re-syncing an unchanged module keeps its handlers live; a changed module revokes the old ones', async () => {
    const module = saveModule(async () => ({ saved: true }));
    const { host } = hostFor([loaded(module)]);
    const first = host.handlersFor({ pluginId: PLUGIN, surfaceId: 'settings' });
    host.sync({ loaded: [loaded(module)], refusals: [] });
    expect(host.handlersFor({ pluginId: PLUGIN, surfaceId: 'settings' })).toBe(first);
    host.sync({ loaded: [loaded(saveModule(async () => ({ saved: false })))], refusals: [] });
    await expect(first.save!({ payload: { name: 'x' }, context: CONTEXT })).rejects.toThrow(ADMIN_SURFACE_PLUGIN_DISABLED_MESSAGE);
    expect(await host.handlersFor({ pluginId: PLUGIN, surfaceId: 'settings' }).save!({ payload: { name: 'x' }, context: CONTEXT })).toEqual({ saved: false });
  });
  test('a real deactivation removes the handlers on the next load and sync', async () => {
    const loader = createPluginContributionLoader({
      findPackages: (query) => findTrustedPluginPackages(query),
      readFile: ({ plugin, filename }) => readTrustedPluginFile(plugin, filename),
      importModule: ({ plugin, modulePath }) => importContainedModule(plugin, modulePath),
    });
    const definition = defineAdminSurfaceHandlerContribution({ filename: FILENAME });
    await withWorkspace(async (workspaceRoot) => {
      await installPlugin({ workspaceRoot, pluginId: PLUGIN, files: { [FILENAME]: surfacesFile(), 'surface/index.html': '<!doctype html>', 'surface/app.mjs': 'export {};',
        'server/handlers.mjs': 'export default { actions: { async save() { return { saved: true }; } } };\n' } });
      const host = createAdminSurfaceHandlerHost({ hostKind: 'hosted', issuedTokens: createIssuedTokenMemories(), capabilities: createFakeSurfaceHost().port });
      host.sync(await loader.loadPluginContributions({ workspaceId: WORKSPACE_ID, definition }).then(({ items, refusals }) => ({ loaded: items, refusals })));
      expect(Object.keys(host.handlersFor({ pluginId: PLUGIN, surfaceId: 'settings' }))).toEqual(['save']);
      await setAgentPluginActivation({ workspaceRoot, pluginId: PLUGIN, enabled: false, actor: 'test' }, { origin: 'bundled' });
      host.sync(await loader.loadPluginContributions({ workspaceId: WORKSPACE_ID, definition }).then(({ items, refusals }) => ({ loaded: items, refusals })));
      expect(host.handlersFor({ pluginId: PLUGIN, surfaceId: 'settings' })).toEqual({});
    });
  });
});

describe('the host kind is the host\'s, never the caller\'s or the plugin\'s', () => {
  const desktopHost = (module: AdminSurfaceHandlerModule, overrides: Record<string, unknown> = {}) => {
    const host = createAdminSurfaceHandlerHost({ hostKind: 'desktop', issuedTokens: createIssuedTokenMemories(), capabilities: createFakeSurfaceHost().port });
    host.sync({ loaded: [loaded(module, overrides)], refusals: [] });
    return host;
  };
  test('a handler sees the host-supplied hostKind even when the caller context claims another', async () => {
    const seen: string[] = [];
    const host = desktopHost(saveModule(async ({ context }) => { seen.push(context.hostKind); return { saved: true }; }));
    // Malformed input on purpose: a caller context carrying a hostKind field the host must override.
    await dispatcherFor(host).dispatch({ action: 'save', payload: { name: 'x' }, context: { ...CONTEXT, hostKind: 'hosted' } as typeof CONTEXT });
    expect(seen).toEqual(['desktop']);
  });
  test('a bootstrap provider sees the host-supplied hostKind', async () => {
    const host = desktopHost({ actions: {}, bootstrap: async ({ context }) => ({ accessToken: context.hostKind }) }, { actions: [], bootstrap });
    expect(await host.bootstrapData({ context: CONTEXT })).toEqual({ accessToken: 'desktop' });
  });
  test('a hostKind outside hosted and desktop is refused when the host is built', () => {
    // Malformed input on purpose: a JavaScript host passing an unchecked config value.
    expect(() => createAdminSurfaceHandlerHost({ hostKind: 'mobile' as 'hosted', issuedTokens: createIssuedTokenMemories(), capabilities: createFakeSurfaceHost().port }))
      .toThrow("createAdminSurfaceHandlerHost: hostKind must be 'hosted' or 'desktop'.");
  });
});

src/admin-surfaces/__tests__/surface-cap.source:
/**
 * @file Security pins (phase A) for the admin-surface capability ports: a handler reaches only the
 * connections, start parameters, callback fields and public config its surface declared; account
 * actions need a signed-in admin; host answers are cut back to the token-free port shape; callback
 * fields are taken once, by their owner, only after a deposit; plugin state is JSON-only, capped,
 * isolated per plugin and never stores an obtained token; disabling the plugin revokes every port.
 */
import { describe, expect, test } from 'vitest';
import { REVOKED_MESSAGE, createIssuedTokenMemories } from '../../lifecycle/tools/capabilities.js';
import { FAKE_TOKEN, WORKSPACE_ID } from '../../lifecycle/tools/__tests__/support.js';
import {
  ADMIN_SURFACE_ACTION_INTENTS, ADMIN_SURFACE_STATE_LIMITS, createAdminSurfaceActionDispatcher, createAdminSurfaceCallbackInbox, createAdminSurfaceHandlerHost, parseAdminSurfacesFile, type AdminSurfaceCapabilityDeclarations, type AdminSurfaceDescriptor, type AdminSurfaceHandlerModule,
} from '../index.js';
import { openAdminSurfaceCapabilitySession, STATE_CREDENTIAL_MESSAGE, type AdminSurfaceConnectionStatus } from '../surface-capabilities.js';
import { createFakeSurfaceHost } from './surface-support.js';

const PLUGIN = 'acme-office';
const DECLARED: AdminSurfaceCapabilityDeclarations = {
  connections: [{ id: 'account', startParams: ['selection-mode'], callbackFields: ['picked-id'] }],
  publicConfig: ['ACME_APP_ID'],
};
const UNDECLARED_CONNECTION = "This admin surface does not declare connection 'other', so its handlers cannot use it. Declare it in the surface's connections.";
const NO_ACTOR = 'Account actions need a signed-in admin. Open the surface from an authenticated admin page and retry.';
const NO_TOKEN_ACTOR = 'Connection access needs a signed-in admin. Open the surface from an authenticated admin page and retry.';

function open(optional: { readonly actorId?: string | null; readonly pluginId?: string; readonly live?: () => boolean } = {}) {
  const fake = createFakeSurfaceHost({ config: { ACME_APP_ID: 'app-123', ACME_OTHER: 'not-declared' }, status: { connectionRef: 'ref-must-not-leak' } });
  const actorId = optional.actorId === undefined ? 'admin-1' : optional.actorId;
  const session = openAdminSurfaceCapabilitySession(
    { capabilities: fake.port({ pluginId: optional.pluginId ?? PLUGIN, workspaceId: WORKSPACE_ID }), isLive: optional.live ?? (() => true), declared: DECLARED, issued: new Set() },
    actorId === null ? {} : { actorId },
  );
  return { ...fake, ...session };
}

const surfaceRaw = (extra: Record<string, unknown>) => JSON.stringify({ schemaVersion: 1, surfaces: [{
  id: 'settings', title: 'Settings', entry: 'surface/index.html', handlerModule: 'server/handlers.mjs',
  actions: [{ name: 'save', input: { type: 'object' }, result: { type: 'object', properties: { empty: { type: 'boolean' } } } }], ...extra,
}] });
const reasonFor = (extra: Record<string, unknown>) => {
  const parsed = parseAdminSurfacesFile({ raw: surfaceRaw(extra) });
  return parsed.ok ? 'accepted' : parsed.reason;
};

describe('the surfaces file is the allowlist', () => {
  test('connections or publicConfig without a handler module are refused', () => {
    expect(reasonFor({ handlerModule: undefined, connections: [{ id: 'account' }] })).toBe('surfaces[0].connections needs a handlerModule that uses it');
    expect(reasonFor({ handlerModule: undefined, publicConfig: ['ACME_APP_ID'] })).toBe('surfaces[0].publicConfig needs a handlerModule that uses it');
  });
  test.each(['ACME_CLIENT_SECRET', 'ACCESS_TOKEN', 'DB_PASSWORD', 'SIGNING_KEY', 'PRIVATE_KEY', 'SESSION_KEY', 'ACME_CREDENTIALS'])('a secret-named public config %s is refused', (name) => {
    expect(reasonFor({ publicConfig: ['ACME_APP_ID', name] })).toBe('surfaces[0].publicConfig[1] names a secret; public config may only hold values that are safe to show');
  });
  test('a public config name that is not an environment-style name is refused', () => {
    expect(reasonFor({ publicConfig: ['acme_app_id'] })).toBe('surfaces[0].publicConfig[0] must be a unique name matching ^[A-Z][A-Z0-9_]{0,63}$');
  });
  test('a connection id, a duplicate connection, or a start parameter name outside the allowed shape is refused', () => {
    expect(reasonFor({ connections: [{ id: '../account' }] })).toBe('surfaces[0].connections[0].id must be a short connection id');
    expect(reasonFor({ connections: [{ id: 'account' }, { id: 'account' }] })).toBe("surfaces[0].connections[1].id 'account' is declared twice");
    expect(reasonFor({ connections: [{ id: 'account', startParams: ['a b'] }] })).toBe('surfaces[0].connections[0].startParams[0] must be a unique name matching ^[A-Za-z0-9_.-]{1,64}$');
    expect(reasonFor({ connections: [{ id: 'account', callbackFields: ['x', 'x'] }] })).toBe('surfaces[0].connections[0].callbackFields[1] must be a unique name matching ^[A-Za-z][A-Za-z0-9_.-]{0,63}$');
  });
  test('a callback field the loopback receiver would refuse (not starting with a letter) is refused', () => {
    expect(reasonFor({ connections: [{ id: 'account', callbackFields: ['_picked'] }] })).toBe('surfaces[0].connections[0].callbackFields[0] must be a unique name matching ^[A-Za-z][A-Za-z0-9_.-]{0,63}$');
  });
  test('connections that are not an array of objects are refused', () => {
    expect(reasonFor({ connections: { id: 'account' } })).toBe('surfaces[0].connections must be an array of at most 4');
    expect(reasonFor({ connections: ['account'] })).toBe('surfaces[0].connections[0] must be an object');
  });
  test('declared lists are parsed onto the descriptor', () => {
    const parsed = parseAdminSurfacesFile({ raw: surfaceRaw({ connections: [{ id: 'account', startParams: ['selection-mode'] }], publicConfig: ['ACME_APP_ID'] }) });
    expect(parsed.ok && parsed.descriptors[0]).toMatchObject({ connections: [{ id: 'account', startParams: ['selection-mode'], callbackFields: [] }], publicConfig: ['ACME_APP_ID'] });
  });
});

describe('connections: only declared ones, account actions only for an admin', () => {
  test.each([
    ['getAccessToken', (s: ReturnType<typeof open>) => s.capabilities.connections.getAccessToken({ connectionId: 'other' })],
    ['status', (s: ReturnType<typeof open>) => s.capabilities.connections.status({ connectionId: 'other' })],
    ['begin', (s: ReturnType<typeof open>) => s.capabilities.connections.begin({ connectionId: 'other', action: 'connect' })],
    ['confirmSwitch', (s: ReturnType<typeof open>) => s.capabilities.connections.confirmSwitch({ connectionId: 'other' })],
    ['cancelSwitch', (s: ReturnType<typeof open>) => s.capabilities.connections.cancelSwitch({ connectionId: 'other' })],
    ['disconnect', (s: ReturnType<typeof open>) => s.capabilities.connections.disconnect({ connectionId: 'other' })],
    ['takeCallbackFields', (s: ReturnType<typeof open>) => s.capabilities.connections.takeCallbackFields({ connectionId: 'other', attemptId: 'attempt-1' })],
  ])('%s refuses an undeclared connection before the host sees it', async (_name, call) => {
    const session = open();
    await expect(call(session)).rejects.toThrow(UNDECLARED_CONNECTION);
    expect([...session.log.calls, ...session.log.tokenRequests]).toEqual([]);
  });
  test.each([
    ['begin', (s: ReturnType<typeof open>) => s.capabilities.connections.begin({ connectionId: 'account', action: 'connect' })],
    ['confirmSwitch', (s: ReturnType<typeof open>) => s.capabilities.connections.confirmSwitch({ connectionId: 'account' })],
    ['cancelSwitch', (s: ReturnType<typeof open>) => s.capabilities.connections.cancelSwitch({ connectionId: 'account' })],
    ['disconnect', (s: ReturnType<typeof open>) => s.capabilities.connections.disconnect({ connectionId: 'account' })],
  ])('%s refuses without a signed-in admin', async (_name, call) => {
    const session = open({ actorId: null });
    await expect(call(session)).rejects.toThrow(NO_ACTOR);
    expect(session.log.calls).toEqual([]);
  });
  test('getAccessToken refuses without a signed-in admin and the host issues no token', async () => {
    const session = open({ actorId: null });
    await expect(session.capabilities.connections.getAccessToken({ connectionId: 'account' })).rejects.toThrow(NO_TOKEN_ACTOR);
    expect(session.log.tokenRequests).toEqual([]);
  });
  test('an undeclared start parameter, a non-string value or an unknown action is refused before the host sees it', async () => {
    const session = open();
    await expect(session.capabilities.connections.begin({ connectionId: 'account', action: 'connect' }, { startParams: { prompt: 'none' } }))
      .rejects.toThrow("Start parameter 'prompt' is not declared for connection 'account' on this admin surface.");
    // Malformed input on purpose: plugin code is untyped JavaScript.
    await expect(session.capabilities.connections.begin({ connectionId: 'account', action: 'connect' }, { startParams: { 'selection-mode': 1 } as never }))
      .rejects.toThrow("Start parameter 'selection-mode' must be a string of at most 2048 characters.");
    await expect(session.capabilities.connections.begin({ connectionId: 'account', action: 'delete-everything' as never }))
      .rejects.toThrow("Account action 'delete-everything' is not one of connect, reconnect, switch, add-scopes.");
    await expect(session.capabilities.connections.begin({ connectionId: 'account', action: 'add-scopes' }, { scopeSetIds: ['../all'] }))
      .rejects.toThrow('Scope sets must be at most 16 short ids.');
    expect(session.log.calls).toEqual([]);
  });
  test('a declared start parameter reaches the host, and the answer is cut back to the port shape (no connection ref)', async () => {
    const session = open();
    const started = await session.capabilities.connections.begin({ connectionId: 'account', action: 'add-scopes' }, { scopeSetIds: ['files'], startParams: { 'selection-mode': 'one' } });
    expect(started).toStrictEqual({ authorizationUrl: 'https://auth.example.test/authorize?state=s1', attemptId: 'attempt-1', expiresAt: '2026-10-20T00:10:00.000Z' });
    expect(session.log.calls).toEqual([`${PLUGIN}:begin:{"connectionId":"account","action":"add-scopes","scopeSetIds":["files"],"startParams":{"selection-mode":"one"}}`]);
  });
  test('every account action maps explicitly onto an API-connection start intent', () => {
    expect(ADMIN_SURFACE_ACTION_INTENTS).toStrictEqual({ connect: 'connect', reconnect: 'connect', 'add-scopes': 'connect', switch: 'switch-account' });
  });
  test('confirmSwitch and cancelSwitch answers are cut back to the token-free status fields', async () => {
    const session = open();
    const status = { connectionId: 'account', status: 'connected', accountLabel: 'person@example.test', grantedScopeSetIds: ['files'], pendingSwitchAccountLabel: null, lastSignInAttempt: null };
    expect(await session.capabilities.connections.confirmSwitch({ connectionId: 'account' })).toStrictEqual(status);
    expect(await session.capabilities.connections.cancelSwitch({ connectionId: 'account' })).toStrictEqual(status);
    expect(session.log.calls).toEqual([`${PLUGIN}:confirmSwitch:{"connectionId":"account"}`, `${PLUGIN}:cancelSwitch:{"connectionId":"account"}`]);
  });
  test('start parameters that are not an object are refused', async () => {
    // Malformed input on purpose: plugin code is untyped JavaScript.
    await expect(open().capabilities.connections.begin({ connectionId: 'account', action: 'connect' }, { startParams: ['selection-mode'] as never }))
      .rejects.toThrow('Start parameters must be an object of strings.');
  });
  test('status and disconnect answers carry only the token-free status fields and the honest revocation outcome', async () => {
    const session = open();
    const status = { connectionId: 'account', status: 'connected', accountLabel: 'person@example.test', grantedScopeSetIds: ['files'], pendingSwitchAccountLabel: null, lastSignInAttempt: null };
    expect(await session.capabilities.connections.status({ connectionId: 'account' })).toStrictEqual(status);
    expect(await session.capabilities.connections.disconnect({ connectionId: 'account' })).toStrictEqual({ ...status, status: 'revocation-pending', revocation: 'pending' });
  });
});

describe('the last sign-in attempt carries host-supplied safe codes only', () => {
  const statusWith = async (lastSignInAttempt: unknown) => {
    // Malformed input on purpose where the attempt carries provider text: the host port is untyped at run time.
    const fake = createFakeSurfaceHost({ status: { lastSignInAttempt: lastSignInAttempt as AdminSurfaceConnectionStatus['lastSignInAttempt'] } });
    const session = openAdminSurfaceCapabilitySession({ capabilities: fake.port({ pluginId: PLUGIN, workspaceId: WORKSPACE_ID }), isLive: () => true, declared: DECLARED, issued: new Set() }, { actorId: 'admin-1' });
    return (await session.capabilities.connections.status({ connectionId: 'account' })).lastSignInAttempt;
  };
  test('safe codes are copied through, and only code and nextAction', async () => {
    expect(await statusWith({ code: 'access-denied', nextAction: 'reconnect', description: 'The user denied access' })).toStrictEqual({ code: 'access-denied', nextAction: 'reconnect' });
  });
  test.each([
    ['provider text as the code', { code: 'The user denied access', nextAction: 'reconnect' }],
    ['provider text as the next action', { code: 'access-denied', nextAction: 'Ask your administrator' }],
    ['a missing next action', { code: 'access-denied' }],
    ['an over-long code', { code: 'a'.repeat(65), nextAction: 'reconnect' }],
    ['a string instead of an object', 'access_denied: denied'],
    ['no attempt from a host that predates the field', undefined],
  ])('%s becomes null, never passed through', async (_label, attempt) => {
    expect(await statusWith(attempt)).toBeNull();
  });
});

describe('callback fields: once, by their owner, after a completed sign-in, declared fields only', () => {
  const key = { workspaceId: WORKSPACE_ID, pluginId: PLUGIN, connectionId: 'account', attemptId: 'attempt-1' };
  test('nothing is returned before the host deposits a completed sign-in', async () => {
    expect(await open().capabilities.connections.takeCallbackFields({ connectionId: 'account', attemptId: 'attempt-1' })).toBeNull();
  });
  test('the owner takes only declared fields, exactly once', async () => {
    const session = open();
    session.inbox.deposit({ ...key, fields: { 'picked-id': 'res-1', 'undeclared-extra': 'x' } });
    expect(await session.capabilities.connections.takeCallbackFields({ connectionId: 'account', attemptId: 'attempt-1' })).toStrictEqual({ 'picked-id': 'res-1' });
    expect(await session.capabilities.connections.takeCallbackFields({ connectionId: 'account', attemptId: 'attempt-1' })).toBeNull();
  });
  test('another plugin with the same connection and attempt ids gets nothing and does not consume the owner\'s fields', () => {
    const inbox = createAdminSurfaceCallbackInbox({ now: () => 0 });
    inbox.deposit({ ...key, fields: { 'picked-id': 'res-1' } });
    expect(inbox.take({ ...key, pluginId: 'other-plugin' })).toBeNull();
    expect(inbox.take({ ...key, workspaceId: 'other-workspace' })).toBeNull();
    expect(inbox.take(key)).toStrictEqual({ 'picked-id': 'res-1' });
  });
  test('a deposit expires after the ten-minute sign-in attempt lifetime', () => {
    let now = 0;
    const inbox = createAdminSurfaceCallbackInbox({ now: () => now });
    inbox.deposit({ ...key, attemptId: 'kept', fields: {} });
    inbox.deposit({ ...key, fields: { 'picked-id': 'old' } });
    now = 10 * 60 * 1000 - 1;
    expect(inbox.take({ ...key, attemptId: 'kept' })).toStrictEqual({});
    now = 10 * 60 * 1000;
    expect(inbox.take(key)).toBeNull();
  });
  test('a full inbox (256 entries) drops the oldest first', () => {
    const inbox = createAdminSurfaceCallbackInbox({ now: () => 0 });
    for (let index = 0; index <= 256; index += 1) inbox.deposit({ ...key, attemptId: `a${index}`, fields: {} });
    expect([inbox.take({ ...key, attemptId: 'a0' }), inbox.take({ ...key, attemptId: 'a1' }), inbox.take({ ...key, attemptId: 'a256' })]).toEqual([null, {}, {}]);
  });
  test('an attempt id outside the opaque-id shape is refused', async () => {
    await expect(open().capabilities.connections.takeCallbackFields({ connectionId: 'account', attemptId: 'a/../b' })).rejects.toThrow('The sign-in attempt id is not valid; start the sign-in again.');
  });
});

describe('plugin state and public config', () => {
  test.each([
    ['undefined', undefined], ['NaN', Number.NaN], ['a Date', new Date(0)], ['a function', () => 1], ['a nested undefined', { a: [undefined] }],
  ])('a value holding %s is refused (JSON-only)', async (_name, value) => {
    // Malformed input on purpose: plugin code is untyped JavaScript.
    await expect(open().capabilities.state.set({ key: 'selection', value: value as never }))
      .rejects.toThrow('A settings value must be plain JSON data (no undefined, functions, NaN or class instances).');
  });
  test('a value nested deeper than the cap, or larger than the byte cap, is refused', async () => {
    let deep: unknown = 'leaf';
    for (let level = 0; level < ADMIN_SURFACE_STATE_LIMITS.maxDepth + 1; level += 1) deep = [deep];
    const session = open();
    await expect(session.capabilities.state.set({ key: 'selection', value: deep as never })).rejects.toThrow('A settings value must be plain JSON data');
    await expect(session.capabilities.state.set({ key: 'selection', value: 'é'.repeat(ADMIN_SURFACE_STATE_LIMITS.maxValueBytes / 2) }))
      .rejects.toThrow('A settings value may be at most 16384 bytes of JSON.');
  });
  test.each(['', '../x', 'a b', 'k'.repeat(129)])('a state key %j outside the short-name shape is refused', async (key) => {
    await expect(open().capabilities.state.get({ key })).rejects.toThrow('A settings key must be a short name of at most 128 characters.');
  });
  test.each(['', '../x', 'a b', 'k'.repeat(129), 7])('set and delete refuse the state key %j before the host sees it', async (key) => {
    const session = open();
    await expect(session.capabilities.state.set({ key: key as string, value: 1 })).rejects.toThrow('A settings key must be a short name of at most 128 characters.');
    await expect(session.capabilities.state.delete({ key: key as string })).rejects.toThrow('A settings key must be a short name of at most 128 characters.');
    expect(session.log.calls).toEqual([]);
  });
  test('a 128-character key with dots, colons, dashes and underscores is accepted', async () => {
    const session = open();
    const key = `a.b:c-d_${'k'.repeat(120)}`;
    await session.capabilities.state.set({ key, value: true });
    expect(await session.capabilities.state.get({ key })).toBe(true);
  });
  test('a value that mentions an access token the call obtained is never stored', async () => {
    const session = open();
    const token = await session.capabilities.connections.getAccessToken({ connectionId: 'account' });
    await expect(session.capabilities.state.set({ key: 'selection', value: { header: `Bearer ${token}` } })).rejects.toThrow(STATE_CREDENTIAL_MESSAGE);
    expect(session.state.size).toBe(0);
  });
  test('a token obtained in an EARLIER call of the same generation is never stored (was reported, now fixed)', async () => {
    const issued = new Set<string>();
    const fake = createFakeSurfaceHost({ config: {}, status: {} });
    const session = () => openAdminSurfaceCapabilitySession({ capabilities: fake.port({ pluginId: PLUGIN, workspaceId: WORKSPACE_ID }), isLive: () => true, declared: DECLARED, issued },
      { actorId: 'admin-1' });
    const token = await session().capabilities.connections.getAccessToken({ connectionId: 'account' });
    await expect(session().capabilities.state.set({ key: 'kept', value: token })).rejects.toThrow(STATE_CREDENTIAL_MESSAGE);
    expect(fake.state.size).toBe(0);
  });
  test('what is stored is the checked copy: changing the object afterwards changes nothing', async () => {
    const session = open();
    const value = { resourceId: 'res-1' };
    await session.capabilities.state.set({ key: 'selection', value });
    value.resourceId = FAKE_TOKEN;
    expect(await session.capabilities.state.get({ key: 'selection' })).toStrictEqual({ resourceId: 'res-1' });
  });
  test('only declared public config is reachable', async () => {
    const session = open();
    expect(await session.capabilities.publicConfig.get({ name: 'ACME_APP_ID' })).toBe('app-123');
    await expect(session.capabilities.publicConfig.get({ name: 'ACME_OTHER' })).rejects.toThrow("This admin surface does not declare public config 'ACME_OTHER'. Declare it in the surface's publicConfig.");
    expect(session.log.calls).toEqual([`${PLUGIN}:publicConfig.get:{"name":"ACME_APP_ID"}`]);
  });
});

describe('plugin isolation and revocation through the handler host', () => {
  const descriptorFor = (): AdminSurfaceDescriptor & { readonly handlerModule: string } => {
    const parsed = parseAdminSurfacesFile({ raw: surfaceRaw({ connections: [{ id: 'account' }] }) });
    if (!parsed.ok) throw new Error(parsed.reason);
    return parsed.descriptors[0] as AdminSurfaceDescriptor & { readonly handlerModule: string };
  };
  const context = (pluginId: string) => ({ workspaceId: WORKSPACE_ID, principalId: 'admin-1', pluginId, surfaceId: 'settings' });

  test('two plugins writing the same state key never see each other\'s value', async () => {
    const fake = createFakeSurfaceHost();
    const writer: AdminSurfaceHandlerModule = { actions: { save: async ({ capabilities, context: { pluginId } }) => { await capabilities.state.set({ key: 'selection', value: pluginId }); return {}; } } };
    const reader: AdminSurfaceHandlerModule = { actions: { save: async ({ capabilities }) => ({ empty: (await capabilities.state.get({ key: 'selection' })) === null }) } };
    const host = createAdminSurfaceHandlerHost({ hostKind: 'hosted', issuedTokens: createIssuedTokenMemories(), capabilities: fake.port });
    host.sync({ loaded: [{ pluginId: 'plugin-a', descriptor: descriptorFor(), module: writer }, { pluginId: 'plugin-b', descriptor: descriptorFor(), module: reader }], refusals: [] });
    const dispatch = (pluginId: string) => createAdminSurfaceActionDispatcher({ descriptor: descriptorFor(), handlers: host.handlersFor({ pluginId, surfaceId: 'settings' }) })
      .dispatch({ action: 'save', payload: {}, context: context(pluginId) });
    expect(await dispatch('plugin-a')).toEqual({ ok: true, result: {} });
    expect(await dispatch('plugin-b')).toEqual({ ok: true, result: { empty: true } });
  });

  test('every port a module kept is revoked once the plugin is disabled', async () => {
    let kept: Parameters<AdminSurfaceHandlerModule['actions'][string]>[0]['capabilities'] | undefined;
    const host = createAdminSurfaceHandlerHost({ hostKind: 'hosted', issuedTokens: createIssuedTokenMemories(), capabilities: createFakeSurfaceHost().port });
    host.sync({ loaded: [{ pluginId: PLUGIN, descriptor: descriptorFor(), module: { actions: { save: async ({ capabilities }) => { kept = capabilities; return {}; } } } }], refusals: [] });
    await createAdminSurfaceActionDispatcher({ descriptor: descriptorFor(), handlers: host.handlersFor({ pluginId: PLUGIN, surfaceId: 'settings' }) }).dispatch({ action: 'save', payload: {}, context: context(PLUGIN) });
    host.sync({ loaded: [], refusals: [] });
    const calls = [
      kept!.connections.status({ connectionId: 'account' }), kept!.connections.begin({ connectionId: 'account', action: 'connect' }),
      kept!.connections.disconnect({ connectionId: 'account' }), kept!.connections.takeCallbackFields({ connectionId: 'account', attemptId: 'a1' }),
      kept!.state.set({ key: 'k', value: 1 }), kept!.state.get({ key: 'k' }), kept!.state.delete({ key: 'k' }), kept!.publicConfig.get({ name: 'X' }),
    ];
    for (const call of calls) await expect(call).rejects.toThrow(REVOKED_MESSAGE);
  });
});

