/**
 * @file Security pins for admin surfaces (phase A): path containment, the sandbox attribute, the CSP
 * string and its extra-source validation, the host-page message gate, the server-side dispatcher's
 * refusals, the surface client's trust rules and the bootstrap's no-store/expiry contract.
 */
import { mkdtemp, mkdir, rm, symlink, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { afterEach, describe, expect, test, vi } from 'vitest';
import { PackagePathViolation } from '../../lifecycle/package-paths.js';
import { readTrustedPluginFile } from '../../lifecycle/__tests__/test-support.js';
import {
  adminSurfaceBootstrapHeaders, adminSurfaceFrameAttributes, createAdminSurfaceActionDispatcher, createAdminSurfaceBootstrap, createAdminSurfaceMount, parseAdminSurfacesFile, readAdminSurfaceFile, validateAdminSurfaceMessage, type AdminSurfaceDescriptor, type AdminSurfaceMessageEvent, type AdminSurfaceMountRecord,
} from '../index.js';
import { AdminSurfaceActionError } from '../action-dispatcher.js';
import { adminSurfaceContentSecurityPolicy, adminSurfaceFileHeaders, isAdminSurfaceBootstrapCurrent } from '../sandbox.js';
import { createAdminSurfaceClient, type AdminSurfaceIncomingMessage } from '../surface-client.js';

const input = { type: 'object', properties: { name: { type: 'string', maxLength: 20 } }, required: ['name'] } as const;
const surface = (overrides: Record<string, unknown> = {}) => ({ id: 'settings', title: 'Settings', entry: 'surface/index.html', files: ['surface/app.mjs'], actions: [{ name: 'save', input }], ...overrides });
const file = (surfaces: unknown[]) => JSON.stringify({ schemaVersion: 1, surfaces });
function parseOne(overrides: Record<string, unknown> = {}): AdminSurfaceDescriptor {
  const parsed = parseAdminSurfacesFile({ raw: file([surface(overrides)]) });
  if (!parsed.ok) throw new Error(parsed.reason);
  return parsed.descriptors[0]!;
}
const reasonFor = (overrides: Record<string, unknown>) => {
  const parsed = parseAdminSurfacesFile({ raw: file([surface(overrides)]) });
  return parsed.ok ? 'accepted' : parsed.reason;
};

describe('contained paths', () => {
  test.each(['../index.html', '/abs/index.html', 'surface\\index.html', 'surface//index.html', './index.html', 'surface/../index.html', '%2e%2e/index.html', '.hidden/index.html', 'index.htm'])('entry %j is refused', (entry) => {
    expect(reasonFor({ entry })).toBe('surfaces[0].entry must be a plain relative path ending in .html');
  });
  test.each(['../app.mjs', '/app.mjs', 'app.exe', 'surface/../../app.mjs', 'app.html'])('file %j is refused', (bad) => {
    expect(reasonFor({ files: [bad] })).toBe('surfaces[0].files[0] must be a plain relative path ending in .mjs, .js, .css, .json');
  });
  test('only the entry and declared files are read; anything else is refused without I/O', async () => {
    const reads: string[] = [];
    const loaded = { plugin: { pluginId: 'acme', packageRoot: '/p' }, descriptor: parseOne() };
    const readFile = async ({ filename }: { readonly filename: string }) => { reads.push(filename); return 'body'; };
    expect(await readAdminSurfaceFile({ surface: loaded, path: 'surface/../secret.json', readFile })).toEqual({ ok: false, reason: 'not-declared' });
    expect(await readAdminSurfaceFile({ surface: loaded, path: 'plugin.json', readFile })).toEqual({ ok: false, reason: 'not-declared' });
    expect(reads).toEqual([]);
    expect(await readAdminSurfaceFile({ surface: loaded, path: 'surface/app.mjs', readFile })).toMatchObject({ ok: true, body: 'body' });
    expect(reads).toEqual(['surface/app.mjs']);
  });
});

test('a declared file that is a symlink out of the plugin root is refused on disk', async () => {
  const base = await mkdtemp(path.join(tmpdir(), 'admin-surface-escape-'));
  try {
    const root = path.join(base, 'plugin');
    await mkdir(path.join(root, 'surface'), { recursive: true });
    await writeFile(path.join(base, 'outside.mjs'), 'export const secret = 1;');
    await symlink(path.join(base, 'outside.mjs'), path.join(root, 'surface/app.mjs'));
    const loaded = { plugin: { pluginId: 'acme', packageRoot: root }, descriptor: parseOne() };
    await expect(readAdminSurfaceFile({ surface: loaded, path: 'surface/app.mjs', readFile: ({ plugin, filename }) => readTrustedPluginFile(plugin, filename) })).rejects.toBeInstanceOf(PackagePathViolation);
  } finally {
    await rm(base, { recursive: true, force: true });
  }
});

describe('sandboxed iframe contract', () => {
  test('sandbox is exactly allow-scripts, never allow-same-origin', () => {
    const attributes = adminSurfaceFrameAttributes({ src: '/s/index.html', title: 'Settings' });
    expect(attributes).toEqual({ src: '/s/index.html', title: 'Settings', sandbox: 'allow-scripts', referrerPolicy: 'no-referrer' });
  });
  test('the default CSP is strict and closes network and framing', () => {
    expect(adminSurfaceContentSecurityPolicy({ descriptor: parseOne() })).toBe(
      "default-src 'none'; script-src 'self'; style-src 'self'; img-src 'self'; font-src 'self'; connect-src 'none'; frame-src 'none'; form-action 'none'; base-uri 'none'; frame-ancestors 'self'; sandbox allow-scripts",
    );
  });
  test('declared, validated origins extend only their own directive', () => {
    const descriptor = parseOne({ csp: { 'connect-src': ['https://api.example.com'], 'script-src': ['https://cdn.example.com:8443'] } });
    expect(adminSurfaceContentSecurityPolicy({ descriptor })).toBe(
      "default-src 'none'; script-src 'self' https://cdn.example.com:8443; style-src 'self'; img-src 'self'; font-src 'self'; connect-src https://api.example.com; frame-src 'none'; form-action 'none'; base-uri 'none'; frame-ancestors 'self'; sandbox allow-scripts",
    );
  });
  test.each([
    'http://api.example.com', 'https://*.example.com', '*', "'unsafe-inline'", "'unsafe-eval'", 'https://api.example.com/path',
    'https://api.example.com:443', 'https://user@api.example.com', 'https://127.0.0.1', 'data:', 'https://API.example.com',
    'https://api.example.com; script-src *', 'https://api.example.com ', 'blob:',
  ])('extra CSP source %j refuses the file', (source) => {
    expect(reasonFor({ csp: { 'connect-src': [source] } })).toBe("surfaces[0].csp['connect-src'] may only list bare https origins (no wildcards, paths or keywords)");
  });
  test.each(['default-src', 'sandbox', 'frame-ancestors', 'form-action', '__proto__'])('directive %j cannot be extended', (directive) => {
    expect(reasonFor({ csp: JSON.parse(`{${JSON.stringify(directive)}:["https://a.example.com"]}`) })).toBe(`surfaces[0].csp may not extend '${directive}'`);
  });
  test('served script files get the CSP, nosniff and a credential-free CORS grant; html gets no CORS', () => {
    const descriptor = parseOne();
    const csp = adminSurfaceContentSecurityPolicy({ descriptor });
    expect(adminSurfaceFileHeaders({ descriptor, path: 'surface/app.mjs' })).toEqual({
      'Content-Type': 'text/javascript; charset=utf-8', 'Content-Security-Policy': csp, 'X-Content-Type-Options': 'nosniff',
      'Referrer-Policy': 'no-referrer', 'Cache-Control': 'no-cache', 'Access-Control-Allow-Origin': '*',
    });
    expect(adminSurfaceFileHeaders({ descriptor, path: 'surface/index.html' })).not.toHaveProperty('Access-Control-Allow-Origin');
  });
});

describe('action schemas are a closed subset', () => {
  test.each([
    [{ type: 'string', pattern: '.*' }, "surfaces[0].actions[0].input uses unsupported keyword 'pattern'"],
    [{ type: 'object', additionalProperties: true }, 'surfaces[0].actions[0].input additionalProperties may only be false (objects are closed)'],
    [{ properties: {} }, 'surfaces[0].actions[0].input must declare a supported type'],
    [{ type: 'object', required: ['missing'] }, 'surfaces[0].actions[0].input required must list declared properties'],
  ])('declaration %j is refused', (schema, reason) => {
    expect(reasonFor({ actions: [{ name: 'save', input: schema }] })).toBe(reason);
  });
});

describe('host-page message gate', () => {
  const frame = {};
  const mount: AdminSurfaceMountRecord = { mountId: 'nonce-1', frame, descriptor: parseOne() };
  const request = (overrides: Record<string, unknown> = {}) => ({ protocol: 'jini.admin-surface', version: 1, kind: 'action-request', mountId: 'nonce-1', requestId: 'r1', action: 'save', payload: { name: 'x' }, ...overrides });
  const event = (overrides: Partial<AdminSurfaceMessageEvent> = {}, data = request()): AdminSurfaceMessageEvent => ({ origin: 'null', source: frame, data, ...overrides });

  test('a well-formed request from this mount passes', () => {
    expect(validateAdminSurfaceMessage({ event: event(), mount })).toEqual({ ok: true, request: request() });
  });
  test('a different origin is ignored', () => {
    expect(validateAdminSurfaceMessage({ event: event({ origin: 'https://evil.example.com' }), mount })).toEqual({ ok: false, ignored: 'origin-mismatch' });
  });
  test('a mount record cannot widen the accepted origin beyond "null"', () => {
    // Malformed input on purpose: a record carrying an extra origin field the gate must ignore.
    const widened = { ...mount, expectedOrigin: 'https://surfaces.example.com' };
    expect(validateAdminSurfaceMessage({ event: event({ origin: 'https://surfaces.example.com' }), mount: widened })).toEqual({ ok: false, ignored: 'origin-mismatch' });
  });
  test('another sandboxed frame (same "null" origin, different window) is ignored', () => {
    expect(validateAdminSurfaceMessage({ event: event({ source: {} }), mount })).toEqual({ ok: false, ignored: 'source-mismatch' });
  });
  test('a wrong mount nonce is ignored', () => {
    expect(validateAdminSurfaceMessage({ event: event({}, request({ mountId: 'nonce-2' })), mount })).toEqual({ ok: false, ignored: 'mount-mismatch' });
  });
  test('a malformed envelope is ignored', () => {
    expect(validateAdminSurfaceMessage({ event: event({}, request({ requestId: 'has space' })), mount })).toEqual({ ok: false, ignored: 'not-an-action-request' });
  });
  test('an undeclared action is refused with a response', () => {
    const verdict = validateAdminSurfaceMessage({ event: event({}, request({ action: 'delete-everything' })), mount });
    expect(verdict).toMatchObject({ ok: false, refused: 'action-undeclared', response: { kind: 'action-response', mountId: 'nonce-1', requestId: 'r1', ok: false, error: { code: 'action-undeclared' } } });
  });
  test('a payload outside the schema is refused without echoing the value', () => {
    const verdict = validateAdminSurfaceMessage({ event: event({}, request({ payload: { name: 'x', token: 'SECRET-VALUE' } })), mount });
    expect(verdict).toMatchObject({ ok: false, refused: 'invalid-payload' });
    expect(JSON.stringify(verdict)).not.toContain('SECRET-VALUE');
  });
  test('an oversized payload is refused', () => {
    const verdict = validateAdminSurfaceMessage({ event: event({}, request({ payload: { name: 'x'.repeat(70_000) } })), mount });
    expect(verdict).toMatchObject({ ok: false, refused: 'invalid-payload', response: { error: { message: 'The request is too large.' } } });
  });
});

describe('server-side dispatcher', () => {
  const descriptor = parseOne({ actions: [{ name: 'save', input, result: { type: 'object', properties: { saved: { type: 'boolean' } }, required: ['saved'] } }] });
  test('an undeclared action is refused even when a handler exists for it', async () => {
    const handler = vi.fn(async () => ({ saved: true }));
    const { dispatch } = createAdminSurfaceActionDispatcher({ descriptor, handlers: { save: handler, purge: handler } });
    expect(await dispatch({ action: 'purge', payload: {}, context: {} })).toEqual({ ok: false, error: { code: 'action-undeclared', message: 'This surface did not declare that action.', retryable: false } });
    expect(handler).not.toHaveBeenCalled();
  });
  test.each(['__proto__', 'constructor', 'toString'])('prototype key %j never resolves a handler', async (action) => {
    const { dispatch } = createAdminSurfaceActionDispatcher({ descriptor: { id: 's', actions: [{ name: action, input }] }, handlers: {} });
    expect(await dispatch({ action, payload: { name: 'x' }, context: {} })).toMatchObject({ ok: false, error: { code: 'action-unavailable' } });
  });
  test('an oversized payload is refused server-side too and never reaches the handler', async () => {
    const handler = vi.fn(async () => ({ saved: true }));
    const { dispatch } = createAdminSurfaceActionDispatcher({ descriptor, handlers: { save: handler } });
    expect(await dispatch({ action: 'save', payload: { name: 'x'.repeat(70_000) }, context: {} }))
      .toEqual({ ok: false, error: { code: 'invalid-payload', message: 'The request is too large.', retryable: false } });
    expect(handler).not.toHaveBeenCalled();
  });
  test('an invalid payload never reaches the handler', async () => {
    const handler = vi.fn(async () => ({ saved: true }));
    const { dispatch } = createAdminSurfaceActionDispatcher({ descriptor, handlers: { save: handler } });
    expect(await dispatch({ action: 'save', payload: { name: 42 }, context: {} })).toMatchObject({ ok: false, error: { code: 'invalid-payload', message: "The request does not match the action's input: $.name must be a string." } });
    expect(handler).not.toHaveBeenCalled();
  });
  test('a handler throw is reported to the host but never leaks to the surface', async () => {
    const heard: unknown[] = [];
    const { dispatch } = createAdminSurfaceActionDispatcher({ descriptor, handlers: { save: async () => { throw new Error('db password=hunter2'); } } }, { onHandlerError: ({ error }) => heard.push(error) });
    const outcome = await dispatch({ action: 'save', payload: { name: 'x' }, context: {} });
    expect(outcome).toEqual({ ok: false, error: { code: 'action-failed', message: 'The action failed. Try again; if it keeps failing, check the server log.', retryable: true } });
    expect(heard).toHaveLength(1);
  });
  test('an AdminSurfaceActionError carries its surface-safe code and message', async () => {
    const { dispatch } = createAdminSurfaceActionDispatcher({ descriptor, handlers: { save: async () => { throw new AdminSurfaceActionError({ code: 'reconnect-required', message: 'Reconnect the account.' }, { retryable: false }); } } });
    expect(await dispatch({ action: 'save', payload: { name: 'x' }, context: {} })).toEqual({ ok: false, error: { code: 'reconnect-required', message: 'Reconnect the account.', retryable: false } });
  });
  test('a result outside the declared result schema is refused', async () => {
    const { dispatch } = createAdminSurfaceActionDispatcher({ descriptor, handlers: { save: async () => ({ saved: true, accessToken: 'SECRET' }) } });
    expect(await dispatch({ action: 'save', payload: { name: 'x' }, context: {} })).toEqual({ ok: false, error: { code: 'invalid-result', message: 'The host returned a result this surface did not declare.', retryable: false } });
  });
});

describe('surface client trust rules', () => {
  afterEach(() => vi.useRealTimers());
  function harness() {
    const parent = { posted: [] as Array<{ message: unknown; targetOrigin: string }>, postMessage(message: unknown, targetOrigin: string) { this.posted.push({ message, targetOrigin }); } };
    let deliver: (event: AdminSurfaceIncomingMessage) => void = () => {};
    const client = createAdminSurfaceClient({ parent, listen: (handler) => { deliver = handler; return () => { deliver = () => {}; }; } }, { timeoutMs: 1000, nowMs: () => 5_000 });
    const init = (overrides: Partial<AdminSurfaceIncomingMessage> = {}, data: Record<string, unknown> = {}) => deliver({ origin: 'https://host.example.com', source: parent, data: { protocol: 'jini.admin-surface', version: 1, kind: 'init', mountId: 'nonce-1', ...data }, ...overrides });
    const respond = (overrides: Partial<AdminSurfaceIncomingMessage> = {}, data: Record<string, unknown> = {}) => deliver({ origin: 'https://host.example.com', source: parent, data: { protocol: 'jini.admin-surface', version: 1, kind: 'action-response', mountId: 'nonce-1', requestId: 'r1', ok: true, result: 'done', ...data }, ...overrides });
    return { parent, client, init, respond };
  }
  test('posts requests to the host origin learned from init, never "*"', async () => {
    const { parent, client, init, respond } = harness();
    init();
    const pending = client.call({ action: 'save', payload: { name: 'x' } });
    await Promise.resolve();
    expect(parent.posted).toEqual([{ message: { protocol: 'jini.admin-surface', version: 1, kind: 'action-request', mountId: 'nonce-1', requestId: 'r1', action: 'save', payload: { name: 'x' } }, targetOrigin: 'https://host.example.com' }]);
    respond();
    await expect(pending).resolves.toBe('done');
  });
  test('init from a window other than the parent is ignored, and a second init cannot replace the first', async () => {
    const { parent, client, init } = harness();
    init({ source: {}, origin: 'https://evil.example.com' }, { mountId: 'evil' });
    init();
    init({ origin: 'https://evil.example.com' }, { mountId: 'evil' });
    const pending = client.call({ action: 'save', payload: {} });
    await Promise.resolve();
    expect(parent.posted[0]).toMatchObject({ targetOrigin: 'https://host.example.com', message: { mountId: 'nonce-1' } });
    client.close();
    await expect(pending).rejects.toMatchObject({ code: 'closed', retryable: false });
  });
  test('responses with the wrong origin, source, mount or shape do not settle the call', async () => {
    vi.useFakeTimers();
    const { client, init, respond } = harness();
    init();
    const pending = client.call({ action: 'save', payload: {} });
    await Promise.resolve();
    respond({ origin: 'https://evil.example.com' });
    respond({ source: {} });
    respond({}, { mountId: 'nonce-2' });
    respond({}, { ok: false, error: { code: 'x' } });
    respond({}, { requestId: 'r9' });
    vi.advanceTimersByTime(1000);
    await expect(pending).rejects.toMatchObject({ name: 'AdminSurfaceCallError', code: 'timeout', retryable: true });
  });
  test('bootstrap data is withheld once expired', () => {
    const fresh = harness();
    fresh.init({}, { bootstrap: { surfaceId: 's', issuedAt: 0, expiresAt: 5_001, data: { token: 't' } } });
    expect(fresh.client.bootstrap()).toEqual({ token: 't' });
    const stale = harness();
    stale.init({}, { bootstrap: { surfaceId: 's', issuedAt: 0, expiresAt: 5_000, data: { token: 't' } } });
    expect(stale.client.bootstrap()).toBeUndefined();
  });
});

describe('bootstrap and mount', () => {
  test('bootstrap headers forbid caching', () => {
    expect(adminSurfaceBootstrapHeaders()).toEqual({ 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store', Pragma: 'no-cache', 'X-Content-Type-Options': 'nosniff' });
  });
  test('the bootstrap expires one minute after issue, and a caller cannot lengthen that', () => {
    const bootstrap = createAdminSurfaceBootstrap({ surfaceId: 's', data: {}, nowMs: 1000 });
    expect(bootstrap).toEqual({ surfaceId: 's', issuedAt: 1000, expiresAt: 61_000, data: {} });
    expect(isAdminSurfaceBootstrapCurrent({ bootstrap, nowMs: 60_999 })).toBe(true);
    expect(isAdminSurfaceBootstrapCurrent({ bootstrap, nowMs: 61_000 })).toBe(false);
    // Malformed input on purpose: the removed ttlMs option, passed untyped, must change nothing.
    const longer = { ttlMs: 300_001 } as unknown as Record<string, never>;
    expect(createAdminSurfaceBootstrap({ surfaceId: 's', data: {}, nowMs: 0 }, longer).expiresAt).toBe(60_000);
  });
  test('each mount gets a fresh 128-bit nonce', () => {
    const a = createAdminSurfaceMount({ surfaceId: 's' });
    const b = createAdminSurfaceMount({ surfaceId: 's' });
    expect(a.mountId).toMatch(/^[0-9a-f]{32}$/);
    expect(a.mountId).not.toBe(b.mountId);
    expect(Object.keys(a).sort()).toEqual(['mountId', 'surfaceId']);
  });
});

src/lifecycle/tools/__tests__/agent-plug.source:
/**
 * @file Security pins for executable Agent Plugin tools (phase A): admission refusals through the real
 * trust gate (inactive, tampered digest, path escape, duplicate id), projection refusals (ambiguous id,
 * undisclosed write, unusable schema), schema refusal of bad input, credential containment of results
 * and errors, destructive confirmation, and revocation on disable.
 */
import { expect, test } from 'vitest';
import { ToolInputError } from '@jini-ai/core';
import { createPluginContributionRegistry, pluginToolIdFor } from '@jini-ai/plugins/host';
import { ISSUED_TOKEN_MEMORY_LIMIT, openCapabilityGate, openCapabilitySession, REVOKED_MESSAGE, WITHHELD_ERROR_MESSAGE, WITHHELD_OUTPUT_MESSAGE, type AgentPluginToolCapabilities, createIssuedTokenMemories } from '../capabilities.js';
import type { LoadedAgentPluginTool } from '../definition.js';
import { createAgentPluginToolProjection } from '../projection.js';
import { setAgentPluginActivation } from '../../__tests__/test-support.js';
import { createHarness, FAKE_TOKEN, fakeCapabilities, installPlugin, toolsFile, TOOLS_FILENAME, withWorkspace } from './support.js';

const SCHEMA = { type: 'object', required: ['ref'], additionalProperties: false, properties: { ref: { type: 'string' } } };
const READ_MODULE = 'export default { invoke: ({ input }) => ({ read: input.ref }) };\n';
const declare = (overrides: Record<string, unknown> = {}) => ({ name: 'look', description: 'Look.', effect: 'read', module: 'tools/look.mjs', inputSchema: SCHEMA, ...overrides });

async function loadOne(files: Record<string, string>, optional: { enabled?: boolean; bundled?: boolean } = {}) {
  return withWorkspace(async (workspaceRoot) => {
    await installPlugin({ workspaceRoot, pluginId: 'fixture-tools', files }, optional);
    const harness = createHarness();
    const refusals = await harness.refresh();
    return { refusals, registered: harness.tools.has({ toolId: 'p_fixture_tools__look' }) };
  });
}

test('an inactive plugin contributes no tool and is skipped silently', async () => {
  expect(await loadOne({ [TOOLS_FILENAME]: toolsFile([declare()]), 'tools/look.mjs': READ_MODULE }, { enabled: false }))
    .toEqual({ refusals: [], registered: false });
});

test('a package whose digest is not the bundled one is refused', async () => {
  const { refusals, registered } = await loadOne({ [TOOLS_FILENAME]: toolsFile([declare()]), 'tools/look.mjs': READ_MODULE }, { bundled: false });
  expect(registered).toBe(false);
  expect(refusals).toHaveLength(1);
  expect(refusals[0]).toMatch(/^agent tools from 'fixture-tools' were not loaded: only plugins shipped with the host may add agent tools \(installed digest [0-9a-f]{12} is not the one this build shipped\)$/);
});

test('a module path that escapes the plugin root is refused before import', async () => {
  expect(await loadOne({ [TOOLS_FILENAME]: toolsFile([declare({ module: '../outside.mjs' })]) })).toEqual({
    refusals: ["agent tool 'look' from 'fixture-tools' was not loaded: module path '../outside.mjs' escapes the plugin root"], registered: false });
});

test('a non-.mjs module path is refused by the parser', async () => {
  expect(await loadOne({ [TOOLS_FILENAME]: toolsFile([declare({ module: 'tools/look.js' })]) })).toEqual({
    refusals: [`agent tools from 'fixture-tools' were not loaded: ${TOOLS_FILENAME} is invalid: tool 'look' module must be a .mjs path inside the plugin`], registered: false });
});

test('a local name declared twice refuses the whole file (duplicate id)', async () => {
  expect(await loadOne({ [TOOLS_FILENAME]: toolsFile([declare(), declare()]), 'tools/look.mjs': READ_MODULE })).toEqual({
    refusals: [`agent tools from 'fixture-tools' were not loaded: ${TOOLS_FILENAME} is invalid: tool 'look' is declared more than once`], registered: false });
});

const loaded = (pluginId: string, overrides: Partial<LoadedAgentPluginTool['descriptor']> = {}, module: LoadedAgentPluginTool['module'] = { invoke: () => 'ok' }): LoadedAgentPluginTool => ({
  pluginId, module, descriptor: { name: 'look', description: 'Look.', effect: 'read', module: 'tools/look.mjs', inputSchema: SCHEMA, ...overrides },
});
function projectionFor(capabilities: AgentPluginToolCapabilities = fakeCapabilities({ tokenRequests: [], requests: [] })) {
  const registry = createPluginContributionRegistry({});
  return { registry, projection: createAgentPluginToolProjection({ issuedTokens: createIssuedTokenMemories(), registry, toolIdFor: pluginToolIdFor, capabilities: () => capabilities }) };
}

test.each([['a-b', 'a_b'], ['a_b', 'a-b']])('two plugins whose namespaced ids collide are both refused (ambiguous): %s, %s', (first, second) => {
  const { registry, projection } = projectionFor();
  expect(projection.sync({ loaded: [loaded(first), loaded(second)], refusals: [] }).refusals)
    .toEqual(["agent tool 'p_a_b__look' was not loaded: more than one plugin declares it ('a-b', 'a_b')"]);
  expect(registry.list({})).toEqual([]);
});

test('a write or destructive tool without describeAffectedResources is refused', () => {
  const { projection } = projectionFor();
  expect(projection.sync({ loaded: [loaded('p', { effect: 'write' }), loaded('q', { effect: 'destructive' })], refusals: [] }).refusals).toEqual([
    "agent tool 'look' from 'p' was not loaded: a write tool must export describeAffectedResources()",
    "agent tool 'look' from 'q' was not loaded: a destructive tool must export describeAffectedResources()",
  ]);
});

test('an input schema the validator cannot compile is refused', () => {
  const { projection } = projectionFor();
  const [refusal] = projection.sync({ loaded: [loaded('p', { inputSchema: { type: 'object', $ref: '#/missing' } })], refusals: [] }).refusals;
  expect(refusal).toMatch(/^agent tool 'look' from 'p' was not loaded: its input schema is invalid \(/);
});

test('a schema fault reached only by some inputs fails closed as a plugin fault, not bad input', async () => {
  const { registry, projection } = projectionFor();
  projection.sync({ loaded: [loaded('p', { inputSchema: { type: 'object', properties: { ref: { type: 'string', pattern: '(' } } } })], refusals: [] });
  const snapshot = registry.list({})[0]!;
  const call = snapshot.tools[0]!.handler({ pluginId: 'p', sdk: snapshot.sdk, auth: { access: 'member', workspaceId: 'w' }, input: { ref: 'x' } });
  await expect(call).rejects.toThrow("Plugin tool 'p_p__look' has an unusable input schema; report it to the plugin author.");
  await expect(call).rejects.not.toBeInstanceOf(ToolInputError);
});

test('input that fails the schema is refused before the module runs, naming locations not values', async () => {
  const calls: unknown[] = [];
  const { registry, projection } = projectionFor();
  projection.sync({ loaded: [loaded('p', {}, { invoke: (input) => { calls.push(input); return 'ran'; } })], refusals: [] });
  const tool = registry.list({})[0]!.tools[0]!;
  const call = tool.handler({ pluginId: 'p', sdk: registry.list({})[0]!.sdk, auth: { access: 'member', workspaceId: 'w' }, input: { ref: 'secret-value', extra: 1 } });
  await expect(call).rejects.toBeInstanceOf(ToolInputError);
  await expect(call).rejects.toThrow("Input for 'p_p__look' does not match its schema at");
  await expect(call).rejects.not.toThrow('secret-value');
  expect(calls).toEqual([]);
  await expect(projection.describeAffectedResources({ toolId: 'p_p__look', input: { ref: 7 } })).rejects.toBeInstanceOf(ToolInputError);
});

async function runWith(module: LoadedAgentPluginTool['module']) {
  const { registry, projection } = projectionFor();
  projection.sync({ loaded: [loaded('p', {}, module)], refusals: [] });
  const snapshot = registry.list({})[0]!;
  return snapshot.tools[0]!.handler({ pluginId: 'p', sdk: snapshot.sdk, auth: { access: 'member', workspaceId: 'w' }, input: { ref: 'c1' } });
}

test('a result that contains an issued access token is withheld', async () => {
  await expect(runWith({ invoke: async ({ capabilities }) => ({ leaked: await capabilities.connections.getAccessToken({ connectionRef: 'c1' }) }) }))
    .rejects.toThrow(WITHHELD_OUTPUT_MESSAGE);
});

test('a token the module kept from an EARLIER call of the same generation is withheld', async () => {
  let kept = '';
  const { registry, projection } = projectionFor();
  projection.sync({ loaded: [loaded('p', {}, { invoke: async ({ capabilities }) => {
    if (kept === '') { kept = await capabilities.connections.getAccessToken({ connectionRef: 'c1' }); return { first: true }; }
    return { leaked: kept };
  } })], refusals: [] });
  const call = () => registry.list({})[0]!.tools[0]!.handler({ pluginId: 'p', sdk: registry.list({})[0]!.sdk, auth: { access: 'member', workspaceId: 'w' }, input: { ref: 'c1' } });
  await call();
  await expect(call()).rejects.toThrow(WITHHELD_OUTPUT_MESSAGE);
});

test('the remembered tokens are bounded: the oldest of more than 64 falls out, the newest stays', async () => {
  const issued = new Set<string>();
  const gate = openCapabilityGate({ isLive: () => true, issued });
  for (let index = 0; index <= ISSUED_TOKEN_MEMORY_LIMIT; index += 1) gate.noteToken({ token: `tok-${index}-${'t'.repeat(16)}` });
  expect([issued.size, gate.mentionsToken({ value: `tok-0-${'t'.repeat(16)}` }), gate.mentionsToken({ value: `tok-${ISSUED_TOKEN_MEMORY_LIMIT}-${'t'.repeat(16)}` })])
    .toEqual([ISSUED_TOKEN_MEMORY_LIMIT, false, true]);
});

test('a token obtained again counts as newest, so a token in active use is not the one that falls out', async () => {
  const gate = openCapabilityGate({ isLive: () => true, issued: new Set() });
  const live = `live-${'t'.repeat(16)}`;
  gate.noteToken({ token: live });
  for (let index = 1; index < ISSUED_TOKEN_MEMORY_LIMIT; index += 1) gate.noteToken({ token: `tok-${index}-${'t'.repeat(16)}` });
  gate.noteToken({ token: live });
  gate.noteToken({ token: `tok-last-${'t'.repeat(16)}` });
  expect(gate.mentionsToken({ value: live })).toBe(true);
});

test('an error whose message or cause contains an issued token is replaced; a clean error passes through', async () => {
  await expect(runWith({ invoke: async ({ capabilities }) => { throw new Error(`bad ${await capabilities.connections.getAccessToken({ connectionRef: 'c1' })}`); } }))
    .rejects.toThrow(WITHHELD_ERROR_MESSAGE);
  await expect(runWith({ invoke: async ({ capabilities }) => { throw new Error('outer', { cause: new Error(await capabilities.connections.getAccessToken({ connectionRef: 'c1' })) }); } }))
    .rejects.toThrow(WITHHELD_ERROR_MESSAGE);
  const clean = Object.assign(new Error('Rate limited; retry later.'), { code: 'rate-limited', retryable: true });
  await expect(runWith({ invoke: async ({ capabilities }) => { await capabilities.connections.getAccessToken({ connectionRef: 'c1' }); throw clean; } })).rejects.toBe(clean);
  expect(FAKE_TOKEN.length).toBeGreaterThan(20);
});

test('a destructive tool always requires confirmation, even under direct host approval', async () => {
  await withWorkspace(async (workspaceRoot) => {
    await installPlugin({ workspaceRoot, pluginId: 'fixture-tools', files: {
      [TOOLS_FILENAME]: toolsFile([declare({ name: 'wipe', effect: 'destructive', module: 'tools/wipe.mjs' })]),
      'tools/wipe.mjs': "export default { invoke: () => 'wiped', describeAffectedResources: ({ input }) => ['record ' + input.ref] };\n",
    } });
    const harness = createHarness();
    expect(await harness.refresh()).toEqual([]);
    expect(harness.tools.list({}).find(tool => tool.id === 'p_fixture_tools__wipe')?.requiresConfirmation).toBe(true);
    expect(await harness.projection.describeAffectedResources({ toolId: 'p_fixture_tools__wipe', input: { ref: 'r1' } })).toEqual({ effect: 'destructive', resources: ['record r1'] });
  });
});

test('an invalid affected-resources answer blocks confirmation', async () => {
  const { projection } = projectionFor();
  projection.sync({ loaded: [loaded('p', { effect: 'write' }, { invoke: () => 'ok', describeAffectedResources: () => [''] })], refusals: [] });
  await expect(projection.describeAffectedResources({ toolId: 'p_p__look', input: { ref: 'x' } }))
    .rejects.toThrow("Plugin tool 'p_p__look' returned an invalid affected-resources list; the call cannot be confirmed.");
});

/** A write tool whose module keeps the token from its last call in module scope, as M5 assumes a plugin may. */
async function disclosureAfterACall(describe: (remembered: string) => unknown) {
  const { registry, projection } = projectionFor();
  let remembered = '';
  projection.sync({ loaded: [loaded('p', { effect: 'write' }, {
    invoke: async ({ capabilities }) => { remembered = await capabilities.connections.getAccessToken({ connectionRef: 'c1' }); return 'ok'; },
    describeAffectedResources: () => describe(remembered),
  })], refusals: [] });
  const snapshot = registry.list({})[0]!;
  await snapshot.tools[0]!.handler({ pluginId: 'p', sdk: snapshot.sdk, auth: { access: 'member', workspaceId: 'w' }, input: { ref: 'c1' } });
  return projection.describeAffectedResources({ toolId: 'p_p__look', input: { ref: 'x' } });
}

test('an affected-resources answer that mentions a token the plugin obtained is refused', async () => {
  await expect(disclosureAfterACall(remembered => [`sheet ${remembered}`]))
    .rejects.toThrow("Plugin tool 'p_p__look' returned an invalid affected-resources list; the call cannot be confirmed.");
});

test('an affected-resources hook error that mentions a token the plugin obtained is withheld', async () => {
  await expect(disclosureAfterACall(remembered => { throw new Error(`cannot describe ${remembered}`); })).rejects.toThrow(WITHHELD_ERROR_MESSAGE);
});

test('a clean affected-resources hook error passes through as the same error', async () => {
  const clean = new Error('sheet not found');
  await expect(disclosureAfterACall(() => { throw clean; })).rejects.toBe(clean);
});

test('a clean affected-resources answer after a call is disclosed', async () => {
  expect(await disclosureAfterACall(() => ['sheet Leads'])).toEqual({ effect: 'write', resources: ['sheet Leads'] });
});

test('disabling the plugin removes its tools, refuses authorized and direct calls and revokes retained capabilities', async () => {
  await withWorkspace(async (workspaceRoot) => {
    await installPlugin({ workspaceRoot, pluginId: 'fixture-tools', files: {
      [TOOLS_FILENAME]: toolsFile([declare()]),
      'tools/look.mjs': 'export default { invoke: ({ input, capabilities }) => { globalThis.__keptCapabilities = capabilities; return { read: input.ref }; } };\n',
    } });
    const harness = createHarness();
    await harness.refresh();
    expect(await harness.invoke('p_fixture_tools__look', { ref: 'r1' })).toEqual({ read: 'r1' });
    const kept = (globalThis as { __keptCapabilities?: AgentPluginToolCapabilities }).__keptCapabilities!;
    delete (globalThis as { __keptCapabilities?: unknown }).__keptCapabilities;
    const pending = await harness.authorize('p_fixture_tools__look', { ref: 'r2' });
    const oldGeneration = harness.contributions.list({})[0]!;

    await setAgentPluginActivation({ workspaceRoot, pluginId: 'fixture-tools', enabled: false, actor: 'test' }, { origin: 'bundled' });
    expect(await harness.refresh()).toEqual([]);

    expect(harness.tools.has({ toolId: 'p_fixture_tools__look' })).toBe(false);
    await expect(pending()).rejects.toThrow('Plugin tool is disabled or was reloaded.');
    await expect(oldGeneration.tools[0]!.handler({ pluginId: 'fixture-tools', sdk: oldGeneration.sdk, auth: { access: 'member', workspaceId: 'w' }, input: { ref: 'r3' } }))
      .rejects.toThrow(REVOKED_MESSAGE);
    await expect(kept.connections.getAccessToken({ connectionRef: 'c1' })).rejects.toThrow(REVOKED_MESSAGE);
    await expect(kept.http.fetch({ url: 'https://api.example.test/' })).rejects.toThrow(REVOKED_MESSAGE);
    await expect(kept.limiter.check({ key: 'k' })).rejects.toThrow(REVOKED_MESSAGE);
    await expect(kept.artifacts!.write({ name: 'a.csv', mediaType: 'text/csv', content: 'a' })).rejects.toThrow(REVOKED_MESSAGE);
    expect(harness.log.tokenRequests).toEqual([]);
  });
});

test('a host without an artifact store leaves artifacts absent, not a wrapper that throws', () => {
  const { artifacts: _omitted, ...host } = fakeCapabilities({ tokenRequests: [], requests: [] });
  const { capabilities } = openCapabilitySession({ capabilities: host, isLive: () => true, issued: createIssuedTokenMemories().forPlugin({ pluginId: 'acme-office' }) });
  expect(Object.hasOwn(capabilities, 'artifacts')).toBe(false);
  expect(capabilities.artifacts).toBeUndefined();
});

src/admin-surfaces/__tests__/delivery-bi.source:
/**
 * @file Security pins for the admin-surface `deliveryBindings` port: a surface manages form-delivery
 * bindings only for the delivery adapters it declared and only through its declared connections; a
 * binding's config is bounded plain JSON that never carries a token the plugin obtained (on the way in
 * and on the way out); another adapter's binding can be neither listed, overwritten nor removed; every
 * call needs a signed-in admin; disabling the plugin revokes the port. The host is the shared typed
 * fake, which deliberately lists every binding in the workspace, so the filtering proven here is Jini's.
 */
import { describe, expect, test } from 'vitest';
import { REVOKED_MESSAGE, createIssuedTokenMemories } from '../../lifecycle/tools/capabilities.js';
import { FAKE_TOKEN, WORKSPACE_ID } from '../../lifecycle/tools/__tests__/support.js';
import { createAdminSurfaceActionDispatcher, createAdminSurfaceHandlerHost, parseAdminSurfacesFile, type AdminSurfaceCapabilityDeclarations, type AdminSurfaceDescriptor, type AdminSurfaceHandlerModule } from '../index.js';
import type { AdminSurfaceDeliveryBinding } from '../delivery-bindings.js';
import { ADMIN_SURFACE_STATE_LIMITS, openAdminSurfaceCapabilitySession, STATE_CREDENTIAL_MESSAGE } from '../surface-capabilities.js';
import { createFakeSurfaceHost } from './surface-support.js';

const PLUGIN = 'acme-office';
const DECLARED: AdminSurfaceCapabilityDeclarations = { connections: [{ id: 'account', startParams: [], callbackFields: [] }], deliveryAdapters: ['acme-rows'] };
const OURS: AdminSurfaceDeliveryBinding = { bindingId: 'ours-1', adapterId: 'acme-rows', connectionId: 'account', enabled: true, allForms: true, config: { tab: 7 } };
const FOREIGN: AdminSurfaceDeliveryBinding = { bindingId: 'foreign-1', adapterId: 'other-adapter', connectionId: 'account', enabled: true, formIds: ['contact'], config: { list: 'x' } };
const DRAFT = { adapterId: 'acme-rows', connectionId: 'account', enabled: true, formIds: ['contact'], config: { tab: 1 } } as const;
const NO_FORMS = 'A delivery binding must name its forms: formIds (a list; [] for none) or allForms: true for every current and future form, not both.';
const NO_ACTOR = 'Delivery settings need a signed-in admin. Open the surface from an authenticated admin page and retry.';
const NOT_OURS = (id: string) => `No delivery binding '${id}' belongs to this surface's delivery adapters; list the bindings and retry.`;

function open(optional: { readonly actorId?: string | null; readonly live?: () => boolean; readonly issued?: Set<string> } = {}) {
  const fake = createFakeSurfaceHost({ bindings: [OURS, FOREIGN] });
  const actorId = optional.actorId === undefined ? 'admin-1' : optional.actorId;
  const session = openAdminSurfaceCapabilitySession(
    { capabilities: fake.port({ pluginId: PLUGIN, workspaceId: WORKSPACE_ID }), isLive: optional.live ?? (() => true), declared: DECLARED, issued: optional.issued ?? new Set() },
    actorId === null ? {} : { actorId },
  );
  return { ...fake, ...session, bindingsPort: session.capabilities.deliveryBindings! };
}

const surfaceRaw = (extra: Record<string, unknown>) => JSON.stringify({ schemaVersion: 1, surfaces: [{
  id: 'destination', title: 'Destination', entry: 'surface/index.html', handlerModule: 'server/handlers.mjs',
  actions: [{ name: 'save', input: { type: 'object' }, result: { type: 'object', properties: { count: { type: 'integer' } } } }], ...extra,
}] });
const reasonFor = (extra: Record<string, unknown>) => {
  const parsed = parseAdminSurfacesFile({ raw: surfaceRaw(extra) });
  return parsed.ok ? 'accepted' : parsed.reason;
};

describe('the surfaces file declares which delivery adapters a surface manages', () => {
  test('deliveryAdapters without a handler module is refused', () => {
    expect(reasonFor({ handlerModule: undefined, actions: [], deliveryAdapters: ['acme-rows'] })).toBe('surfaces[0].deliveryAdapters needs a handlerModule that uses it');
  });
  test.each([
    ['not an array', 'acme-rows'],
    ['more than 8', Array.from({ length: 9 }, (_, index) => `adapter-${index}`)],
  ])('a deliveryAdapters list that is %s is refused', (_label, deliveryAdapters) => {
    expect(reasonFor({ deliveryAdapters })).toBe('surfaces[0].deliveryAdapters must be an array of at most 8');
  });
  test.each([['Acme-Rows'], ['../rows'], ['a'.repeat(65)], [7]])('a delivery adapter id %j that is not a lowercase hyphenated id is refused', (id) => {
    expect(reasonFor({ deliveryAdapters: ['acme-rows', id] })).toBe('surfaces[0].deliveryAdapters[1] must be a unique name matching ^(?=.{1,64}$)[a-z0-9]+(?:-[a-z0-9]+)*$');
  });
  test('a delivery adapter declared twice is refused', () => {
    expect(reasonFor({ deliveryAdapters: ['acme-rows', 'acme-rows'] })).toBe('surfaces[0].deliveryAdapters[1] must be a unique name matching ^(?=.{1,64}$)[a-z0-9]+(?:-[a-z0-9]+)*$');
  });
  test('declared adapters are parsed onto the descriptor', () => {
    const parsed = parseAdminSurfacesFile({ raw: surfaceRaw({ deliveryAdapters: ['acme-rows', 'a'.repeat(64)] }) });
    expect(parsed.ok && parsed.descriptors[0]!.deliveryAdapters).toStrictEqual(['acme-rows', 'a'.repeat(64)]);
  });
});

describe('the port exists only where it is declared and provided', () => {
  test('a surface that declares no delivery adapters gets no deliveryBindings port', () => {
    const session = openAdminSurfaceCapabilitySession({ capabilities: createFakeSurfaceHost().port({ pluginId: PLUGIN, workspaceId: WORKSPACE_ID }), isLive: () => true, declared: { connections: DECLARED.connections! }, issued: new Set() }, { actorId: 'admin-1' });
    expect(session.capabilities).not.toHaveProperty('deliveryBindings');
  });
  test('a host that provides no deliveryBindings port leaves it absent', () => {
    const session = openAdminSurfaceCapabilitySession({ capabilities: createFakeSurfaceHost({ deliveryBindings: false }).port({ pluginId: PLUGIN, workspaceId: WORKSPACE_ID }), isLive: () => true, declared: DECLARED, issued: new Set() }, { actorId: 'admin-1' });
    expect(session.capabilities).not.toHaveProperty('deliveryBindings');
  });
});

describe('save: only declared adapters and connections, bounded token-free config', () => {
  test('an undeclared adapter is refused before the host sees it', async () => {
    const session = open();
    await expect(session.bindingsPort.save({ ...DRAFT, adapterId: 'other-adapter' }))
      .rejects.toThrow("This admin surface does not declare delivery adapter 'other-adapter', so its handlers cannot manage its bindings. Declare it in the surface's deliveryAdapters.");
    expect(session.log.calls).toEqual([]);
  });
  test('a connection the surface did not declare is refused before the host sees it', async () => {
    const session = open();
    await expect(session.bindingsPort.save({ ...DRAFT, connectionId: 'other-plugins-account' }))
      .rejects.toThrow("Delivery bindings may only use this surface's declared connections; 'other-plugins-account' is not one of them.");
    expect(session.log.calls).toEqual([]);
  });
  test('a config one byte over the limit is refused and nothing is saved', async () => {
    const session = open();
    const config = { pad: 'x'.repeat(ADMIN_SURFACE_STATE_LIMITS.maxValueBytes - '{"pad":""}'.length + 1) };
    await expect(session.bindingsPort.save({ ...DRAFT, config })).rejects.toThrow('A settings value may be at most 16384 bytes of JSON.');
    expect(session.log.calls).toEqual([]);
  });
  test('a config mentioning a token the plugin obtained is refused and nothing is saved', async () => {
    const session = open();
    const token = await session.capabilities.connections.getAccessToken({ connectionId: 'account' });
    await expect(session.bindingsPort.save({ ...DRAFT, config: { header: `Bearer ${token}` } })).rejects.toThrow(STATE_CREDENTIAL_MESSAGE);
    expect(session.log.calls).toEqual([]);
  });
  test('a config mentioning a token an earlier call (or a tool) obtained is refused', async () => {
    const session = open({ issued: new Set([FAKE_TOKEN]) });
    await expect(session.bindingsPort.save({ ...DRAFT, config: { nested: [{ value: FAKE_TOKEN }] } })).rejects.toThrow(STATE_CREDENTIAL_MESSAGE);
    expect(session.bindings.get('binding-3')).toBeUndefined();
  });
  test("another adapter's binding cannot be overwritten through its binding id", async () => {
    const session = open();
    await expect(session.bindingsPort.save({ ...DRAFT, bindingId: 'foreign-1' })).rejects.toThrow(NOT_OURS('foreign-1'));
    expect(session.bindings.get('foreign-1')).toStrictEqual(FOREIGN);
    expect(session.log.calls).toEqual([`${PLUGIN}:bindings.list:{}`]);
  });
});

describe('list and remove never reach another adapter\'s bindings', () => {
  test('list returns only the declared adapters\' bindings, even when the host returns more', async () => {
    await expect(open().bindingsPort.list()).resolves.toStrictEqual([OURS]);
  });
  test('list withholds the bindings when one mentions a token the plugin obtained', async () => {
    const session = open({ issued: new Set([FAKE_TOKEN]) });
    session.bindings.set('ours-2', { ...OURS, bindingId: 'ours-2', config: { leaked: FAKE_TOKEN } });
    await expect(session.bindingsPort.list()).rejects.toThrow('A delivery binding held a connection credential, so it was withheld. Remove it and save it again.');
  });
  test("removing another adapter's binding is refused and it stays", async () => {
    const session = open();
    await expect(session.bindingsPort.remove({ bindingId: 'foreign-1' })).rejects.toThrow(NOT_OURS('foreign-1'));
    expect(session.bindings.get('foreign-1')).toStrictEqual(FOREIGN);
    expect(session.log.calls).not.toContain(`${PLUGIN}:bindings.remove:{"bindingId":"foreign-1"}`);
  });
});

describe('which forms a binding delivers is always stated (never an implicit "every form")', () => {
  const { formIds: _formIds, ...noForms } = DRAFT;
  test.each([
    ['neither formIds nor allForms', noForms],
    ['allForms: false', { ...noForms, allForms: false }],
    ['allForms as a string', { ...noForms, allForms: 'true' }],
    ['both formIds and allForms', { ...DRAFT, allForms: true }],
  ])('a draft with %s is refused before the host sees it', async (_label, draft) => {
    const session = open();
    // Malformed on purpose: a plugin is JavaScript and may send any of these.
    await expect(session.bindingsPort.save(draft as unknown as Parameters<typeof session.bindingsPort.save>[0])).rejects.toThrow(NO_FORMS);
    expect(session.log.calls).toEqual([]);
  });
  test('allForms: true reaches the host as stated, without a formIds key', async () => {
    const session = open();
    await expect(session.bindingsPort.save({ ...noForms, allForms: true })).resolves.toMatchObject({ allForms: true });
    expect(session.log.calls.at(-1)).toBe('acme-office:bindings.save:{"adapterId":"acme-rows","connectionId":"account","enabled":true,"allForms":true,"config":{"tab":1}}');
  });
  test('a binding the host lists without stating its forms is refused, never read as every form', async () => {
    const session = open();
    const { allForms: _allForms, ...unstated } = OURS as AdminSurfaceDeliveryBinding & { allForms: true };
    // Malformed on purpose: a host that still stores "absent = every form" must map it to allForms: true.
    session.bindings.set('ours-1', unstated as unknown as AdminSurfaceDeliveryBinding);
    await expect(session.bindingsPort.list()).rejects.toThrow("The host listed delivery binding 'ours-1' without formIds or allForms; fix the host's binding store.");
  });
});

describe('a signed-in admin and a live plugin are required', () => {
  test.each([
    ['list', (s: ReturnType<typeof open>) => s.bindingsPort.list()],
    ['save', (s: ReturnType<typeof open>) => s.bindingsPort.save(DRAFT)],
    ['remove', (s: ReturnType<typeof open>) => s.bindingsPort.remove({ bindingId: 'ours-1' })],
  ])('%s without a signed-in admin is refused before the host sees it', async (_name, call) => {
    const session = open({ actorId: null });
    await expect(call(session)).rejects.toThrow(NO_ACTOR);
    expect(session.log.calls).toEqual([]);
  });

  test.each([
    ['list', (s: ReturnType<typeof open>) => s.bindingsPort.list()],
    ['save', (s: ReturnType<typeof open>) => s.bindingsPort.save(DRAFT)],
    ['remove', (s: ReturnType<typeof open>) => s.bindingsPort.remove({ bindingId: 'ours-1' })],
  ])('%s on a revoked session is refused before the host sees it', async (_name, call) => {
    const session = open({ live: () => false });
    await expect(call(session)).rejects.toThrow(REVOKED_MESSAGE);
    expect(session.log.calls).toEqual([]);
  });

  test('a port a handler module kept is revoked once the plugin is disabled', async () => {
    const parsed = parseAdminSurfacesFile({ raw: surfaceRaw({ connections: [{ id: 'account' }], deliveryAdapters: ['acme-rows'] }) });
    const descriptor = (parsed.ok ? parsed.descriptors[0] : undefined) as AdminSurfaceDescriptor & { handlerModule: string };
    let kept: Parameters<AdminSurfaceHandlerModule['actions'][string]>[0]['capabilities'] | undefined;
    const fake = createFakeSurfaceHost({ bindings: [OURS] });
    const host = createAdminSurfaceHandlerHost({ hostKind: 'hosted', issuedTokens: createIssuedTokenMemories(), capabilities: fake.port });
    host.sync({ loaded: [{ pluginId: PLUGIN, descriptor, module: { actions: { save: async ({ capabilities }) => { kept = capabilities; return { count: (await capabilities.deliveryBindings!.list()).length }; } } } }], refusals: [] });
    const context = { workspaceId: WORKSPACE_ID, principalId: 'admin-1', pluginId: PLUGIN, surfaceId: 'destination' };
    await expect(createAdminSurfaceActionDispatcher({ descriptor, handlers: host.handlersFor({ pluginId: PLUGIN, surfaceId: 'destination' }) }).dispatch({ action: 'save', payload: {}, context }))
      .resolves.toStrictEqual({ ok: true, result: { count: 1 } });
    host.sync({ loaded: [], refusals: [] });
    for (const call of [kept!.deliveryBindings!.list(), kept!.deliveryBindings!.save(DRAFT), kept!.deliveryBindings!.remove({ bindingId: 'ours-1' })]) await expect(call).rejects.toThrow(REVOKED_MESSAGE);
    expect(fake.bindings.get('ours-1')).toStrictEqual(OURS);
  });
});

src/lifecycle/tools/__tests__/projection.source:
/**
 * @file Unit tests for the tool projection against a typed fake contribution registry (the real one is
 * exercised by the security and vertical-slice suites): schema compile faults, generation reuse and
 * replacement, a registry that refuses a generation, the inert site-plugin SDK slot, root-level schema
 * errors, and the affected-resources disclosure for unknown, withdrawn and read tools.
 */
import { describe, expect, test } from 'vitest';
import { ToolInputError } from '@jini-ai/core';
import { createIssuedTokenMemories, type AgentPluginToolCapabilities } from '../capabilities.js';
import type { AgentPluginToolModule, LoadedAgentPluginTool } from '../definition.js';
import type { AgentPluginToolDescriptor } from '../manifest.js';
import { createAgentPluginToolProjection, type AgentPluginToolProjectionPorts, type AgentPluginToolSnapshot } from '../projection.js';

type Registry = AgentPluginToolProjectionPorts['registry'];

/** Fake registry keyed by plugin id; `failReplace` makes `replace` throw the given value. */
function fakeRegistry(optional: { failReplace?: unknown } = {}) {
  const held = new Map<string, AgentPluginToolSnapshot>();
  const calls = { replace: 0, detach: [] as string[] };
  const registry: Registry = {
    replace: ({ contributions }) => {
      calls.replace += 1;
      if (optional.failReplace !== undefined) throw optional.failReplace;
      held.set(contributions.pluginId, contributions);
    },
    detach: ({ pluginId }) => { calls.detach.push(pluginId); held.delete(pluginId); },
    list: () => [...held.values()],
  };
  return { registry, held, calls };
}

const capabilities = (): AgentPluginToolCapabilities => ({
  connections: { getAccessToken: async () => 'unused' },
  http: { fetch: async () => new Response('') },
  limiter: { check: async () => ({ allowed: true }) },
  state: { get: async () => null },
});

function projectionWith(registry: Registry) {
  return createAgentPluginToolProjection({
    registry, capabilities, issuedTokens: createIssuedTokenMemories(), toolIdFor: ({ pluginId, name }) => `p_${pluginId}__${name}`,
  });
}

function loaded(
  optional: { pluginId?: string; descriptor?: Partial<AgentPluginToolDescriptor>; module?: AgentPluginToolModule } = {},
): LoadedAgentPluginTool {
  const descriptor: AgentPluginToolDescriptor = {
    name: 'list_rows', description: 'Lists rows.', effect: 'read', module: 'tools/list.mjs',
    inputSchema: { type: 'object', properties: { n: { type: 'integer' } }, additionalProperties: false }, ...optional.descriptor,
  };
  return { pluginId: optional.pluginId ?? 'acme-office', descriptor, module: optional.module ?? { invoke: () => 'ok' } };
}

describe('schema compilation', () => {
  test('a schema that throws a non-Error while compiling is refused with its text', () => {
    const { registry } = fakeRegistry();
    // Malformed input on purpose: a public-API caller can pass any object; JSON data cannot do this.
    const inputSchema = { type: 'object', get properties(): never { throw 'not an error'; } };
    expect(projectionWith(registry).sync({ loaded: [loaded({ descriptor: { inputSchema } })], refusals: [] }).refusals)
      .toEqual(["agent tool 'list_rows' from 'acme-office' was not loaded: its input schema is invalid (not an error)"]);
  });
});

describe('generations', () => {
  test('an unchanged reload keeps the same generation and does not replace it', () => {
    const { registry, calls, held } = fakeRegistry();
    const projection = projectionWith(registry);
    const tool = loaded();
    projection.sync({ loaded: [tool], refusals: [] });
    const first = held.get('acme-office');
    projection.sync({ loaded: [{ ...tool, descriptor: { ...tool.descriptor } }], refusals: [] });
    expect(calls.replace).toBe(1);
    expect(held.get('acme-office')).toBe(first);
  });

  test('a new module object for the same declaration replaces the generation', () => {
    const { registry, calls } = fakeRegistry();
    const projection = projectionWith(registry);
    projection.sync({ loaded: [loaded()], refusals: [] });
    projection.sync({ loaded: [loaded({ module: { invoke: () => 'new' } })], refusals: [] });
    expect(calls.replace).toBe(2);
  });

  test('a changed declaration with the same module replaces the generation', () => {
    const { registry, calls } = fakeRegistry();
    const projection = projectionWith(registry);
    const module: AgentPluginToolModule = { invoke: () => 'ok' };
    projection.sync({ loaded: [loaded({ module })], refusals: [] });
    projection.sync({ loaded: [loaded({ module, descriptor: { description: 'Lists rows, changed.' } })], refusals: [] });
    expect(calls.replace).toBe(2);
  });

  test('a different tool count replaces the generation', () => {
    const { registry, calls } = fakeRegistry();
    const projection = projectionWith(registry);
    const module: AgentPluginToolModule = { invoke: () => 'ok' };
    projection.sync({ loaded: [loaded({ module })], refusals: [] });
    projection.sync({ loaded: [loaded({ module }), loaded({ module, descriptor: { name: 'other' } })], refusals: [] });
    expect(calls.replace).toBe(2);
  });

  test('a registry that refuses an Error detaches the plugin and reports its message', () => {
    const { registry, calls } = fakeRegistry({ failReplace: new Error('id already taken') });
    const projection = projectionWith(registry);
    expect(projection.sync({ loaded: [loaded()], refusals: ['loader said so'] }).refusals)
      .toEqual(['loader said so', "agent tools from 'acme-office' were not loaded: id already taken"]);
    expect(calls.detach).toEqual(['acme-office']);
  });

  test('a registry that refuses a non-Error reports its text, and the tool is not described', async () => {
    const { registry } = fakeRegistry({ failReplace: 'busy' });
    const projection = projectionWith(registry);
    expect(projection.sync({ loaded: [loaded()], refusals: [] }).refusals).toEqual(["agent tools from 'acme-office' were not loaded: busy"]);
    await expect(projection.describeAffectedResources({ toolId: 'p_acme-office__list_rows', input: {} })).resolves.toBeNull();
  });
});

describe('the contract snapshot', () => {
  test('fills the site-plugin SDK slot with functions that refuse', () => {
    const { registry, held } = fakeRegistry();
    projectionWith(registry).sync({ loaded: [loaded()], refusals: [] });
    // The contract types the slot as `object`; this is the site-plugin SDK shape the projection fills.
    const sdk = held.get('acme-office')!.sdk as { content: { read: () => never }; routes: { add: () => never }; addFilter: () => never };
    const message = 'Agent Plugin tools have no site-plugin SDK.';
    expect(() => sdk.content.read()).toThrow(message);
    expect(() => sdk.routes.add()).toThrow(message);
    expect(() => sdk.addFilter()).toThrow(message);
    expect(Object.isFrozen(sdk)).toBe(true);
  });

  test('input failing at the schema root is located at #', async () => {
    const { registry, held } = fakeRegistry();
    projectionWith(registry).sync({ loaded: [loaded({ descriptor: { inputSchema: { type: 'object', required: ['n'] } } })], refusals: [] });
    const tool = held.get('acme-office')!.tools[0]!;
    const call = tool.handler({ pluginId: 'acme-office', auth: { workspaceId: 'w' }, input: {} });
    await expect(call).rejects.toBeInstanceOf(ToolInputError);
    await expect(call).rejects.toThrow("Input for 'p_acme-office__list_rows' does not match its schema at # (required). Fix the input and retry.");
  });
});

describe('a call', () => {
  test('names at most three distinct failing locations', async () => {
    const { registry, held } = fakeRegistry();
    const nested = (depth: number): Record<string, unknown> => (depth === 0 ? { type: 'integer' } : { type: 'object', properties: { [`k${depth}`]: nested(depth - 1) } });
    projectionWith(registry).sync({ loaded: [loaded({ descriptor: { inputSchema: nested(4) } })], refusals: [] });
    const input = { k4: { k3: { k2: { k1: 'not an integer' } } } };
    await expect(held.get('acme-office')!.tools[0]!.handler({ pluginId: 'acme-office', auth: { workspaceId: 'w' }, input }))
      .rejects.toThrow("Input for 'p_acme-office__list_rows' does not match its schema at # (properties), #/k4 (properties), #/k4/k3 (properties). Fix the input and retry.");
  });

  test('scopes host capabilities to the caller and passes the abort signal to the host and the module', async () => {
    const { registry, held } = fakeRegistry();
    const scopes: unknown[] = [];
    const seen: (AbortSignal | undefined)[] = [];
    const projection = createAgentPluginToolProjection({
      registry, issuedTokens: createIssuedTokenMemories(), toolIdFor: ({ pluginId, name }) => `p_${pluginId}__${name}`,
      capabilities: (scope) => { scopes.push(scope); return capabilities(); },
    });
    projection.sync({ loaded: [loaded({ module: { invoke: ({ signal }) => { seen.push(signal); return 'done'; } } })], refusals: [] });
    const { signal } = new AbortController();
    const tool = held.get('acme-office')!.tools[0]!;
    await expect(tool.handler({ pluginId: 'acme-office', auth: { workspaceId: 'w', principalId: 'member-1' }, input: {}, signal })).resolves.toBe('done');
    await expect(tool.handler({ pluginId: 'acme-office', auth: { workspaceId: 'w' }, input: {} })).resolves.toBe('done');
    expect(scopes).toEqual([{ pluginId: 'acme-office', workspaceId: 'w', principalId: 'member-1', signal }, { pluginId: 'acme-office', workspaceId: 'w' }]);
    expect(seen).toEqual([signal, undefined]);
  });

  test('every tool of one plugin is projected in one generation, in declaration order', () => {
    const { registry, held } = fakeRegistry();
    projectionWith(registry).sync({ loaded: [loaded(), loaded({ descriptor: { name: 'append_row' } })], refusals: [] });
    expect(held.get('acme-office')!.tools.map(tool => tool.name)).toEqual(['list_rows', 'append_row']);
  });
});

describe('describeAffectedResources', () => {
  test('is null for a tool id no plugin projected', async () => {
    const { registry } = fakeRegistry();
    const projection = projectionWith(registry);
    projection.sync({ loaded: [loaded()], refusals: [] });
    await expect(projection.describeAffectedResources({ toolId: 'p_acme-office__missing', input: {} })).resolves.toBeNull();
  });

  test('is null once the registry no longer holds the generation', async () => {
    const { registry, held } = fakeRegistry();
    const projection = projectionWith(registry);
    projection.sync({ loaded: [loaded()], refusals: [] });
    held.clear();
    await expect(projection.describeAffectedResources({ toolId: 'p_acme-office__list_rows', input: {} })).resolves.toBeNull();
  });

  test('a read tool without a disclosure hook discloses no resources', async () => {
    const { registry } = fakeRegistry();
    const projection = projectionWith(registry);
    projection.sync({ loaded: [loaded()], refusals: [] });
    await expect(projection.describeAffectedResources({ toolId: 'p_acme-office__list_rows', input: { n: 1 } })).resolves.toEqual({ effect: 'read', resources: [] });
  });

  test('a write tool discloses a frozen copy of what its hook returns', async () => {
    const { registry } = fakeRegistry();
    const projection = projectionWith(registry);
    const answer = ['Row 1 of Sheet A'];
    projection.sync({ loaded: [loaded({ descriptor: { effect: 'write' }, module: { invoke: () => 'ok', describeAffectedResources: () => answer } })], refusals: [] });
    const disclosure = await projection.describeAffectedResources({ toolId: 'p_acme-office__list_rows', input: { n: 1 } });
    expect(disclosure).toEqual({ effect: 'write', resources: ['Row 1 of Sheet A'] });
    expect(disclosure?.resources).not.toBe(answer);
    expect(Object.isFrozen(disclosure?.resources)).toBe(true);
  });

  test.each([
    ['more than 50 entries', Array.from({ length: 51 }, (_, index) => `r${index}`)],
    ['an empty entry', ['']],
    ['an entry over 300 characters', ['r'.repeat(301)]],
    ['a non-string entry', [7]],
    ['a non-array answer', 'r1'],
  ])('a hook answer with %s blocks confirmation', async (_label, answer) => {
    const { registry } = fakeRegistry();
    const projection = projectionWith(registry);
    projection.sync({ loaded: [loaded({ descriptor: { effect: 'destructive' }, module: { invoke: () => 'ok', describeAffectedResources: () => answer } })], refusals: [] });
    await expect(projection.describeAffectedResources({ toolId: 'p_acme-office__list_rows', input: {} }))
      .rejects.toThrow("Plugin tool 'p_acme-office__list_rows' returned an invalid affected-resources list; the call cannot be confirmed. Report it to the plugin author.");
  });

  test('accepts exactly 50 entries of 300 characters', async () => {
    const { registry } = fakeRegistry();
    const projection = projectionWith(registry);
    const answer = Array.from({ length: 50 }, () => 'r'.repeat(300));
    projection.sync({ loaded: [loaded({ descriptor: { effect: 'write' }, module: { invoke: () => 'ok', describeAffectedResources: () => answer } })], refusals: [] });
    await expect(projection.describeAffectedResources({ toolId: 'p_acme-office__list_rows', input: {} })).resolves.toMatchObject({ resources: answer });
  });
});

src/admin-surfaces/__tests__/surface-cap.source:
/**
 * @file The one phase-A vertical-slice proof for the admin-surface capability ports: a neutral
 * "acme-office" fixture is installed, bundled and activated through the real lifecycle owners and
 * its handler module admitted by the real loader. Through the host dispatcher it reads connection
 * status, starts a sign-in with a declared start parameter, takes the callback field the host's
 * callback route deposited after a completed sign-in, verifies it through guarded HTTP, saves the
 * selection in plugin state, and reads declared public config for its bootstrap. A second test
 * extends the slice to the plugin's agent tools: a product flag its surface writes is what its tool
 * reads, through the same host store, so turning the product off blocks the tool. No network.
 */
import { expect, test } from 'vitest';
import { createIssuedTokenMemories } from '../../lifecycle/tools/capabilities.js';
import { createPluginContributionLoader } from '../../lifecycle/contribution-loader.js';
import { findTrustedPluginPackages, importContainedModule, readTrustedPluginFile } from '../../lifecycle/__tests__/test-support.js';
import { createHarness, FAKE_TOKEN, fakeCapabilities, installPlugin, toolsFile, TOOLS_FILENAME, WORKSPACE_ID, withWorkspace } from '../../lifecycle/tools/__tests__/support.js';
import { createAdminSurfaceActionDispatcher, createAdminSurfaceHandlerHost, defineAdminSurfaceContribution, defineAdminSurfaceHandlerContribution } from '../index.js';
import { createFakeSurfaceHost } from './surface-support.js';

const FILENAME = 'host-admin-surfaces.json';
const HANDLERS = `export default {
  actions: {
    async 'read-status'({ capabilities, context }) {
      const status = await capabilities.connections.status({ connectionId: context.connectionIds[0] });
      return { status: status.status, account: status.accountLabel };
    },
    async 'choose-resource'({ capabilities, context }) {
      return capabilities.connections.begin({ connectionId: context.connectionIds[0], action: 'add-scopes' },
        { scopeSetIds: ['files'], startParams: { 'selection-mode': 'one' } });
    },
    async 'finish-choice'({ input, capabilities, context, fail }) {
      const connectionId = context.connectionIds[0];
      const fields = await capabilities.connections.takeCallbackFields({ connectionId, attemptId: input.attemptId });
      if (fields === null) throw fail({ code: 'choice-missing', message: 'Choose the resource again.' });
      const token = await capabilities.connections.getAccessToken({ connectionId });
      const response = await capabilities.http.fetch({ url: 'https://api.example.test/resources/' + fields['picked-id'] }, { headers: { authorization: 'Bearer ' + token } });
      if (response.status !== 200) throw fail({ code: 'choice-unverified', message: 'The chosen resource could not be opened; choose it again.' });
      await capabilities.state.set({ key: 'selection', value: { resourceId: fields['picked-id'] } });
      return { saved: true, resourceId: fields['picked-id'] };
    },
  },
  async bootstrap({ capabilities }) {
    return { appId: await capabilities.publicConfig.get({ name: 'ACME_APP_ID' }) };
  },
};
`;
const object = (properties: Record<string, unknown>, required: string[] = []) => ({ type: 'object', properties, required });
const SURFACES = JSON.stringify({ schemaVersion: 1, surfaces: [{
  id: 'resource-chooser', title: 'Choose a resource', entry: 'surface/index.html', files: ['surface/app.mjs'], handlerModule: 'server/handlers.mjs',
  connections: [{ id: 'account', startParams: ['selection-mode'], callbackFields: ['picked-id'] }], publicConfig: ['ACME_APP_ID'],
  actions: [
    { name: 'read-status', input: object({}), result: object({ status: { type: 'string' }, account: { type: 'string' } }, ['status']) },
    { name: 'choose-resource', input: object({}), result: object({ authorizationUrl: { type: 'string' }, attemptId: { type: 'string' }, expiresAt: { type: 'string' } }, ['authorizationUrl', 'attemptId']) },
    { name: 'finish-choice', input: object({ attemptId: { type: 'string', maxLength: 128 } }, ['attemptId']), result: object({ saved: { type: 'boolean' }, resourceId: { type: 'string' } }, ['saved']) },
  ],
  bootstrap: object({ appId: { type: 'string' } }, ['appId']),
}] });

test('an acme-style surface administers its own connection, takes a callback field once, verifies it and saves the choice', async () => {
  await withWorkspace(async (workspaceRoot) => {
    await installPlugin({ workspaceRoot, pluginId: 'acme-office', files: {
      [FILENAME]: SURFACES, 'surface/index.html': '<!doctype html><script type="module" src="app.mjs"></script>', 'surface/app.mjs': 'export {};', 'server/handlers.mjs': HANDLERS,
    } });
    const loader = createPluginContributionLoader({
      findPackages: (query) => findTrustedPluginPackages(query),
      readFile: ({ plugin, filename }) => readTrustedPluginFile(plugin, filename),
      importModule: ({ plugin, modulePath }) => importContainedModule(plugin, modulePath),
    });
    const fake = createFakeSurfaceHost({ config: { ACME_APP_ID: 'app-123' } });
    const host = createAdminSurfaceHandlerHost({ hostKind: 'hosted', issuedTokens: createIssuedTokenMemories(), capabilities: fake.port });
    const surfaces = await loader.loadPluginContributions({ workspaceId: WORKSPACE_ID, definition: defineAdminSurfaceContribution({ filename: FILENAME }) });
    const handlerLoad = await loader.loadPluginContributions({ workspaceId: WORKSPACE_ID, definition: defineAdminSurfaceHandlerContribution({ filename: FILENAME }) });
    expect([...surfaces.refusals, ...host.sync({ loaded: handlerLoad.items, refusals: handlerLoad.refusals }).refusals]).toEqual([]);
    const [surface] = surfaces.items;
    if (!surface) throw new Error('the fixture surface was not admitted');
    const context = { workspaceId: WORKSPACE_ID, principalId: 'admin-1', pluginId: 'acme-office', surfaceId: 'resource-chooser' };
    const dispatcher = createAdminSurfaceActionDispatcher({ descriptor: surface.descriptor, handlers: host.handlersFor({ pluginId: 'acme-office', surfaceId: 'resource-chooser' }) });
    const dispatch = (action: string, payload: unknown = {}) => dispatcher.dispatch({ action, payload, context });

    expect(await host.bootstrapData({ context })).toEqual({ appId: 'app-123' });
    expect(await dispatch('read-status')).toEqual({ ok: true, result: { status: 'connected', account: 'person@example.test' } });
    const started = await dispatch('choose-resource');
    expect(started).toEqual({ ok: true, result: { authorizationUrl: 'https://auth.example.test/authorize?state=s1', attemptId: 'attempt-1', expiresAt: '2026-10-20T00:10:00.000Z' } });

    // The host's callback route, after the sign-in completed: deposits the declared callback field.
    fake.inbox.deposit({ workspaceId: WORKSPACE_ID, pluginId: 'acme-office', connectionId: 'account', attemptId: 'attempt-1', fields: { 'picked-id': 'res-42' } });
    expect(await dispatch('finish-choice', { attemptId: 'attempt-1' })).toEqual({ ok: true, result: { saved: true, resourceId: 'res-42' } });
    expect(await dispatch('finish-choice', { attemptId: 'attempt-1' })).toEqual({ ok: false, error: { code: 'choice-missing', message: 'Choose the resource again.', retryable: false } });

    expect(fake.log.requests).toEqual([{ url: 'https://api.example.test/resources/res-42', headers: { authorization: `Bearer ${FAKE_TOKEN}` } }]);
    expect([...fake.state.values()]).toEqual([{ resourceId: 'res-42' }]);
    expect(fake.log.calls).toEqual([
      'acme-office:publicConfig.get:{"name":"ACME_APP_ID"}',
      'acme-office:status:{"connectionId":"account"}',
      'acme-office:begin:{"connectionId":"account","action":"add-scopes","scopeSetIds":["files"],"startParams":{"selection-mode":"one"}}',
      'acme-office:state.set:{"key":"selection"}',
    ]);
  });
});

const PRODUCT_HANDLERS = `export default {
  actions: {
    async 'set-product'({ input, capabilities }) {
      await capabilities.state.set({ key: 'products', value: { tables: input.on } });
      return { on: input.on };
    },
  },
};
`;
const OFF_MESSAGE = "Tables is turned off in this plugin's settings; turn it on and retry.";
const LIST_TABLES = `export default {
  async invoke({ capabilities }) {
    const products = await capabilities.state.get({ key: 'products' });
    if (products?.tables !== true) throw new Error(${JSON.stringify(OFF_MESSAGE)});
    return { tables: ['leads'] };
  },
};
`;
const PRODUCT_SURFACES = JSON.stringify({ schemaVersion: 1, surfaces: [{
  id: 'products', title: 'Products', entry: 'surface/index.html', handlerModule: 'server/handlers.mjs',
  actions: [{ name: 'set-product', input: object({ on: { type: 'boolean' } }, ['on']), result: object({ on: { type: 'boolean' } }, ['on']) }],
}] });

test('a product flag the surface writes is what the same plugin\'s tool reads: turning it off blocks the tool', async () => {
  await withWorkspace(async (workspaceRoot) => {
    await installPlugin({ workspaceRoot, pluginId: 'acme-office', files: {
      [FILENAME]: PRODUCT_SURFACES, 'surface/index.html': '<!doctype html>', 'server/handlers.mjs': PRODUCT_HANDLERS,
      [TOOLS_FILENAME]: toolsFile([{ name: 'list_tables', description: 'List tables.', effect: 'read', module: 'tools/list-tables.mjs', inputSchema: object({}) }]),
      'tools/list-tables.mjs': LIST_TABLES,
    } });
    const loader = createPluginContributionLoader({
      findPackages: (query) => findTrustedPluginPackages(query),
      readFile: ({ plugin, filename }) => readTrustedPluginFile(plugin, filename),
      importModule: ({ plugin, modulePath }) => importContainedModule(plugin, modulePath),
    });
    const fake = createFakeSurfaceHost();
    const surfaceHost = createAdminSurfaceHandlerHost({ hostKind: 'hosted', issuedTokens: createIssuedTokenMemories(), capabilities: fake.port });
    const surfaces = await loader.loadPluginContributions({ workspaceId: WORKSPACE_ID, definition: defineAdminSurfaceContribution({ filename: FILENAME }) });
    const handlerLoad = await loader.loadPluginContributions({ workspaceId: WORKSPACE_ID, definition: defineAdminSurfaceHandlerContribution({ filename: FILENAME }) });
    expect([...surfaces.refusals, ...surfaceHost.sync({ loaded: handlerLoad.items, refusals: handlerLoad.refusals }).refusals]).toEqual([]);
    // The host builds the tool port over the same store its surface port uses, scoped the same way.
    const tools = createHarness({ capabilities: (scope) => ({ ...fakeCapabilities(fake.log), state: fake.port(scope).state }) });
    expect(await tools.refresh()).toEqual([]);
    const dispatcher = createAdminSurfaceActionDispatcher({ descriptor: surfaces.items[0]!.descriptor, handlers: surfaceHost.handlersFor({ pluginId: 'acme-office', surfaceId: 'products' }) });
    const setProduct = (on: boolean) => dispatcher.dispatch({ action: 'set-product', payload: { on }, context: { workspaceId: WORKSPACE_ID, principalId: 'admin-1', pluginId: 'acme-office', surfaceId: 'products' } });

    await expect(tools.invoke('p_acme_office__list_tables', {})).rejects.toThrow(OFF_MESSAGE);
    expect(await setProduct(true)).toEqual({ ok: true, result: { on: true } });
    expect(await tools.invoke('p_acme_office__list_tables', {})).toEqual({ tables: ['leads'] });
    expect(await setProduct(false)).toEqual({ ok: true, result: { on: false } });
    await expect(tools.invoke('p_acme_office__list_tables', {})).rejects.toThrow(OFF_MESSAGE);
    expect(fake.log.calls).toEqual(['acme-office:state.set:{"key":"products"}', 'acme-office:state.set:{"key":"products"}']);
  });
});

