/** Admin tools retain the screen's schema, capability, permission and revocation boundaries. */
import { describe, expect, test } from 'vitest';
import { buildAdminSurfaceActionTools } from '../action-tools.js';
import { createAdminSurfaceActionDispatcher } from '../action-dispatcher.js';
import { parseAdminSurfacesFile, type AdminSurfaceDescriptor } from '../descriptor.js';
import { createAdminSurfaceHandlerHost, type LoadedAdminSurfaceHandlers } from '../surface-handlers.js';
import { createAgentPluginToolProjection } from '../../lifecycle/tools/projection.js';
import { createIssuedTokenMemories } from '../../lifecycle/tools/capabilities.js';
import { fakeCapabilities } from '../../lifecycle/tools/__tests__/support.js';
import { createFakeSurfaceHost } from './surface-support.js';
import { createPluginContributionRegistry, pluginToolIdFor } from '@jini-ai/plugins/host';

const input = { type: 'object', properties: { value: { type: 'string' } }, required: ['value'] } as const;
const context = { workspaceId: 'workspace', principalId: 'owner', pluginId: 'acme', surfaceId: 'account' };
function descriptor(effect?: unknown): AdminSurfaceDescriptor {
  const parsed = parseAdminSurfacesFile({ raw: JSON.stringify({ schemaVersion: 1, surfaces: [{ id: 'account', title: 'Account', entry: 'index.html', handlerModule: 'handlers.mjs',
    actions: [{ name: 'save', input, result: { type: 'string' }, ...(effect === undefined ? {} : { effect }) }] }] }) });
  if (!parsed.ok) throw new Error(parsed.reason);
  return parsed.descriptors[0]!;
}
function fixture() {
  const surface = descriptor();
  const fake = createFakeSurfaceHost();
  const issuedTokens = createIssuedTokenMemories();
  const host = createAdminSurfaceHandlerHost({ capabilities: fake.port, issuedTokens, hostKind: 'hosted' });
  const calls: unknown[] = [];
  const loaded: LoadedAdminSurfaceHandlers = { pluginId: 'acme', descriptor: { ...surface, handlerModule: 'handlers.mjs' }, module: { actions: {
    save: async ({ input: value, capabilities, context: scope }) => { calls.push({ value, scope }); await capabilities.state.set({ key: 'saved', value: 'yes' }); return 'saved'; },
  } } };
  host.sync({ loaded: [loaded], refusals: [] });
  let allowed = true;
  const tools = buildAdminSurfaceActionTools({ surfaces: [{ pluginId: 'acme', descriptor: surface }], handlersFor: host.handlersFor,
    authorize: async ({ context: who }) => { expect(who).toEqual(context); if (!allowed) throw new Error('denied'); },
  });
  const call = (value: unknown) => tools[0]!.tool.handler({ pluginId: 'acme', auth: context, input: value });
  return { surface, host, tools, calls, call, deny: () => { allowed = false; }, fake, issuedTokens };
}

describe('admin action tools', () => {
  test('declares the effect with write as the default and rejects unknown/null effects', () => {
    expect(descriptor().actions[0]!.effect).toBe('write');
    expect(descriptor('read').actions[0]!.effect).toBe('read');
    expect(descriptor('destructive').actions[0]!.effect).toBe('destructive');
    expect(() => descriptor('execute')).toThrow(/effect/);
    expect(() => descriptor(null)).toThrow(/effect/);
  });
  test('namespaces surface/action and calls exactly the screen handler with its capability scope', async () => {
    const f = fixture();
    expect(f.tools[0]!.tool.name).toBe('account_save');
    expect(f.tools[0]!.tool.effect).toBe('write');
    const screen = createAdminSurfaceActionDispatcher({ descriptor: f.surface, handlers: f.host.handlersFor(context) });
    const payload = { value: 'hello' };
    expect(await f.call({ payload })).toEqual(await screen.dispatch({ action: 'save', payload, context }));
    expect(f.calls).toHaveLength(2);
    expect(f.fake.log.calls).toEqual(['acme:state.set:{"key":"saved"}', 'acme:state.set:{"key":"saved"}']);
    expect(f.fake.state.get('workspace\u0000acme\u0000saved')).toBe('yes');
  });
  test('enforces permission before any handler/capability call', async () => {
    const f = fixture(); f.deny();
    await expect(f.call({ payload: { value: 'hello' } })).rejects.toThrow('denied');
    expect(f.calls).toEqual([]); expect(f.fake.log.calls).toEqual([]);
  });
  test.each([{}, { payload: {} }, { payload: { value: 1 } }, { payload: { value: 'x', extra: true } }, { payload: { value: 'x' }, extra: true }])('refuses invalid input %j before execution and disclosure', async (bad) => {
    const f = fixture();
    await expect(f.call(bad)).rejects.toThrow(/payload/);
    expect(() => f.tools[0]!.describeAffectedResources({ input: bad })).toThrow(/payload/);
    expect(f.calls).toEqual([]);
  });
  test('uses dispatcher result validation and returns a browser URL without opening anything', async () => {
    const f = fixture();
    const tools = buildAdminSurfaceActionTools({ surfaces: [{ pluginId: 'acme', descriptor: f.surface }], authorize: async () => {},
      handlersFor: () => ({ save: async () => ({ undeclared: true }) }),
    });
    expect(await tools[0]!.tool.handler({ pluginId: 'acme', auth: context, input: { payload: { value: 'hello' } } })).toMatchObject({ ok: false, error: { code: 'invalid-result' } });
    const links = buildAdminSurfaceActionTools({ surfaces: [{ pluginId: 'acme', descriptor: f.surface }], authorize: async () => {}, handlersFor: () => ({ save: async () => 'https://auth.example.test/sign-in' }) });
    expect(await links[0]!.tool.handler({ pluginId: 'acme', auth: context, input: { payload: { value: 'hello' } } })).toEqual({ ok: true, result: 'https://auth.example.test/sign-in' });
  });
  test('shares projection withdrawal with executable tools; stale handlers cannot act', async () => {
    const f = fixture(); const registry = createPluginContributionRegistry({});
    const projection = createAgentPluginToolProjection({ registry, toolIdFor: pluginToolIdFor, issuedTokens: f.issuedTokens,
      capabilities: () => fakeCapabilities({ tokenRequests: [], requests: [] }),
    });
    expect(projection.sync({ loaded: [], refusals: [], additionalTools: f.tools }).refusals).toEqual([]);
    const snapshot = registry.list({})[0]!;
    const held = snapshot.tools[0]!;
    expect(await projection.describeAffectedResources({ toolId: 'p_acme__account_save', input: { payload: { value: 'x' } } })).toEqual({ effect: 'write', resources: ['Account: save'] });
    projection.sync({ loaded: [], refusals: [] });
    expect(registry.list({})).toEqual([]);
    expect(await projection.describeAffectedResources({ toolId: 'p_acme__account_save', input: {} })).toBeNull();
    expect(() => held.handler({ pluginId: 'acme', sdk: snapshot.sdk, auth: { ...context, access: 'admin' }, input: { payload: { value: 'x' } } })).toThrow(/disabled/);
    expect(f.calls).toEqual([]);
  });
  test('refuses colliding ids across surface variants instead of selecting a handler', () => {
    const f = fixture(); const registry = createPluginContributionRegistry({});
    const projection = createAgentPluginToolProjection({ registry, toolIdFor: pluginToolIdFor, issuedTokens: f.issuedTokens,
      capabilities: () => fakeCapabilities({ tokenRequests: [], requests: [] }),
    });
    const result = projection.sync({ loaded: [], refusals: [], additionalTools: [...f.tools, ...f.tools] });
    expect(result.refusals).toEqual(["agent tool 'p_acme__account_save' was not loaded: more than one contribution declares it"]);
    expect(registry.list({}).flatMap(row => row.tools)).toEqual([]);
  });
  test('a hand-built descriptor without an effect projects a write tool', () => {
    const { effect: _dropped, ...action } = descriptor().actions[0]!;
    const surface = { ...descriptor(), actions: [action] };
    const [tool] = buildAdminSurfaceActionTools({ surfaces: [{ pluginId: 'acme', descriptor: surface }], handlersFor: () => ({}), authorize: async () => undefined });
    expect(tool!.tool.effect).toBe('write');
  });
  test('refuses an unauthenticated call before authorization or any handler runs', async () => {
    const f = fixture();
    const authorized: unknown[] = [];
    const tools = buildAdminSurfaceActionTools({ surfaces: [{ pluginId: 'acme', descriptor: f.surface }], handlersFor: f.host.handlersFor,
      authorize: async input => { authorized.push(input); } });
    await expect(tools[0]!.tool.handler({ pluginId: 'acme', auth: { workspaceId: 'workspace' }, input: { payload: { value: 'x' } } }))
      .rejects.toThrow('Admin actions require an authenticated principal.');
    expect(authorized).toEqual([]);
    expect(f.calls).toEqual([]);
  });
  test('the optional run decorator wraps the same dispatch and can decorate its outcome', async () => {
    const f = fixture();
    const tools = buildAdminSurfaceActionTools({ surfaces: [{ pluginId: 'acme', descriptor: f.surface }], handlersFor: f.host.handlersFor,
      authorize: async () => undefined }, { run: async ({ dispatch }) => ({ decorated: await dispatch() }) });
    const plain = await f.call({ payload: { value: 'hello' } });
    expect(await tools[0]!.tool.handler({ pluginId: 'acme', auth: context, input: { payload: { value: 'hello' } } })).toEqual({ decorated: plain });
    expect(f.calls).toHaveLength(2);
  });
  test('a live projected admin tool runs the same handler; an additional tool without an effect discloses as write', async () => {
    const f = fixture(); const registry = createPluginContributionRegistry({});
    const projection = createAgentPluginToolProjection({ registry, toolIdFor: pluginToolIdFor, issuedTokens: f.issuedTokens,
      capabilities: () => fakeCapabilities({ tokenRequests: [], requests: [] }),
    });
    const tools = buildAdminSurfaceActionTools({ surfaces: [{ pluginId: 'acme', descriptor: f.surface }], handlersFor: f.host.handlersFor, authorize: async () => undefined });
    const { effect: _dropped, ...withoutEffect } = tools[0]!.tool;
    const failing = { pluginId: 'acme', tool: { ...withoutEffect, name: 'account_probe' }, describeAffectedResources: () => { throw new Error('resource lookup failed'); } };
    const plain = { ...failing, tool: { ...withoutEffect, name: 'account_plain' }, describeAffectedResources: () => ['Account: plain'] };
    expect(projection.sync({ loaded: [], refusals: [], additionalTools: [...tools, failing, plain] }).refusals).toEqual([]);
    const snapshot = registry.list({})[0]!;
    const live = snapshot.tools.find(tool => tool.name === 'account_save')!;
    expect(await live.handler({ pluginId: 'acme', sdk: snapshot.sdk, auth: { ...context, access: 'admin' }, input: { payload: { value: 'live' } } })).toEqual(await f.call({ payload: { value: 'live' } }));
    expect(f.calls).toHaveLength(2);
    expect(await projection.describeAffectedResources({ toolId: 'p_acme__account_plain', input: {} })).toEqual({ effect: 'write', resources: ['Account: plain'] });
    await expect(projection.describeAffectedResources({ toolId: 'p_acme__account_probe', input: {} })).rejects.toThrow('resource lookup failed');
  });
});

src/admin-surfaces/__tests__/external-li.source:
/**
 * @file Security pins (phase A) for host-mediated external links: a surface may only declare bare
 * https origins (bounded, unique), and an `open-link` message reaches the host's opener only from
 * this mount's frame, with this mount's nonce, for a well-formed https URL on a declared origin.
 * Every refusal names a code and never echoes the URL; the opener receives the parser's normalized
 * form, so the host never re-parses a string the gate judged differently.
 */
import { describe, expect, test } from 'vitest';
import { createAdminSurfaceClient } from '../surface-client.js';
import { openAdminSurfaceLink, parseAdminSurfacesFile, type AdminSurfaceDescriptor, type AdminSurfaceMessageEvent, type AdminSurfaceMountRecord } from '../index.js';

const surface = (overrides: Record<string, unknown> = {}) => ({ id: 'settings', title: 'Settings', entry: 'surface/index.html', ...overrides });
const raw = (overrides: Record<string, unknown>) => JSON.stringify({ schemaVersion: 1, surfaces: [surface(overrides)] });
function parseOne(overrides: Record<string, unknown> = {}): AdminSurfaceDescriptor {
  const parsed = parseAdminSurfacesFile({ raw: raw(overrides) });
  if (!parsed.ok) throw new Error(parsed.reason);
  return parsed.descriptors[0]!;
}
const reasonFor = (overrides: Record<string, unknown>) => {
  const parsed = parseAdminSurfacesFile({ raw: raw(overrides) });
  return parsed.ok ? 'accepted' : parsed.reason;
};

describe('declared link origins', () => {
  test('bare https origins are kept as declared', () => {
    expect(parseOne({ linkOrigins: ['https://accounts.example.com', 'https://docs.example.com:8443'] }).linkOrigins).toEqual(['https://accounts.example.com', 'https://docs.example.com:8443']);
  });
  test.each(['http://accounts.example.com', 'https://*.example.com', 'https://accounts.example.com/path', 'https://127.0.0.1', 'javascript:alert(1)', 'data:text/html,x', 'https://accounts.example.com:443', 'https://user@accounts.example.com', 42])('origin %j is refused', (origin) => {
    expect(reasonFor({ linkOrigins: [origin] })).toBe('surfaces[0].linkOrigins[0] must be a unique bare https origin (no wildcards, paths or keywords)');
  });
  test('a duplicate origin is refused', () => {
    expect(reasonFor({ linkOrigins: ['https://a.example.com', 'https://a.example.com'] })).toBe('surfaces[0].linkOrigins[1] must be a unique bare https origin (no wildcards, paths or keywords)');
  });
  test('more than 8 origins are refused', () => {
    const origins = Array.from({ length: 9 }, (_, index) => `https://h${index}.example.com`);
    expect(reasonFor({ linkOrigins: origins })).toBe('surfaces[0].linkOrigins must be an array of at most 8');
  });
});

describe('open-link gate', () => {
  const frame = {};
  const mount: AdminSurfaceMountRecord = { mountId: 'nonce-1', frame, descriptor: parseOne({ linkOrigins: ['https://accounts.example.com'] }) };
  const message = (overrides: Record<string, unknown> = {}) => ({ protocol: 'jini.admin-surface', version: 1, kind: 'open-link', mountId: 'nonce-1', requestId: 'r1', url: 'https://accounts.example.com/permissions', ...overrides });
  const event = (overrides: Partial<AdminSurfaceMessageEvent> = {}, data: unknown = message()): AdminSurfaceMessageEvent => ({ origin: 'null', source: frame, data, ...overrides });
  function opener(optional: { readonly fails?: boolean } = {}) {
    const opened: string[] = [];
    const openLink = async ({ url }: { readonly url: string }) => { if (optional.fails) throw new Error('shell refused https://accounts.example.com/secret'); opened.push(url); };
    return { opened, openLink };
  }
  const refusal = (code: string, text: string, retryable = false) => ({
    ok: false, refused: code,
    response: { protocol: 'jini.admin-surface', version: 1, kind: 'action-response', mountId: 'nonce-1', requestId: 'r1', ok: false, error: { code, message: text, retryable } },
  });

  test('a declared https link is handed to the host opener in normalized form and answered', async () => {
    const { opened, openLink } = opener();
    const verdict = await openAdminSurfaceLink({ event: event({}, message({ url: 'https://ACCOUNTS.example.com:443/permissions?x=1' })), mount, openLink });
    expect(opened).toEqual(['https://accounts.example.com/permissions?x=1']);
    expect(verdict).toEqual({ ok: true, url: 'https://accounts.example.com/permissions?x=1', response: { protocol: 'jini.admin-surface', version: 1, kind: 'action-response', mountId: 'nonce-1', requestId: 'r1', ok: true, result: null } });
  });
  test('an undeclared origin is refused without opening or echoing the URL', async () => {
    const { opened, openLink } = opener();
    expect(await openAdminSurfaceLink({ event: event({}, message({ url: 'https://evil.example.net/phish' })), mount, openLink }))
      .toEqual(refusal('link-undeclared', 'This surface did not declare that link destination.'));
    expect(opened).toEqual([]);
  });
  test('a surface that declares no link origins can open nothing', async () => {
    const { opened, openLink } = opener();
    const bare: AdminSurfaceMountRecord = { ...mount, descriptor: parseOne() };
    expect(await openAdminSurfaceLink({ event: event(), mount: bare, openLink })).toEqual(refusal('link-undeclared', 'This surface did not declare that link destination.'));
    expect(opened).toEqual([]);
  });
  test.each(['http://accounts.example.com/permissions', 'javascript:alert(document.domain)', 'data:text/html,<script>alert(1)</script>', 'JAVASCRIPT://accounts.example.com/%0aalert(1)'])('non-https link %j is refused', async (url) => {
    const { opened, openLink } = opener();
    expect(await openAdminSurfaceLink({ event: event({}, message({ url })), mount, openLink })).toEqual(refusal('link-not-https', 'Only https links can be opened.'));
    expect(opened).toEqual([]);
  });
  test.each(['not a url', 'https://user:pass@accounts.example.com/permissions'])('malformed or credential-carrying link %j is refused', async (url) => {
    const { opened, openLink } = opener();
    expect(await openAdminSurfaceLink({ event: event({}, message({ url })), mount, openLink })).toEqual(refusal('link-invalid', 'That link is not a valid web address.'));
    expect(opened).toEqual([]);
  });
  test('a link longer than 2048 characters is refused', async () => {
    const { opened, openLink } = opener();
    const url = `https://accounts.example.com/${'a'.repeat(2048 - 'https://accounts.example.com/'.length + 1)}`;
    expect(await openAdminSurfaceLink({ event: event({}, message({ url })), mount, openLink })).toEqual(refusal('link-too-long', 'The link is too long.'));
    expect(opened).toEqual([]);
  });
  test('a link of exactly 2048 characters is opened', async () => {
    const { opened, openLink } = opener();
    const url = `https://accounts.example.com/${'a'.repeat(2048 - 'https://accounts.example.com/'.length)}`;
    await openAdminSurfaceLink({ event: event({}, message({ url })), mount, openLink });
    expect(opened).toEqual([url]);
  });
  test('a wrong mount nonce is ignored and opens nothing', async () => {
    const { opened, openLink } = opener();
    expect(await openAdminSurfaceLink({ event: event({}, message({ mountId: 'nonce-2' })), mount, openLink })).toEqual({ ok: false, ignored: 'mount-mismatch' });
    expect(opened).toEqual([]);
  });
  test('another sandboxed frame is ignored', async () => {
    const { openLink } = opener();
    expect(await openAdminSurfaceLink({ event: event({ source: {} }), mount, openLink })).toEqual({ ok: false, ignored: 'source-mismatch' });
  });
  test('a non-sandboxed origin is ignored', async () => {
    const { openLink } = opener();
    expect(await openAdminSurfaceLink({ event: event({ origin: 'https://accounts.example.com' }), mount, openLink })).toEqual({ ok: false, ignored: 'origin-mismatch' });
  });
  test.each([
    ['an action request', { kind: 'action-request' }],
    ['a non-string url', { url: 42 }],
    ['a malformed request id', { requestId: 'has space' }],
  ])('%s is not an open-link message', async (_label, overrides) => {
    const { openLink } = opener();
    expect(await openAdminSurfaceLink({ event: event({}, message(overrides)), mount, openLink })).toEqual({ ok: false, ignored: 'not-an-open-link' });
  });
  test.each(['open-link', null])('non-object message data %j is not an open-link message', async (data) => {
    const { openLink } = opener();
    expect(await openAdminSurfaceLink({ event: event({}, data), mount, openLink })).toEqual({ ok: false, ignored: 'not-an-open-link' });
  });
  test('an opener failure is answered as retryable without its raw text', async () => {
    const { openLink } = opener({ fails: true });
    expect(await openAdminSurfaceLink({ event: event(), mount, openLink })).toEqual(refusal('link-failed', 'The host could not open the link. Try again.', true));
  });
});

test('the surface client posts open-link only to the host origin learned from init and rejects with the host refusal', async () => {
  const posted: Array<{ readonly message: unknown; readonly targetOrigin: string }> = [];
  const parent = { postMessage(message: unknown, targetOrigin: string) { posted.push({ message, targetOrigin }); } };
  let deliver: (event: { readonly origin: string; readonly source: unknown; readonly data: unknown }) => void = () => {};
  const client = createAdminSurfaceClient({ parent, listen: (handler) => { deliver = handler; return () => {}; } });
  const base = { protocol: 'jini.admin-surface', version: 1, mountId: 'nonce-1' };
  deliver({ origin: 'https://host.example.com', source: parent, data: { ...base, kind: 'init' } });
  const pending = client.openLink({ url: 'https://elsewhere.example.net/' });
  await Promise.resolve();
  expect(posted).toEqual([{ message: { ...base, kind: 'open-link', requestId: 'r1', url: 'https://elsewhere.example.net/' }, targetOrigin: 'https://host.example.com' }]);
  deliver({ origin: 'https://host.example.com', source: parent, data: { ...base, kind: 'action-response', requestId: 'r1', ok: false, error: { code: 'link-undeclared', message: 'This surface did not declare that link destination.', retryable: false } } });
  await expect(pending).rejects.toMatchObject({ name: 'AdminSurfaceCallError', code: 'link-undeclared' });
  client.close();
});

src/lifecycle/tools/__tests__/capability.source:
/**
 * @file Security unit tests for the shared capability gate's credential scans: a result or error is
 * released only when its serialized form cannot be shown to omit every token this plugin obtained.
 * Unserializable values fail closed, escaped tokens are still found, and an error is walked through
 * every own property (the JSON-invisible `cause` and `AggregateError.errors` too), Map and Set
 * contents, to any depth within a node bound; an unreadable or oversized error is withheld. Tokens are built at runtime; no credential literal.
 */
import { describe, expect, test } from 'vitest';
import {
  REVOKED_MESSAGE, WITHHELD_ERROR_MESSAGE, WITHHELD_OUTPUT_MESSAGE, checkedStateKey, createIssuedTokenMemories, openCapabilityGate,
} from '../capabilities.js';

const TOKEN = ['tok', 'en', '-', 'y'.repeat(24)].join('');

function gateWith(tokens: readonly string[], optional: { readonly live?: () => boolean } = {}) {
  const issued = createIssuedTokenMemories().forPlugin({ pluginId: 'acme-office' });
  const gate = openCapabilityGate({ isLive: optional.live ?? (() => true), issued });
  for (const token of tokens) gate.noteToken({ token });
  return { gate, issued };
}

describe('release (result gate)', () => {
  test('with no token issued, even an unserializable value is released untouched', () => {
    const circular: Record<string, unknown> = {};
    circular.self = circular;
    expect(gateWith([]).gate.release({ value: circular })).toBe(circular);
  });

  test('an unserializable value fails closed once a token was issued', () => {
    const circular: Record<string, unknown> = {};
    circular.self = circular;
    expect(() => gateWith([TOKEN]).gate.release({ value: circular })).toThrow(WITHHELD_OUTPUT_MESSAGE);
  });

  test('a value with no JSON form (undefined) is released, since it cannot carry a token', () => {
    expect(gateWith([TOKEN]).gate.release({ value: undefined })).toBeUndefined();
  });

  test('a token nested in the result is withheld', () => {
    expect(() => gateWith([TOKEN]).gate.release({ value: { rows: [[`Bearer ${TOKEN}`]] } })).toThrow(WITHHELD_OUTPUT_MESSAGE);
  });

  test('a token that JSON escapes is still found in its escaped form', () => {
    const escaped = `${TOKEN}"\\`;
    expect(() => gateWith([escaped]).gate.release({ value: { note: escaped } })).toThrow(WITHHELD_OUTPUT_MESSAGE);
  });

  test('a clean result is released as the same value', () => {
    const value = { rows: [['a']] };
    expect(gateWith([TOKEN]).gate.release({ value })).toBe(value);
  });
});

describe('sanitize (error gate)', () => {
  function chain(depth: number, deepestMessage: string): Error {
    let error = new Error(deepestMessage);
    for (let level = 0; level < depth; level += 1) error = new Error(`level ${level}`, { cause: error });
    return error;
  }

  test('a token in an own field of the error is withheld', () => {
    const error = Object.assign(new Error('failed'), { detail: TOKEN });
    expect(gateWith([TOKEN]).gate.sanitize({ error })).toEqual(new Error(WITHHELD_ERROR_MESSAGE));
  });

  test('a token three causes deep is found through the stringified tail of the chain', () => {
    expect(gateWith([TOKEN]).gate.sanitize({ error: chain(3, `upstream said ${TOKEN}`) })).toEqual(new Error(WITHHELD_ERROR_MESSAGE));
  });

  test('the replacement error carries no cause', () => {
    const replaced = gateWith([TOKEN]).gate.sanitize({ error: chain(1, TOKEN) }) as Error;
    expect(replaced.cause).toBeUndefined();
  });

  test('a clean cause chain passes through as the same error', () => {
    const error = chain(3, 'upstream said no');
    expect(gateWith([TOKEN]).gate.sanitize({ error })).toBe(error);
  });

  test('a thrown non-error value is scanned as itself', () => {
    expect(gateWith([TOKEN]).gate.sanitize({ error: `raw ${TOKEN}` })).toEqual(new Error(WITHHELD_ERROR_MESSAGE));
  });

  test('a token inside an AggregateError (non-enumerable errors) is withheld', () => {
    const error = new AggregateError([new Error('first'), new Error(`Authorization: Bearer ${TOKEN}`)], 'all failed');
    expect(gateWith([TOKEN]).gate.sanitize({ error })).toEqual(new Error(WITHHELD_ERROR_MESSAGE));
  });

  test('a clean AggregateError passes through as the same error', () => {
    const error = new AggregateError([new Error('first'), new Error('second')], 'all failed');
    expect(gateWith([TOKEN]).gate.sanitize({ error })).toBe(error);
  });

  test('a token six causes deep is withheld', () => {
    expect(gateWith([TOKEN]).gate.sanitize({ error: chain(6, `upstream said ${TOKEN}`) })).toEqual(new Error(WITHHELD_ERROR_MESSAGE));
  });

  test('a token in an error held by a plain-object cause is withheld', () => {
    const error = new Error('failed', { cause: { response: { inner: new Error(`echo ${TOKEN}`) } } });
    expect(gateWith([TOKEN]).gate.sanitize({ error })).toEqual(new Error(WITHHELD_ERROR_MESSAGE));
  });

  test('a token in a non-enumerable own field is withheld', () => {
    const error = Object.defineProperty(new Error('failed'), 'header', { value: `Bearer ${TOKEN}`, enumerable: false });
    expect(gateWith([TOKEN]).gate.sanitize({ error })).toEqual(new Error(WITHHELD_ERROR_MESSAGE));
  });

  test('a token held in a Map inside the cause is withheld', () => {
    const error = new Error('failed', { cause: { headers: new Map([['authorization', `Bearer ${TOKEN}`]]) } });
    expect(gateWith([TOKEN]).gate.sanitize({ error })).toEqual(new Error(WITHHELD_ERROR_MESSAGE));
  });

  test('a token held in a Set inside the cause is withheld', () => {
    const error = new Error('failed', { cause: new Set([`Bearer ${TOKEN}`]) });
    expect(gateWith([TOKEN]).gate.sanitize({ error })).toEqual(new Error(WITHHELD_ERROR_MESSAGE));
  });

  test('a cause chain too long to scan fails closed', () => {
    expect(gateWith([TOKEN]).gate.sanitize({ error: chain(300, 'clean all the way down') })).toEqual(new Error(WITHHELD_ERROR_MESSAGE));
  });

  test('a cyclic cause chain is scanned once and passes through when clean', () => {
    const error = new Error('loop');
    error.cause = error;
    expect(gateWith([TOKEN]).gate.sanitize({ error })).toBe(error);
  });

  test('a field whose getter throws fails closed', () => {
    const error = Object.defineProperty(new Error('failed'), 'detail', { get() { throw new Error('unreadable'); }, enumerable: false });
    expect(gateWith([TOKEN]).gate.sanitize({ error })).toEqual(new Error(WITHHELD_ERROR_MESSAGE));
  });

  test('an error holding a very large array of strings is scanned without throwing', () => {
    const error = Object.assign(new Error('failed'), { lines: Array.from({ length: 300_000 }, () => 'clean') });
    expect(gateWith([TOKEN]).gate.sanitize({ error })).toBe(error);
  });

  test('with no token issued, any error passes through untouched', () => {
    const error = chain(300, 'clean');
    expect(gateWith([]).gate.sanitize({ error })).toBe(error);
  });
});

describe('token memory and revocation', () => {
  test('one memory per plugin: a token noted in one session is withheld by the next, not by another plugin', () => {
    const memories = createIssuedTokenMemories();
    const open = (pluginId: string) => openCapabilityGate({ isLive: () => true, issued: memories.forPlugin({ pluginId }) });
    open('acme-office').noteToken({ token: TOKEN });
    expect(() => open('acme-office').release({ value: TOKEN })).toThrow(WITHHELD_OUTPUT_MESSAGE);
    expect(open('other-plugin').release({ value: TOKEN })).toBe(TOKEN);
  });

  test('an empty token is returned but never remembered', () => {
    const { gate, issued } = gateWith([]);
    expect(gate.noteToken({ token: '' })).toBe('');
    expect(issued.size).toBe(0);
  });

  test('mentionsToken reports a remembered token', () => {
    const { gate } = gateWith([TOKEN]);
    expect([gate.mentionsToken({ value: { a: TOKEN } }), gate.mentionsToken({ value: { a: 'clean' } })]).toEqual([true, false]);
  });

  test('a guarded capability refuses once the plugin is no longer live', async () => {
    let live = true;
    const { gate } = gateWith([], { live: () => live });
    const call = gate.guard(async () => 'called');
    await expect(call()).resolves.toBe('called');
    live = false;
    await expect(call()).rejects.toThrow(REVOKED_MESSAGE);
  });
});

describe('checkedStateKey', () => {
  test('passes a dotted, coloned key of 128 characters', () => {
    const key = `a.b:c-${'d'.repeat(122)}`;
    expect(checkedStateKey({ key })).toBe(key);
  });

  test('refuses a key starting with a separator', () => {
    expect(() => checkedStateKey({ key: '.hidden' })).toThrow('A settings key must be a short name of at most 128 characters.');
  });
});

