/**
 * @file Unit tests for the admin-surface `deliveryBindings` port's shapes and bounds: what the host
 * receives on save (a checked copy with only the known fields), what the plugin gets back (the port's
 * shape, never the host's connection ref), updating and removing the surface's own bindings, and the
 * refusals for a malformed draft (enabled flag, form ids, config) or an unknown binding id. The host is the shared
 * typed fake; no network.
 */
import { describe, expect, test } from 'vitest';
import { WORKSPACE_ID } from '../../lifecycle/tools/__tests__/support.js';
import type { AdminSurfaceCapabilityDeclarations } from '../capability-declarations.js';
import type { AdminSurfaceDeliveryBinding, AdminSurfaceDeliveryBindingDraft } from '../delivery-bindings.js';
import { openAdminSurfaceCapabilitySession } from '../surface-capabilities.js';
import { createFakeSurfaceHost } from './surface-support.js';

const DECLARED: AdminSurfaceCapabilityDeclarations = { connections: [{ id: 'account', startParams: [], callbackFields: [] }], deliveryAdapters: ['acme-rows', 'acme-notes'] };
const OURS: AdminSurfaceDeliveryBinding = { bindingId: 'ours-1', adapterId: 'acme-rows', connectionId: 'account', enabled: false, formIds: ['contact'], config: { tab: 7 } };
const DRAFT: AdminSurfaceDeliveryBindingDraft = { adapterId: 'acme-rows', connectionId: 'account', enabled: true, formIds: ['contact'], config: { tab: 1 } };

function open() {
  const fake = createFakeSurfaceHost({ bindings: [OURS] });
  const session = openAdminSurfaceCapabilitySession(
    { capabilities: fake.port({ pluginId: 'acme-office', workspaceId: WORKSPACE_ID }), isLive: () => true, declared: DECLARED, issued: new Set() },
    { actorId: 'admin-1' },
  );
  return { ...fake, port: session.capabilities.deliveryBindings! };
}

describe('save', () => {
  test('a new binding reaches the host as a checked copy with only the known fields', async () => {
    const session = open();
    // Malformed on purpose: a draft carrying a host field must not pass it on.
    await session.port.save({ ...DRAFT, connectionRef: 'ref-from-plugin' } as AdminSurfaceDeliveryBindingDraft);
    expect(session.log.calls).toEqual(['acme-office:bindings.save:{"adapterId":"acme-rows","connectionId":"account","enabled":true,"formIds":["contact"],"config":{"tab":1}}']);
  });
  test('the saved binding comes back in the port shape, without the host\'s connection ref', async () => {
    await expect(open().port.save({ ...DRAFT, formIds: [] })).resolves.toStrictEqual({ bindingId: 'binding-2', adapterId: 'acme-rows', connectionId: 'account', enabled: true, formIds: [], config: { tab: 1 } });
  });
  test('the stored config is a copy the plugin cannot change afterwards', async () => {
    const session = open();
    const config = { tab: 1 };
    await session.port.save({ ...DRAFT, config });
    config.tab = 2;
    expect(session.bindings.get('binding-2')?.config).toStrictEqual({ tab: 1 });
  });
  test('the stored form ids are a copy the plugin cannot change afterwards', async () => {
    const session = open();
    const formIds = ['contact'];
    await session.port.save({ ...DRAFT, formIds });
    formIds.push('quote');
    expect(session.bindings.get('binding-2')?.formIds).toStrictEqual(['contact']);
  });
  test('the surface\'s own binding is updated in place through its id', async () => {
    const session = open();
    await expect(session.port.save({ ...DRAFT, bindingId: 'ours-1', adapterId: 'acme-notes', formIds: ['contact', 'quote'] }))
      .resolves.toStrictEqual({ bindingId: 'ours-1', adapterId: 'acme-notes', connectionId: 'account', enabled: true, formIds: ['contact', 'quote'], config: { tab: 1 } });
    expect(session.bindings.size).toBe(1);
  });
  test('64 form ids are accepted', async () => {
    const formIds = Array.from({ length: 64 }, (_, index) => `form-${index}`);
    await expect(open().port.save({ ...DRAFT, formIds })).resolves.toMatchObject({ formIds });
  });
  test('a config of exactly the size limit is accepted', async () => {
    const config = { pad: 'x'.repeat(16 * 1024 - '{"pad":""}'.length) };
    await expect(open().port.save({ ...DRAFT, config })).resolves.toMatchObject({ bindingId: 'binding-2' });
  });

  // Malformed drafts on purpose (a plugin is JavaScript): each is refused before the host sees it.
  test.each([
    ['not an object', null, 'A delivery binding must be an object.'],
    ['a non-boolean enabled flag', { ...DRAFT, enabled: 'yes' }, 'A delivery binding needs enabled: true or false.'],
    ['form ids that are not an array', { ...DRAFT, formIds: 'contact' }, 'formIds must be at most 64 unique short form ids.'],
    ['65 form ids', { ...DRAFT, formIds: Array.from({ length: 65 }, (_, index) => `form-${index}`) }, 'formIds must be at most 64 unique short form ids.'],
    ['a form id outside the short-id shape', { ...DRAFT, formIds: ['contact', 'a b'] }, 'formIds must be at most 64 unique short form ids.'],
    ['a form id listed twice', { ...DRAFT, formIds: ['contact', 'contact'] }, 'formIds must be at most 64 unique short form ids.'],
    ['a config that is an array', { ...DRAFT, config: [1] }, "A delivery binding's config must be a JSON object."],
    ['a config that is missing', { ...DRAFT, config: undefined }, "A delivery binding's config must be a JSON object."],
    ['a config that is not plain JSON', { ...DRAFT, config: { at: new Date(0) } }, 'A settings value must be plain JSON data'],
  ])('a draft with %s is refused', async (_label, draft, message) => {
    const session = open();
    await expect(session.port.save(draft as unknown as AdminSurfaceDeliveryBindingDraft)).rejects.toThrow(message);
    expect(session.log.calls).toEqual([]);
  });
  test('an undeclared adapter id is cut to 64 characters in the refusal', async () => {
    const long = `x${'y'.repeat(99)}`;
    await expect(open().port.save({ ...DRAFT, adapterId: long })).rejects.toThrow(`This admin surface does not declare delivery adapter '${long.slice(0, 64)}', so`);
  });
  test('an unknown binding id is refused', async () => {
    await expect(open().port.save({ ...DRAFT, bindingId: 'missing' })).rejects.toThrow("No delivery binding 'missing' belongs to this surface's delivery adapters; list the bindings and retry.");
  });
});

describe('list and remove', () => {
  test('a binding the host lists for every form comes back as allForms: true, without a formIds key', async () => {
    const session = open();
    const { formIds: _formIds, ...rest } = OURS as AdminSurfaceDeliveryBinding & { formIds: readonly string[] };
    const everyForm: AdminSurfaceDeliveryBinding = { ...rest, allForms: true };
    session.bindings.set('ours-1', everyForm);
    await expect(session.port.list()).resolves.toStrictEqual([everyForm]);
  });
  test('a listed binding with form ids comes back with a copy of them', async () => {
    const session = open();
    const [listed] = await session.port.list();
    expect([listed, listed?.formIds === session.bindings.get('ours-1')?.formIds]).toStrictEqual([OURS, false]);
  });
  test('the surface\'s own binding is removed through its id', async () => {
    const session = open();
    await expect(session.port.remove({ bindingId: 'ours-1' })).resolves.toBeUndefined();
    expect(session.bindings.size).toBe(0);
    expect(session.log.calls).toEqual(['acme-office:bindings.list:{}', 'acme-office:bindings.remove:{"bindingId":"ours-1"}']);
  });
  test('removing an unknown binding id is refused', async () => {
    await expect(open().port.remove({ bindingId: 'missing' })).rejects.toThrow("No delivery binding 'missing' belongs to this surface's delivery adapters; list the bindings and retry.");
  });
});

src/admin-surfaces/__tests__/issued-toke.source:
/**
 * @file Security pins for the per-plugin issued-token memory: one plugin's tools and its admin-surface
 * handlers run code that can share module scope (a common lib module), so a token one context
 * obtained must be withheld when the OTHER context returns or stores it, and a re-sync (new
 * generation, same cached module) must not forget it. Typed fakes; no network.
 */
import { expect, test } from 'vitest';
import { createPluginContributionRegistry, pluginToolIdFor } from '@jini-ai/plugins/host';
import { createIssuedTokenMemories, WITHHELD_OUTPUT_MESSAGE, type AgentPluginToolCapabilities, type IssuedTokenMemories } from '../../lifecycle/tools/capabilities.js';
import type { LoadedAgentPluginTool } from '../../lifecycle/tools/definition.js';
import { createAgentPluginToolProjection } from '../../lifecycle/tools/projection.js';
import { fakeCapabilities, WORKSPACE_ID } from '../../lifecycle/tools/__tests__/support.js';
import {
  createAdminSurfaceHandlerHost, parseAdminSurfacesFile, type AdminSurfaceDescriptor, type AdminSurfaceHandlerModule,
} from '../index.js';
import { STATE_CREDENTIAL_MESSAGE } from '../surface-capabilities.js';
import { createFakeSurfaceHost } from './surface-support.js';

const PLUGIN = 'acme-office';
/** Built at runtime so no credential-shaped literal is committed; distinct from the surface fake's token. */
const TOOL_TOKEN = ['tok', '-tool-', 'y'.repeat(24)].join('');

function surfaceDescriptor(): AdminSurfaceDescriptor & { readonly handlerModule: string } {
  const parsed = parseAdminSurfacesFile({ raw: JSON.stringify({ schemaVersion: 1, surfaces: [{
    id: 'settings', title: 'Settings', entry: 'surface/index.html', handlerModule: 'server/handlers.mjs', connections: [{ id: 'account' }],
    actions: [{ name: 'save', input: { type: 'object' }, result: { type: 'object' } }],
  }] }) });
  if (!parsed.ok) throw new Error(parsed.reason);
  return parsed.descriptors[0] as AdminSurfaceDescriptor & { readonly handlerModule: string };
}

/** One plugin's tool and surface handler, wired the way a host composes them with ONE token memory. */
function compose(required: { readonly tool: LoadedAgentPluginTool['module']; readonly surface: AdminSurfaceHandlerModule; readonly issuedTokens: IssuedTokenMemories }) {
  const toolCapabilities: AgentPluginToolCapabilities = { ...fakeCapabilities({ tokenRequests: [], requests: [] }), connections: { getAccessToken: async () => TOOL_TOKEN } };
  const registry = createPluginContributionRegistry({});
  const projection = createAgentPluginToolProjection({ registry, toolIdFor: pluginToolIdFor, capabilities: () => toolCapabilities, issuedTokens: required.issuedTokens });
  const loadedTool = (module: LoadedAgentPluginTool['module']): LoadedAgentPluginTool => ({ pluginId: PLUGIN, module,
    descriptor: { name: 'look', description: 'Look.', effect: 'read', module: 'tools/look.mjs', inputSchema: { type: 'object' } } });
  projection.sync({ loaded: [loadedTool(required.tool)], refusals: [] });
  const fake = createFakeSurfaceHost();
  const surfaces = createAdminSurfaceHandlerHost({ hostKind: 'hosted', capabilities: fake.port, issuedTokens: required.issuedTokens });
  surfaces.sync({ loaded: [{ pluginId: PLUGIN, descriptor: surfaceDescriptor(), module: required.surface }], refusals: [] });
  return {
    fake,
    callTool: () => { const snapshot = registry.list({})[0]!; return snapshot.tools[0]!.handler({ pluginId: PLUGIN, sdk: snapshot.sdk, auth: { access: 'admin', workspaceId: WORKSPACE_ID }, input: {} }); },
    callSurface: () => surfaces.handlersFor({ pluginId: PLUGIN, surfaceId: 'settings' }).save!({ payload: {}, context: { workspaceId: WORKSPACE_ID, principalId: 'admin-1', pluginId: PLUGIN, surfaceId: 'settings' } }),
    resyncTool: (module: LoadedAgentPluginTool['module']) => projection.sync({ loaded: [loadedTool(module)], refusals: [] }),
  };
}

test("a token the plugin's TOOL obtained is withheld when its SURFACE handler returns it", async () => {
  let kept = '';
  const plugin = compose({
    issuedTokens: createIssuedTokenMemories(),
    tool: { invoke: async ({ capabilities }) => { kept = await capabilities.connections.getAccessToken({ connectionRef: 'c1' }); return { ok: true }; } },
    surface: { actions: { save: async () => ({ leaked: kept }) } },
  });
  await plugin.callTool();
  await expect(plugin.callSurface()).rejects.toThrow(WITHHELD_OUTPUT_MESSAGE);
});

test("a token the plugin's SURFACE handler obtained is withheld when its TOOL returns it", async () => {
  let kept = '';
  const plugin = compose({
    issuedTokens: createIssuedTokenMemories(),
    tool: { invoke: async () => ({ leaked: kept }) },
    surface: { actions: { save: async ({ capabilities }) => { kept = await capabilities.connections.getAccessToken({ connectionId: 'account' }); return {}; } } },
  });
  await plugin.callSurface();
  await expect(plugin.callTool()).rejects.toThrow(WITHHELD_OUTPUT_MESSAGE);
});

test("a token the plugin's TOOL obtained is never saved by its SURFACE handler's state write", async () => {
  let kept = '';
  const plugin = compose({
    issuedTokens: createIssuedTokenMemories(),
    tool: { invoke: async ({ capabilities }) => { kept = await capabilities.connections.getAccessToken({ connectionRef: 'c1' }); return { ok: true }; } },
    surface: { actions: { save: async ({ capabilities }) => { await capabilities.state.set({ key: 'kept', value: kept }); return {}; } } },
  });
  await plugin.callTool();
  await expect(plugin.callSurface()).rejects.toThrow(STATE_CREDENTIAL_MESSAGE);
  expect(plugin.fake.state.size).toBe(0);
});

test('a re-sync that replaces the tool generation still withholds a token the old generation obtained', async () => {
  let kept = '';
  const plugin = compose({
    issuedTokens: createIssuedTokenMemories(),
    tool: { invoke: async ({ capabilities }) => { kept = await capabilities.connections.getAccessToken({ connectionRef: 'c1' }); return { ok: true }; } },
    surface: { actions: { save: async () => ({}) } },
  });
  await plugin.callTool();
  plugin.resyncTool({ invoke: async () => ({ leaked: kept }) });
  await expect(plugin.callTool()).rejects.toThrow(WITHHELD_OUTPUT_MESSAGE);
});

test("one plugin's memory is not another's: the same memories object keeps plugins apart", () => {
  const memories = createIssuedTokenMemories();
  memories.forPlugin({ pluginId: PLUGIN }).add(TOOL_TOKEN);
  expect([memories.forPlugin({ pluginId: PLUGIN }).has(TOOL_TOKEN), memories.forPlugin({ pluginId: 'other-plugin' }).has(TOOL_TOKEN)]).toEqual([true, false]);
});

src/lifecycle/tools/__tests__/manifest.u.source:
/**
 * @file Unit tests for the tool contribution parser: every rule that refuses a declaration file
 * (version, list bounds, name, description, effect, module, input schema, duplicates) and the
 * shape of an accepted descriptor. Pure: the parser does no I/O.
 */
import { describe, expect, test } from 'vitest';
import { parseAgentPluginToolsFile } from '../manifest.js';

const SCHEMA = { type: 'object', properties: { q: { type: 'string' } } };
const TOOL = { name: 'list_rows', description: 'Lists rows.', effect: 'read', module: 'tools/list.mjs', inputSchema: SCHEMA };

function parse(raw: string) {
  return parseAgentPluginToolsFile({ raw });
}

function parseTools(tools: readonly unknown[]) {
  return parse(JSON.stringify({ schemaVersion: 1, tools }));
}

function withTool(overrides: Record<string, unknown>) {
  return parseTools([{ ...TOOL, ...overrides }]);
}

describe('file shape', () => {
  test('accepts one declaration and returns a frozen descriptor without unknown keys', () => {
    const parsed = parseTools([{ ...TOOL, extra: 'ignored' }]);
    expect(parsed).toEqual({ ok: true, descriptors: [TOOL] });
    expect(Object.isFrozen(parsed.ok ? parsed.descriptors[0] : undefined)).toBe(true);
  });

  test('refuses text that is not JSON', () => {
    expect(parse('{not json')).toEqual({ ok: false, reason: 'not valid JSON' });
  });

  test('refuses a JSON array at the top level', () => {
    expect(parse('[]')).toEqual({ ok: false, reason: 'schemaVersion must be 1' });
  });

  test('refuses another schema version', () => {
    expect(parse(JSON.stringify({ schemaVersion: 2, tools: [TOOL] }))).toEqual({ ok: false, reason: 'schemaVersion must be 1' });
  });

  test('refuses tools that is not an array', () => {
    expect(parse(JSON.stringify({ schemaVersion: 1, tools: { a: TOOL } }))).toEqual({ ok: false, reason: 'tools must list 1 to 128 declarations' });
  });

  test('refuses an empty tool list', () => {
    expect(parseTools([])).toEqual({ ok: false, reason: 'tools must list 1 to 128 declarations' });
  });

  test('accepts exactly 128 declarations', () => {
    const tools = Array.from({ length: 128 }, (_, index) => ({ ...TOOL, name: `tool_${index}` }));
    const parsed = parseTools(tools);
    expect(parsed.ok && parsed.descriptors.length).toBe(128);
  });

  test('refuses 129 declarations', () => {
    const tools = Array.from({ length: 129 }, (_, index) => ({ ...TOOL, name: `tool_${index}` }));
    expect(parseTools(tools)).toEqual({ ok: false, reason: 'tools must list 1 to 128 declarations' });
  });

  test('refuses a declaration that is not an object', () => {
    expect(parseTools([TOOL, 'list_rows'])).toEqual({ ok: false, reason: 'every tool declaration must be an object' });
  });

  test('refuses the whole file when a later declaration is invalid', () => {
    expect(parseTools([TOOL, { ...TOOL, name: 'second', effect: 'admin' }])).toEqual({ ok: false, reason: "tool 'second' effect must be read, write or destructive" });
  });
});

describe('name', () => {
  test.each([['Upper'], ['1digit'], ['has-dash'], [`a${'b'.repeat(64)}`], [7]])('refuses %j', (name) => {
    expect(withTool({ name })).toEqual({ ok: false, reason: 'a tool name must be lower snake case, at most 64 characters' });
  });

  test('accepts a 64-character lower snake case name', () => {
    const name = `a${'b'.repeat(63)}`;
    expect(withTool({ name }).ok).toBe(true);
  });
});

describe('description', () => {
  const reason = "tool 'list_rows' needs a description of at most 8000 characters";

  test('refuses a missing description', () => {
    expect(withTool({ description: undefined })).toEqual({ ok: false, reason });
  });

  test('refuses a whitespace-only description', () => {
    expect(withTool({ description: '   ' })).toEqual({ ok: false, reason });
  });

  test('refuses a description over 8000 characters', () => {
    expect(withTool({ description: 'd'.repeat(8001) })).toEqual({ ok: false, reason });
  });

  test('accepts a description of exactly 8000 characters', () => {
    expect(withTool({ description: 'd'.repeat(8000) }).ok).toBe(true);
  });

  test('a description problem is reported before an effect problem', () => {
    expect(withTool({ description: '', effect: 'admin' })).toEqual({ ok: false, reason });
  });
});

describe('effect', () => {
  test.each(['write', 'destructive'])('accepts %s', (effect) => {
    expect(withTool({ effect }).ok).toBe(true);
  });

  test('an effect problem is reported before a module problem', () => {
    expect(withTool({ effect: 'admin', module: 'x.js' })).toEqual({ ok: false, reason: "tool 'list_rows' effect must be read, write or destructive" });
  });
});

describe('module', () => {
  const reason = "tool 'list_rows' module must be a .mjs path inside the plugin";

  test('refuses a non-string module', () => {
    expect(withTool({ module: 42 })).toEqual({ ok: false, reason });
  });

  test('refuses a module path over 256 characters', () => {
    expect(withTool({ module: `${'m'.repeat(253)}.mjs` })).toEqual({ ok: false, reason });
  });

  test('accepts a module path of exactly 256 characters', () => {
    expect(withTool({ module: `${'m'.repeat(252)}.mjs` }).ok).toBe(true);
  });
});

describe('input schema', () => {
  const reason = 'inputSchema must be a JSON Schema describing an object';

  test('refuses a missing schema', () => {
    expect(withTool({ inputSchema: undefined })).toEqual({ ok: false, reason });
  });

  test('refuses a schema whose type is not object', () => {
    expect(withTool({ inputSchema: { type: 'string' } })).toEqual({ ok: false, reason });
  });

  test('refuses a schema larger than 64 KiB', () => {
    expect(withTool({ inputSchema: { type: 'object', description: 'x'.repeat(65536) } })).toEqual({ ok: false, reason: 'inputSchema is larger than 64 KiB' });
  });

  test('measures the schema in UTF-8 bytes, not characters', () => {
    // 22,000 three-byte characters are 66,000 bytes: over the bound although far under it in length.
    expect(withTool({ inputSchema: { type: 'object', description: '€'.repeat(22000) } })).toEqual({ ok: false, reason: 'inputSchema is larger than 64 KiB' });
  });
});

test('a local name declared twice refuses the whole file', () => {
  expect(parseTools([TOOL, { ...TOOL }])).toEqual({ ok: false, reason: "tool 'list_rows' is declared more than once" });
});

src/lifecycle/tools/__tests__/agent-plug.source:
/**
 * @file Security pins (phase A) for the read-only plugin state an executable tool receives: the tool
 * port carries `get` only (never `set` or `delete`, even when the host hands over its full store), keys
 * pass the same shape check as the admin-surface state, the plugin cannot choose another plugin's or
 * workspace's keys (the projection scopes the host port by the calling plugin and workspace, and the
 * host receives the key alone), and a reader the module kept is revoked once the plugin is disabled.
 */
import { expect, test } from 'vitest';
import { createPluginContributionRegistry, pluginToolIdFor } from '@jini-ai/plugins/host';
import { createFakeSurfaceHost } from '../../../admin-surfaces/__tests__/surface-support.js';
import { openCapabilitySession, REVOKED_MESSAGE, type AgentPluginToolCapabilities, type AgentPluginToolCapabilityScope, createIssuedTokenMemories } from '../capabilities.js';
import type { LoadedAgentPluginTool } from '../definition.js';
import { createAgentPluginToolProjection } from '../projection.js';
import { fakeCapabilities, WORKSPACE_ID } from './support.js';

const KEY_MESSAGE = 'A settings key must be a short name of at most 128 characters.';
const SCHEMA = { type: 'object', additionalProperties: false, properties: {} };

/** Tool capabilities over the shared fake host: its full state store (get, set, delete) is what the host passes. */
function toolPort(fake: ReturnType<typeof createFakeSurfaceHost>) {
  return (scope: AgentPluginToolCapabilityScope): AgentPluginToolCapabilities => ({ ...fakeCapabilities(fake.log), state: fake.port(scope).state });
}

function session(state: AgentPluginToolCapabilities['state'], live: () => boolean = () => true) {
  return openCapabilitySession({ capabilities: { ...fakeCapabilities({ tokenRequests: [], requests: [] }), state }, isLive: live, issued: new Set() });
}

test('a tool\'s state port has get only, frozen, even when the host passes its full store', () => {
  const fake = createFakeSurfaceHost();
  const { state } = openCapabilitySession({ capabilities: toolPort(fake)({ pluginId: 'acme-office', workspaceId: WORKSPACE_ID }), isLive: () => true, issued: new Set() }).capabilities;
  expect(Object.keys(state)).toEqual(['get']);
  expect(Object.isFrozen(state)).toBe(true);
  expect('set' in state || 'delete' in state).toBe(false);
});

test.each(['', '../x', 'a b', 'k'.repeat(129), 7])('a tool state key %j outside the short-name shape is refused before the host sees it', async (key) => {
  const seen: unknown[] = [];
  const { capabilities } = session({ get: async (input) => { seen.push(input); return null; } });
  await expect(capabilities.state.get({ key: key as string })).rejects.toThrow(KEY_MESSAGE);
  expect(seen).toEqual([]);
});

test('the host receives the key alone: a plugin cannot name another plugin or workspace', async () => {
  const seen: unknown[] = [];
  const { capabilities } = session({ get: async (input, optional) => { seen.push([input, optional]); return 'v'; } });
  // Malformed input on purpose: extra scope fields a plugin might try to smuggle in.
  expect(await capabilities.state.get({ key: 'products', pluginId: 'other', workspaceId: 'w2' } as never, { pluginId: 'other' } as never)).toBe('v');
  expect(seen).toStrictEqual([[{ key: 'products' }, undefined]]);
});

const reader = (pluginId: string): LoadedAgentPluginTool => ({
  pluginId, descriptor: { name: 'flags', description: 'Read flags.', effect: 'read', module: 'tools/flags.mjs', inputSchema: SCHEMA },
  module: { invoke: async ({ capabilities }) => ({ products: await capabilities.state.get({ key: 'products' }) }) },
});

function projected(fake: ReturnType<typeof createFakeSurfaceHost>, loaded: readonly LoadedAgentPluginTool[]) {
  const registry = createPluginContributionRegistry({});
  const projection = createAgentPluginToolProjection({ issuedTokens: createIssuedTokenMemories(), registry, toolIdFor: pluginToolIdFor, capabilities: toolPort(fake) });
  projection.sync({ loaded, refusals: [] });
  const call = (pluginId: string, workspaceId: string) => {
    const snapshot = registry.list({}).find((candidate) => candidate.pluginId === pluginId)!;
    return snapshot.tools[0]!.handler({ pluginId, sdk: snapshot.sdk, auth: { access: 'member', workspaceId }, input: {} });
  };
  return { projection, call };
}

test('a tool reads only its own plugin\'s state in its own workspace', async () => {
  const fake = createFakeSurfaceHost();
  await fake.port({ pluginId: 'plugin-a', workspaceId: WORKSPACE_ID }).state.set({ key: 'products', value: { tables: true } });
  const { call } = projected(fake, [reader('plugin-a'), reader('plugin-b')]);
  expect(await call('plugin-a', WORKSPACE_ID)).toEqual({ products: { tables: true } });
  expect(await call('plugin-b', WORKSPACE_ID)).toEqual({ products: null });
  expect(await call('plugin-a', 'workspace-other')).toEqual({ products: null });
});

test('a state reader the module kept is revoked once the plugin is disabled', async () => {
  const fake = createFakeSurfaceHost();
  let kept: AgentPluginToolCapabilities['state'] | undefined;
  const keeper: LoadedAgentPluginTool = { ...reader('plugin-a'), module: { invoke: ({ capabilities }) => { kept = capabilities.state; return 'ok'; } } };
  const { projection, call } = projected(fake, [keeper]);
  expect(await call('plugin-a', WORKSPACE_ID)).toBe('ok');
  projection.sync({ loaded: [], refusals: [] });
  await expect(kept!.get({ key: 'products' })).rejects.toThrow(REVOKED_MESSAGE);
});

src/admin-surfaces/__tests__/surface-han.source:
/**
 * @file The one phase-A vertical-slice proof for plugin-supplied surface handlers: a neutral
 * "acme-office" fixture is installed, bundled and activated through the real lifecycle owners; the
 * real loaders admit its surface (data) and its handler module (executable); the host composes
 * `handlersFor` into the existing action dispatcher and `bootstrapData` into the bootstrap envelope,
 * and one declared action runs plugin code with injected fake capabilities. No network.
 */
import { expect, test } from 'vitest';
import { createIssuedTokenMemories } from '../../lifecycle/tools/capabilities.js';
import { createPluginContributionLoader } from '../../lifecycle/contribution-loader.js';
import { findTrustedPluginPackages, importContainedModule, readTrustedPluginFile } from '../../lifecycle/__tests__/test-support.js';
import { FAKE_TOKEN, installPlugin, WORKSPACE_ID, withWorkspace } from '../../lifecycle/tools/__tests__/support.js';
import { createFakeSurfaceHost } from './surface-support.js';
import {
  createAdminSurfaceActionDispatcher, createAdminSurfaceBootstrap, createAdminSurfaceHandlerHost,
  defineAdminSurfaceContribution, defineAdminSurfaceHandlerContribution, readAdminSurfaceFile,
} from '../index.js';

const FILENAME = 'host-admin-surfaces.json';
const HANDLERS = `export default {
  actions: {
    async 'save-selection'({ input, capabilities, context }) {
      const token = await capabilities.connections.getAccessToken({ connectionId: context.connectionIds[0] });
      const response = await capabilities.http.fetch({ url: 'https://api.example.test/files/' + input.resourceId },
        { method: 'GET', headers: { authorization: 'Bearer ' + token } });
      return { saved: response.status === 200, workspace: context.workspaceId };
    },
  },
  async bootstrap({ capabilities }) {
    return { accessToken: await capabilities.connections.getAccessToken({ connectionId: 'conn-1' }), appId: 'public-app-id' };
  },
};
`;
const SURFACES = JSON.stringify({ schemaVersion: 1, surfaces: [{
  id: 'resource-chooser', title: 'Choose a file', entry: 'surface/index.html', files: ['surface/app.mjs'], handlerModule: 'server/handlers.mjs', connections: [{ id: 'conn-1' }],
  actions: [{ name: 'save-selection',
    input: { type: 'object', properties: { resourceId: { type: 'string', maxLength: 128 } }, required: ['resourceId'] },
    result: { type: 'object', properties: { saved: { type: 'boolean' }, workspace: { type: 'string' } }, required: ['saved'] } }],
  bootstrap: { type: 'object', properties: { accessToken: { type: 'string' }, appId: { type: 'string' } }, required: ['accessToken', 'appId'] },
}] });

test('an acme-style plugin surface runs its own handler and bootstrap provider through the host dispatcher', async () => {
  await withWorkspace(async (workspaceRoot) => {
    await installPlugin({ workspaceRoot, pluginId: 'acme-office', files: {
      [FILENAME]: SURFACES, 'surface/index.html': '<!doctype html><script type="module" src="app.mjs"></script>', 'surface/app.mjs': 'export {};', 'server/handlers.mjs': HANDLERS,
    } });
    const loader = createPluginContributionLoader({
      findPackages: (query) => findTrustedPluginPackages(query),
      readFile: ({ plugin, filename }) => readTrustedPluginFile(plugin, filename),
      importModule: ({ plugin, modulePath }) => importContainedModule(plugin, modulePath),
    });
    const { log, port } = createFakeSurfaceHost();
    const host = createAdminSurfaceHandlerHost({ hostKind: 'hosted', issuedTokens: createIssuedTokenMemories(), capabilities: port });

    const surfaces = await loader.loadPluginContributions({ workspaceId: WORKSPACE_ID, definition: defineAdminSurfaceContribution({ filename: FILENAME }) });
    const handlerLoad = await loader.loadPluginContributions({ workspaceId: WORKSPACE_ID, definition: defineAdminSurfaceHandlerContribution({ filename: FILENAME }) });
    expect([...surfaces.refusals, ...host.sync({ loaded: handlerLoad.items, refusals: handlerLoad.refusals }).refusals]).toEqual([]);
    const [surface] = surfaces.items;
    if (!surface) throw new Error('the fixture surface was not admitted');
    expect(await readAdminSurfaceFile({ surface, path: 'server/handlers.mjs', readFile: ({ plugin, filename }) => readTrustedPluginFile(plugin, filename) })).toEqual({ ok: false, reason: 'not-declared' });

    const context = { workspaceId: WORKSPACE_ID, principalId: 'admin-1', pluginId: 'acme-office', surfaceId: 'resource-chooser' };
    const bootstrap = createAdminSurfaceBootstrap({ surfaceId: surface.descriptor.id, data: await host.bootstrapData({ context }), nowMs: 1_000 });
    expect(bootstrap).toEqual({ surfaceId: 'resource-chooser', issuedAt: 1_000, expiresAt: 61_000, data: { accessToken: FAKE_TOKEN, appId: 'public-app-id' } });

    const dispatcher = createAdminSurfaceActionDispatcher({ descriptor: surface.descriptor, handlers: host.handlersFor({ pluginId: 'acme-office', surfaceId: 'resource-chooser' }) });
    expect(await dispatcher.dispatch({ action: 'save-selection', payload: { resourceId: 'file-42' }, context }))
      .toEqual({ ok: true, result: { saved: true, workspace: WORKSPACE_ID } });
    expect(log.tokenRequests).toEqual(['conn-1', 'conn-1']);
    expect(log.requests).toEqual([{ url: 'https://api.example.test/files/file-42', headers: { authorization: `Bearer ${FAKE_TOKEN}` } }]);
  });
});

/**
 * @file Unit tests for the plugin handler host paths the security suite leaves at their edges: the
 * `fail` helper's retryable flag and 300-character message cap, a declared action the module does
 * not answer staying unavailable, and a changed declaration (same module object) starting a new
 * generation that revokes the old handlers. The host runs over the shared typed fake capabilities.
 */
import { describe, expect, test } from 'vitest';
import { WORKSPACE_ID } from '../../lifecycle/tools/__tests__/support.js';
import { createIssuedTokenMemories } from '../../lifecycle/tools/capabilities.js';
import { createAdminSurfaceActionDispatcher } from '../action-dispatcher.js';
import { parseAdminSurfacesFile, type AdminSurfaceDescriptor } from '../descriptor.js';
import { ADMIN_SURFACE_PLUGIN_DISABLED_MESSAGE, createAdminSurfaceHandlerHost, type AdminSurfaceHandlerModule, type LoadedAdminSurfaceHandlers } from '../surface-handlers.js';
import { createFakeSurfaceHost } from './surface-support.js';

const PLUGIN = 'acme-office';
const CONTEXT = { workspaceId: WORKSPACE_ID, principalId: 'admin-1', pluginId: PLUGIN, surfaceId: 'settings' };
const INPUT = { type: 'object' } as const;
const RESULT = { type: 'boolean' } as const;

function descriptorOf(overrides: Record<string, unknown> = {}): AdminSurfaceDescriptor & { readonly handlerModule: string } {
  const raw = JSON.stringify({ schemaVersion: 1, surfaces: [{
    id: 'settings', title: 'Settings', entry: 'surface/index.html', handlerModule: 'server/handlers.mjs',
    actions: [{ name: 'save', input: INPUT, result: RESULT }, { name: 'reset', input: INPUT, result: RESULT }], ...overrides,
  }] });
  const parsed = parseAdminSurfacesFile({ raw });
  if (!parsed.ok) throw new Error(parsed.reason);
  return parsed.descriptors[0] as AdminSurfaceDescriptor & { readonly handlerModule: string };
}

function hostWith(entries: readonly LoadedAdminSurfaceHandlers[]) {
  const { port } = createFakeSurfaceHost();
  const host = createAdminSurfaceHandlerHost({ hostKind: 'desktop', issuedTokens: createIssuedTokenMemories(), capabilities: port });
  expect(host.sync({ loaded: entries, refusals: [] }).refusals).toEqual([]);
  return host;
}

describe('the fail helper', () => {
  test('keeps an explicit retryable flag', async () => {
    const module: AdminSurfaceHandlerModule = { actions: { save: ({ fail }) => { throw fail({ code: 'rate-limited', message: 'Try again in a minute.' }, { retryable: true }); } } };
    const handler = hostWith([{ descriptor: descriptorOf(), pluginId: PLUGIN, module }]).handlersFor({ pluginId: PLUGIN, surfaceId: 'settings' }).save!;
    await expect(handler({ payload: {}, context: CONTEXT })).rejects.toMatchObject({ code: 'rate-limited', retryable: true });
  });

  test('cuts a plugin failure message to 300 characters', async () => {
    const module: AdminSurfaceHandlerModule = { actions: { save: ({ fail }) => { throw fail({ code: 'sheet-missing', message: 'm'.repeat(400) }); } } };
    const handler = hostWith([{ descriptor: descriptorOf(), pluginId: PLUGIN, module }]).handlersFor({ pluginId: PLUGIN, surfaceId: 'settings' }).save!;
    await expect(handler({ payload: {}, context: CONTEXT })).rejects.toMatchObject({ code: 'sheet-missing', message: 'm'.repeat(300), retryable: false });
  });
});

test('a declared action the module does not answer stays unavailable', async () => {
  const descriptor = descriptorOf();
  const host = hostWith([{ descriptor, pluginId: PLUGIN, module: { actions: { save: () => true } } }]);
  const handlers = host.handlersFor({ pluginId: PLUGIN, surfaceId: 'settings' });
  expect(Object.keys(handlers)).toEqual(['save']);
  const dispatcher = createAdminSurfaceActionDispatcher({ descriptor, handlers });
  await expect(dispatcher.dispatch({ action: 'reset', payload: {}, context: CONTEXT }))
    .resolves.toEqual({ ok: false, error: { code: 'action-unavailable', message: 'This action is not available on this host.', retryable: false } });
});

test('a changed declaration with the same module object starts a new generation and revokes the old handlers', async () => {
  const module: AdminSurfaceHandlerModule = { actions: { save: () => true } };
  const { port } = createFakeSurfaceHost();
  const host = createAdminSurfaceHandlerHost({ hostKind: 'hosted', issuedTokens: createIssuedTokenMemories(), capabilities: port });
  host.sync({ loaded: [{ descriptor: descriptorOf(), pluginId: PLUGIN, module }], refusals: [] });
  const old = host.handlersFor({ pluginId: PLUGIN, surfaceId: 'settings' }).save!;
  host.sync({ loaded: [{ descriptor: descriptorOf({ title: 'Settings (renamed)' }), pluginId: PLUGIN, module }], refusals: [] });
  await expect(old({ payload: {}, context: CONTEXT })).rejects.toMatchObject({ code: 'plugin-disabled', message: ADMIN_SURFACE_PLUGIN_DISABLED_MESSAGE });
  await expect(host.handlersFor({ pluginId: PLUGIN, surfaceId: 'settings' }).save!({ payload: {}, context: CONTEXT })).resolves.toBe(true);
});

