/**
 * @file Unit tests for admin-surface capability bounds the security suite leaves at their edges:
 * refusal text truncates plugin-supplied names to 64 characters, start parameter values are capped
 * at 2048 characters, at most 16 scope sets are accepted, and a staged account switch label is passed
 * through. The host is the shared typed fake; no network.
 */
import { describe, expect, test } from 'vitest';
import { WORKSPACE_ID } from '../../lifecycle/tools/__tests__/support.js';
import type { AdminSurfaceCapabilityDeclarations } from '../capability-declarations.js';
import { openAdminSurfaceCapabilitySession, type AdminSurfaceConnectionStatus } from '../surface-capabilities.js';
import { createFakeSurfaceHost } from './surface-support.js';

const DECLARED: AdminSurfaceCapabilityDeclarations = {
  connections: [{ id: 'account', startParams: ['selection-mode'], callbackFields: [] }],
  publicConfig: ['ACME_APP_ID'],
};

function open(optional: { readonly status?: Partial<AdminSurfaceConnectionStatus> } = {}) {
  const fake = createFakeSurfaceHost({ config: { ACME_APP_ID: 'app-123' }, ...(optional.status && { status: optional.status }) });
  const session = openAdminSurfaceCapabilitySession(
    { capabilities: fake.port({ pluginId: 'acme-office', workspaceId: WORKSPACE_ID }), isLive: () => true, declared: DECLARED, issued: new Set() },
    { actorId: 'admin-1' },
  );
  return { ...session, log: fake.log };
}

const LONG = `x${'y'.repeat(99)}`;

describe('refusal text names at most 64 characters of a plugin-supplied name', () => {
  test('an undeclared connection id', async () => {
    await expect(open().capabilities.connections.status({ connectionId: LONG }))
      .rejects.toThrow(`This admin surface does not declare connection '${LONG.slice(0, 64)}', so its handlers cannot use it.`);
  });

  test('an undeclared public config name', async () => {
    await expect(open().capabilities.publicConfig.get({ name: LONG }))
      .rejects.toThrow(`This admin surface does not declare public config '${LONG.slice(0, 64)}'. Declare it in the surface's publicConfig.`);
  });
});

describe('begin bounds', () => {
  test('a start parameter value of exactly 2048 characters reaches the host', async () => {
    const session = open();
    await session.capabilities.connections.begin({ connectionId: 'account', action: 'connect' }, { startParams: { 'selection-mode': 'v'.repeat(2048) } });
    expect(session.log.calls).toHaveLength(1);
  });

  test('a start parameter value of 2049 characters is refused before the host sees it', async () => {
    const session = open();
    await expect(session.capabilities.connections.begin({ connectionId: 'account', action: 'connect' }, { startParams: { 'selection-mode': 'v'.repeat(2049) } }))
      .rejects.toThrow("Start parameter 'selection-mode' must be a string of at most 2048 characters.");
    expect(session.log.calls).toEqual([]);
  });

  test('16 scope sets are accepted and 17 are refused', async () => {
    const session = open();
    const ids = (count: number) => Array.from({ length: count }, (_, index) => `set-${index}`);
    await session.capabilities.connections.begin({ connectionId: 'account', action: 'add-scopes' }, { scopeSetIds: ids(16) });
    await expect(session.capabilities.connections.begin({ connectionId: 'account', action: 'add-scopes' }, { scopeSetIds: ids(17) }))
      .rejects.toThrow('Scope sets must be at most 16 short ids.');
    expect(session.log.calls).toHaveLength(1);
  });
});

test('a staged switch reports the account it would move to', async () => {
  const session = open({ status: { pendingSwitchAccountLabel: 'other@example.test' } });
  await expect(session.capabilities.connections.status({ connectionId: 'account' })).resolves.toMatchObject({ pendingSwitchAccountLabel: 'other@example.test' });
});

src/lifecycle/tools/__tests__/definition.source:
/**
 * @file Unit tests for the tool contribution definition: it is an executable definition on the
 * host-chosen filename, imports exactly the declared module, and refuses a module export that is
 * not a tool module, naming the tool and plugin. The import port is a typed fake; nothing runs.
 */
import { describe, expect, test } from 'vitest';
import type { PluginModuleImportPort } from '../../contribution-loader.js';
import type { TrustedPluginPackage } from '../../trusted-plugin-files.js';
import { defineAgentPluginToolContribution } from '../definition.js';
import type { AgentPluginToolDescriptor } from '../manifest.js';

const PLUGIN: TrustedPluginPackage = { pluginId: 'acme-office', packageRoot: '/plugins/acme-office' };
const DESCRIPTOR: AgentPluginToolDescriptor = { name: 'list_rows', description: 'Lists rows.', effect: 'read', module: 'tools/list.mjs', inputSchema: { type: 'object' } };

function load(exported: unknown) {
  const requested: string[] = [];
  const importModule: PluginModuleImportPort = async ({ modulePath }) => { requested.push(modulePath); return { exported }; };
  const definition = defineAgentPluginToolContribution({ filename: 'host-agent-tools.json' });
  return { requested, loaded: definition.load({ plugin: PLUGIN, descriptor: DESCRIPTOR, importModule }) };
}

test('is an executable contribution on the host-chosen filename, parsed by the tools parser', () => {
  const definition = defineAgentPluginToolContribution({ filename: 'host-agent-tools.json' });
  expect(definition).toMatchObject({ filename: 'host-agent-tools.json', contribution: 'agent tools', kind: 'executable' });
  expect(definition.parse({ raw: '{}' })).toEqual({ ok: false, reason: 'schemaVersion must be 1' });
});

describe('module export validation', () => {
  test('a valid tool module loads, importing the declared module path', async () => {
    const module = { invoke: () => 'ok' };
    const { requested, loaded } = load(module);
    await expect(loaded).resolves.toEqual({ descriptor: DESCRIPTOR, pluginId: 'acme-office', module });
    expect(requested).toEqual(['tools/list.mjs']);
  });

  test('a module with a describeAffectedResources function loads', async () => {
    const module = { invoke: () => 'ok', describeAffectedResources: () => ['row 1'] };
    await expect(load(module).loaded).resolves.toMatchObject({ module });
  });

  test('a null export is refused, naming the tool and plugin', async () => {
    await expect(load(null).loaded).resolves.toBe("agent tool 'list_rows' from 'acme-office' was not loaded: its module's default export is not an object");
  });

  test('a function export is refused as not an object', async () => {
    await expect(load(() => 'ok').loaded).resolves.toBe("agent tool 'list_rows' from 'acme-office' was not loaded: its module's default export is not an object");
  });

  test('an export without invoke() is refused', async () => {
    await expect(load({ run: () => 'ok' }).loaded).resolves.toBe("agent tool 'list_rows' from 'acme-office' was not loaded: its module's default export has no invoke()");
  });

  test('a non-function describeAffectedResources is refused', async () => {
    await expect(load({ invoke: () => 'ok', describeAffectedResources: ['row 1'] }).loaded)
      .resolves.toBe("agent tool 'list_rows' from 'acme-office' was not loaded: describeAffectedResources must be a function");
  });
});

src/lifecycle/tools/__tests__/agent-plug.source:
/**
 * @file The one vertical-slice proof: a real installed, bundled, active plugin ships a host-named
 * tool file and an `.mjs` module; the trusted loader imports it, the projection registers it in a
 * real ToolRegistry under `p_<plugin>__<local>`, and a call runs with injected fake capabilities.
 */
import { expect, test } from 'vitest';
import { createHarness, FAKE_TOKEN, installPlugin, toolsFile, TOOLS_FILENAME, withWorkspace } from './support.js';

const APPEND_MODULE = `export default {
  async invoke({ input, capabilities }) {
    const token = await capabilities.connections.getAccessToken({ connectionRef: input.connectionRef });
    const response = await capabilities.http.fetch({ url: 'https://api.example.test/tables/' + input.table + '/rows' },
      { method: 'POST', headers: { authorization: 'Bearer ' + token }, body: JSON.stringify({ values: input.values }) });
    return { status: response.status, appended: input.values.length };
  },
  describeAffectedResources({ input }) { return ['table ' + input.table]; },
};
`;

test('load a fake plugin .mjs tool, project it, invoke it with injected capabilities and get its result', async () => {
  await withWorkspace(async (workspaceRoot) => {
    await installPlugin({ workspaceRoot, pluginId: 'acme-office', files: {
      [TOOLS_FILENAME]: toolsFile([{ name: 'append_rows', description: 'Append rows to a table.', effect: 'write', module: 'tools/append-rows.mjs',
        inputSchema: { type: 'object', required: ['connectionRef', 'table', 'values'], additionalProperties: false, properties: {
          connectionRef: { type: 'string' }, table: { type: 'string' }, values: { type: 'array', items: { type: 'string' } } } } }]),
      'tools/append-rows.mjs': APPEND_MODULE,
    } });
    const harness = createHarness();

    expect(await harness.refresh()).toEqual([]);
    expect(harness.tools.has({ toolId: 'p_acme_office__append_rows' })).toBe(true);
    const input = { connectionRef: 'conn-1', table: 'leads', values: ['a', 'b'] };
    expect(await harness.projection.describeAffectedResources({ toolId: 'p_acme_office__append_rows', input })).toEqual({ effect: 'write', resources: ['table leads'] });

    expect(await harness.invoke('p_acme_office__append_rows', input)).toEqual({ status: 200, appended: 2 });
    expect(harness.log.tokenRequests).toEqual(['conn-1']);
    expect(harness.log.requests).toEqual([{ url: 'https://api.example.test/tables/leads/rows',
      headers: { authorization: `Bearer ${FAKE_TOKEN}` }, body: '{"values":["a","b"]}' }]);
  });
});

src/lifecycle/tools/__tests__/capabiliti.source:
/**
 * @file Characterization pin written green on the unmodified `../capabilities.ts` before the
 * artifacts capability became optional: a host that gives an artifact store still gets it wrapped
 * (a frozen gate-guarded writer that passes the call through and is revoked with the session).
 */
import { expect, test } from 'vitest';
import { createIssuedTokenMemories, openCapabilitySession, REVOKED_MESSAGE } from '../capabilities.js';
import { fakeCapabilities } from './support.js';

test('a host artifact store is wrapped: frozen, passed through while live, revoked after', async () => {
  let live = true;
  const host = fakeCapabilities({ tokenRequests: [], requests: [] });
  const { capabilities } = openCapabilitySession({ capabilities: host, isLive: () => live, issued: createIssuedTokenMemories().forPlugin({ pluginId: 'acme-office' }) });
  expect(capabilities.artifacts).not.toBe(host.artifacts);
  expect(Object.isFrozen(capabilities.artifacts)).toBe(true);
  expect(await capabilities.artifacts!.write({ name: 'a.csv', mediaType: 'text/csv', content: 'a' })).toEqual({ artifactRef: 'artifact:a.csv' });
  live = false;
  await expect(capabilities.artifacts!.write({ name: 'a.csv', mediaType: 'text/csv', content: 'a' })).rejects.toThrow(REVOKED_MESSAGE);
});

